INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C1','math',6,2,'u5',2,'원주 — 원의 중심·반지름·지름을 되짚고 원의 둘레를 원주라 하며, 원 안 정육각형(지름의 3배)과 원 밖 정사각형(지름의 4배)으로 원주가 지름의 3배보다 길고 4배보다 짧음을 알기',ARRAY['6수03-11']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C2','math',6,2,'u5',3,'원주율 — 원의 지름에 대한 원주의 비율이 모든 원에서 일정함을 알고 (원주율) = (원주) ÷ (지름), 끝없이 이어지는 소수라 3.14로 어림해 쓰기',ARRAY['6수03-11']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C3','math',6,2,'u5',4,'원주 구하기 — (원주) = (지름) × (원주율), 반지름만 알면 2를 먼저 곱해 지름을 만든 뒤 원주율을 곱하고, 굴러간 거리 문제에 쓰기',ARRAY['6수03-11']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C4','math',6,2,'u5',4,'지름·반지름 구하기 — (지름) = (원주) ÷ (원주율)로 곱셈을 되짚어 지름과 반지름을 구하고, 원주·지름·반지름이 섞인 원의 크기를 견주기',ARRAY['6수03-11']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C5','math',6,2,'u5',5,'원의 넓이 어림하기 — 모눈 칸(온전한 칸·걸친 칸)과 원 안·밖 정사각형으로 넓이가 들어갈 범위를 찾고, (반지름) × (반지름)의 2배와 4배 사이(약 3배)임을 알기',ARRAY['6수03-12']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C6','math',6,2,'u5',6,'원의 넓이 구하기 — 원을 한없이 잘라 이어 붙인 직사각형(가로 원주의 반, 세로 반지름)으로 (원의 넓이) = (반지름) × (반지름) × (원주율)을 이끌어 내고 쓰기',ARRAY['6수03-12']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C7','math',6,2,'u5',7,'원의 넓이 활용 — 고리 모양은 큰 원에서 작은 원을 빼고, 잘라 옮겨도 넓이는 그대로이며, 반원·사분원·조각은 원의 넓이를 나누어 구하기',ARRAY['6수03-12']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u5-C8','math',6,2,'u5',8,'반지름과 넓이의 관계 — 반지름이 □배가 되면 원주는 □배, 원의 넓이는 반지름을 두 번 곱하므로 □ × □배가 됨을 알고 쓰기',ARRAY['6수03-12']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X01','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C6']::text[],'원의 중심·반지름·지름을 혼동하거나 (지름) = (반지름) × 2 관계를 거꾸로 쓴다','지름은 반지름 두 개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X02','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2']::text[],'원주를 지름·반지름 같은 선분과 혼동하거나, 원주가 지름의 3배(4배)와 정확히 같다고 단정하거나, 다각형처럼 변을 더해 구하려 한다','3배보다 길고 4배보다 짧아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X03','math',6,'u5',ARRAY['M6-2-u5-C1']::text[],'원 안 정육각형의 한 변을 지름으로, 원 밖 정사각형의 한 변을 반지름으로 바꾸어 본다','육각형 한 변 = 반지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X04','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'원주율을 (지름) ÷ (원주)나 (원주) ÷ (반지름)으로 구한다(기준량을 잘못 잡음)','기준량은 지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X05','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'원이 커지면 원주율도 커진다고, 또는 원마다 원주율이 다르다고 본다','원주율은 늘 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X06','math',6,'u5',ARRAY['M6-2-u5-C2']::text[],'3.14가 원주율의 정확한 값이라 보거나, 잰 값의 작은 차이를 원주율이 달라서라고 본다','3.14는 어림한 값') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X07','math',6,'u5',ARRAY['M6-2-u5-C3','M6-2-u5-C4']::text[],'반지름만 주어졌을 때 2를 곱하지 않고 반지름에 바로 원주율을 곱한다','반지름 × 2부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X08','math',6,'u5',ARRAY['M6-2-u5-C3','M6-2-u5-C4']::text[],'원주를 구할 때 나누거나 지름을 구할 때 곱하는 등 곱셈·나눗셈을 거꾸로 쓴다','지름 × 3.14 = 원주') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X10','math',6,'u5',ARRAY['M6-2-u5-C5']::text[],'넓이 어림에서 온전한 칸과 걸친 칸을 바꾸거나, 범위를 벗어난 값을 고르거나, 어림을 정확한 값으로 단정한다','어림은 범위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X11','math',6,'u5',ARRAY['M6-2-u5-C5']::text[],'원 안·밖 정사각형의 넓이가 (반지름) × (반지름)의 몇 배인지(2배·4배) 혼동한다','안은 2개, 밖은 4개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X12','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'원의 넓이를 원주 식((지름) × (원주율))으로 구하거나 원주와 넓이 식을 바꾸어 쓴다','넓이는 반지름을 두 번') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X13','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C7']::text[],'원의 넓이를 구할 때 반지름 대신 지름을 두 번 곱한다','지름 말고 반지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X14','math',6,'u5',ARRAY['M6-2-u5-C6','M6-2-u5-C8']::text[],'원의 넓이를 구할 때 반지름을 한 번만 곱한다((반지름) × (원주율))','반지름을 두 번') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X15','math',6,'u5',ARRAY['M6-2-u5-C6']::text[],'원을 잘라 이어 붙인 직사각형의 가로를 원주 전체로, 세로를 지름으로 본다','가로는 원주의 반') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X16','math',6,'u5',ARRAY['M6-2-u5-C7']::text[],'고리 모양의 넓이를 반지름의 차로 만든 원의 넓이로 구하거나 작은 원을 빼지 않는다','큰 원 - 작은 원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X17','math',6,'u5',ARRAY['M6-2-u5-C7']::text[],'잘라 옮기면 넓이가 변한다고 보거나, 반원·사분원·조각에서 나누기를 빠뜨리거나 잘못 나눈다','몇 조각 중 하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X18','math',6,'u5',ARRAY['M6-2-u5-C2','M6-2-u5-C8']::text[],'반지름(지름)이 □배일 때 원주·넓이가 몇 배인지 잘못 본다(넓이도 □배, 원주도 □ × □배, 차이로 늘리기)','넓이는 □ × □배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X19','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C5','M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔알맞은, 반지름↔지름, 큰↔작은','물음의 「잘못·않은」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u5-X20','math',6,'u5',ARRAY['M6-2-u5-C1','M6-2-u5-C2','M6-2-u5-C3','M6-2-u5-C4','M6-2-u5-C5','M6-2-u5-C6','M6-2-u5-C7','M6-2-u5-C8']::text[],'소수 곱셈·나눗셈의 자릿수나 단위(cm·m)를 바꾸는 계산을 잘못한다','어림해서 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#1','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'mc','auto','원의 둘레를 무엇이라고 하나요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심과 원 위의 한 점을 이은 선분을 반지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심을 지나도록 원 위의 두 점을 이은 선분을 지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#2','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','원 모양 얼음판의 지름은 16 m예요. 이 얼음판의 반지름은 몇 m인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"원 모양 얼음판의 지름은 16 m예요. 이 얼음판의 반지름은 몇 m인가요?","answer":["8"],"explanation":["반지름은 지름의 반이에요.","(반지름) = (지름) ÷ 2예요.","16 ÷ 2 = 8 — 반지름은 8 m예요."],"variant_rule":{"alt":[{"stem":"원 모양 얼음판의 지름은 24 m예요. 이 얼음판의 반지름은 몇 m인가요?","answer":["12"],"explanation":["반지름은 지름의 반이에요.","(반지름) = (지름) ÷ 2예요.","24 ÷ 2 = 12 — 반지름은 12 m예요."]},{"stem":"원 모양 얼음판의 지름은 30 m예요. 이 얼음판의 반지름은 몇 m인가요?","answer":["15"],"explanation":["반지름은 지름의 반이에요.","(반지름) = (지름) ÷ 2예요.","30 ÷ 2 = 15 — 반지름은 15 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#3','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["16"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","8 × 2 = 16 — 지름은 16 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["12"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","6 × 2 = 12 — 지름은 12 cm예요."]},{"stem":"반지름이 9 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["18"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","9 × 2 = 18 — 지름은 18 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#4','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','지름이 4 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"지름이 4 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["12"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 2이고 변이 6개이니 둘레는 2 × 6이에요.","2 × 6 = 12 — 지름의 3배인 12 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["18"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 3이고 변이 6개이니 둘레는 3 × 6이에요.","3 × 6 = 18 — 지름의 3배인 18 cm예요."]},{"stem":"지름이 8 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["24"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 4이고 변이 6개이니 둘레는 4 × 6이에요.","4 × 6 = 24 — 지름의 3배인 24 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#5','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'sa','auto','지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["16"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 4 cm이고 변이 4개예요.","4 × 4 = 16 — 지름의 4배인 16 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["24"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 6 cm이고 변이 4개예요.","6 × 4 = 24 — 지름의 4배인 24 cm예요."]},{"stem":"지름이 7 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["28"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 7 cm이고 변이 4개예요.","7 × 4 = 28 — 지름의 4배인 28 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#6','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'mc','auto','원 안에 꼭 맞는 정육각형의 한 변은 원의 무엇과 길이가 같나요?',ARRAY['M6-2-u5-X03','M6-2-u5-X02']::text[],true,'{"seq":6,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"원 안에 꼭 맞는 정육각형의 한 변은 원의 무엇과 길이가 같나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M6-2-u5-X03"},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"원주의 반","mis":"M6-2-u5-X02"}],"explanation":["정육각형은 원의 중심을 꼭짓점으로 하는 정삼각형 6개로 나뉘어요.","정삼각형의 두 변이 반지름이니 정육각형의 한 변도 반지름과 같아요.","그래서 정육각형의 둘레는 반지름의 6배, 곧 지름의 3배예요."],"variant_rule":{"alt":[{"stem":"원 밖에 꼭 맞는 정사각형의 한 변은 원의 무엇과 길이가 같나요?","options":[{"t":"지름","correct":true},{"t":"반지름","mis":"M6-2-u5-X03"},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"원주의 반","mis":"M6-2-u5-X02"}],"explanation":["정사각형이 원을 꼭 감싸면 마주 보는 두 변 사이가 원의 지름만큼 떨어져 있어요.","그래서 정사각형의 한 변은 지름과 같아요.","정사각형의 둘레는 지름의 4배예요."]},{"stem":"원 안에 꼭 맞는 정육각형의 둘레는 원의 지름의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"6배","mis":"M6-2-u5-X03"},{"t":"2배","mis":"M6-2-u5-X03"},{"t":"4배","mis":"M6-2-u5-X03"}],"explanation":["정육각형의 한 변은 반지름과 같아요.","변이 6개이니 둘레는 반지름의 6배예요.","반지름 2개가 지름이니 반지름의 6배는 지름의 3배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#7','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'mc','auto','지름이 4 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":7,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"지름이 4 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"12 cm보다 길고 16 cm보다 짧아요","correct":true},{"t":"8 cm보다 길고 12 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"16 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 12 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 12 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 16 cm예요.","원주는 그 사이 — 12 cm보다 길고 16 cm보다 짧아요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"18 cm보다 길고 24 cm보다 짧아요","correct":true},{"t":"12 cm보다 길고 18 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"24 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 18 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 18 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 24 cm예요.","원주는 그 사이 — 18 cm보다 길고 24 cm보다 짧아요."]},{"stem":"지름이 10 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"30 cm보다 길고 40 cm보다 짧아요","correct":true},{"t":"20 cm보다 길고 30 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"40 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 30 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 30 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 40 cm예요.","원주는 그 사이 — 30 cm보다 길고 40 cm보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#8','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'ox','auto','원주는 지름의 정확히 3배예요.',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":8,"concept":"M6-2-u5-C1","difficulty":2,"kind":"ox","stem":"원주는 지름의 정확히 3배예요.","answer":"X","reason_options":[{"t":"원주는 원 안 정육각형의 둘레(지름의 3배)보다 길기 때문에","correct":true},{"t":"원 안 정육각형의 둘레가 지름의 3배이기 때문에","mis":"M6-2-u5-X02"}],"mis":"M6-2-u5-X02","explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."],"variant_rule":{"alt":[{"stem":"원주는 원 밖에 꼭 맞는 정사각형의 둘레보다 짧아요.","answer":"O","reason_options":[{"t":"꺾인 선보다 원의 굽은 선이 더 짧기 때문에","correct":true},{"t":"정사각형의 한 변이 반지름과 같기 때문에","mis":"M6-2-u5-X03"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]},{"stem":"원의 둘레도 다각형처럼 변의 길이를 더해 구할 수 있어요.","answer":"X","reason_options":[{"t":"원에는 곧은 변이 하나도 없기 때문에","correct":true},{"t":"원의 변은 지름 하나뿐이라서 지름을 두 번 더하면 되기 때문에","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#9','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',2,'mc','auto','지름이 4 cm인 원의 둘레에 맞추어 지름 막대를 이어 붙였어요. 3개로는 못 미치고 4개면 넘어섰어요. 이것으로 알 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":9,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"지름이 4 cm인 원의 둘레에 맞추어 지름 막대를 이어 붙였어요. 3개로는 못 미치고 4개면 넘어섰어요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"원주는 지름의 3배보다 길고 4배보다 짧아요","correct":true},{"t":"원주는 지름의 3배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름의 4배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름보다 짧아요","mis":"M6-2-u5-X02"}],"explanation":["지름 막대 3개는 12 cm, 4개는 16 cm예요.","3개로는 못 미쳤으니 원주는 12 cm보다 길어요.","4개면 넘어섰으니 16 cm보다 짧아요 — 지름의 3배와 4배 사이예요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원의 둘레에 맞추어 지름 막대를 이어 붙였어요. 3개로는 못 미치고 4개면 넘어섰어요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"원주는 지름의 3배보다 길고 4배보다 짧아요","correct":true},{"t":"원주는 지름의 3배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름의 4배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름보다 짧아요","mis":"M6-2-u5-X02"}],"explanation":["지름 막대 3개는 18 cm, 4개는 24 cm예요.","3개로는 못 미쳤으니 원주는 18 cm보다 길어요.","4개면 넘어섰으니 24 cm보다 짧아요 — 지름의 3배와 4배 사이예요."]},{"stem":"지름이 5 cm인 원의 둘레에 맞추어 지름 막대를 이어 붙였어요. 3개로는 못 미치고 4개면 넘어섰어요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"원주는 지름의 3배보다 길고 4배보다 짧아요","correct":true},{"t":"원주는 지름의 3배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름의 4배와 정확히 같아요","mis":"M6-2-u5-X02"},{"t":"원주는 지름보다 짧아요","mis":"M6-2-u5-X02"}],"explanation":["지름 막대 3개는 15 cm, 4개는 20 cm예요.","3개로는 못 미쳤으니 원주는 15 cm보다 길어요.","4개면 넘어섰으니 20 cm보다 짧아요 — 지름의 3배와 4배 사이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_basic#10','math',6,2,'u5','L02','g6_2_math_u5_L02_basic','lesson_basic','M6-2-u5-C1',3,'mc','auto','지름이 10 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":10,"concept":"M6-2-u5-C1","difficulty":3,"kind":"mc","stem":"지름이 10 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"29 cm","mis":"M6-2-u5-X02"},{"t":"42 cm","mis":"M6-2-u5-X02"},{"t":"10 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 10 cm이면 원주는 30 cm와 40 cm 사이예요.","보기 가운데 그 사이에 있는 것은 31.4 cm뿐이에요."],"variant_rule":{"alt":[{"stem":"지름이 6 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"17 cm","mis":"M6-2-u5-X02"},{"t":"26 cm","mis":"M6-2-u5-X02"},{"t":"6 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 6 cm이면 원주는 18 cm와 24 cm 사이예요.","보기 가운데 그 사이에 있는 것은 18.84 cm뿐이에요."]},{"stem":"지름이 20 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"62.8 cm","correct":true},{"t":"59 cm","mis":"M6-2-u5-X02"},{"t":"82 cm","mis":"M6-2-u5-X02"},{"t":"20 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 20 cm이면 원주는 60 cm와 80 cm 사이예요.","보기 가운데 그 사이에 있는 것은 62.8 cm뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#1','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',2,'sa','auto','지름이 10 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 10 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["30"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 5이고 변이 6개이니 둘레는 5 × 6이에요.","5 × 6 = 30 — 지름의 3배인 30 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 6이고 변이 6개이니 둘레는 6 × 6이에요.","6 × 6 = 36 — 지름의 3배인 36 cm예요."]},{"stem":"지름이 14 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["42"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 7이고 변이 6개이니 둘레는 7 × 6이에요.","7 × 6 = 42 — 지름의 3배인 42 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#2','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',2,'mc','auto','지름이 8 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":2,"kind":"mc","stem":"지름이 8 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"23 cm","mis":"M6-2-u5-X02"},{"t":"34 cm","mis":"M6-2-u5-X02"},{"t":"8 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 8 cm이면 원주는 24 cm와 32 cm 사이예요.","보기 가운데 그 사이에 있는 것은 25.12 cm뿐이에요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"35 cm","mis":"M6-2-u5-X02"},{"t":"50 cm","mis":"M6-2-u5-X02"},{"t":"12 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 12 cm이면 원주는 36 cm와 48 cm 사이예요.","보기 가운데 그 사이에 있는 것은 37.68 cm뿐이에요."]},{"stem":"지름이 5 cm인 원의 원주가 될 수 있는 길이는 어느 것인가요?","options":[{"t":"15.7 cm","correct":true},{"t":"14 cm","mis":"M6-2-u5-X02"},{"t":"22 cm","mis":"M6-2-u5-X02"},{"t":"5 cm","mis":"M6-2-u5-X02"}],"explanation":["원주는 지름의 3배보다 길고 4배보다 짧아요.","지름이 5 cm이면 원주는 15 cm와 20 cm 사이예요.","보기 가운데 그 사이에 있는 것은 15.7 cm뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#3','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'error','auto','지름이 6 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u5-X02','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":3,"kind":"error","stem":"지름이 6 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「원주는 정확히 지름의 3배인 18 cm야.」","correct":true,"mis_target":"M6-2-u5-X02"},{"t":"나린 — 「원 안 정육각형의 둘레는 18 cm야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「원 밖 정사각형의 둘레는 24 cm야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「원주는 18 cm보다 길고 24 cm보다 짧아.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정육각형의 둘레는 18 cm, 원 밖 정사각형의 둘레는 24 cm예요.","원주는 정육각형의 둘레보다 길어요.","그래서 원주가 정확히 18 cm라는 가온의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"지름이 8 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「원주는 정확히 지름의 3배인 24 cm야.」","correct":true,"mis_target":"M6-2-u5-X02"},{"t":"하린 — 「원 안 정육각형의 둘레는 24 cm야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「원 밖 정사각형의 둘레는 32 cm야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「원주는 24 cm보다 길고 32 cm보다 짧아.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정육각형의 둘레는 24 cm, 원 밖 정사각형의 둘레는 32 cm예요.","원주는 정육각형의 둘레보다 길어요.","그래서 원주가 정확히 24 cm라는 수아의 말이 잘못되었어요."]},{"stem":"지름이 10 cm인 원의 원주를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「원주는 정확히 지름의 3배인 30 cm야.」","correct":true,"mis_target":"M6-2-u5-X02"},{"t":"지호 — 「원 안 정육각형의 둘레는 30 cm야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「원 밖 정사각형의 둘레는 40 cm야.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「원주는 30 cm보다 길고 40 cm보다 짧아.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정육각형의 둘레는 30 cm, 원 밖 정사각형의 둘레는 40 cm예요.","원주는 정육각형의 둘레보다 길어요.","그래서 원주가 정확히 30 cm라는 서아의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#4','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C1","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"원 안 정육각형의 한 변","r":"반지름"},{"l":"원 밖 정사각형의 한 변","r":"지름"},{"l":"원 위를 한 바퀴 돈 거리","r":"원주"}],"mis":"M6-2-u5-X01","explanation":["원 안 정육각형의 한 변은 반지름, 원 밖 정사각형의 한 변은 지름이에요.","정육각형 둘레는 지름의 3배, 정사각형 둘레는 지름의 4배예요.","원 위를 한 바퀴 돈 거리가 원주예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원의 중심과 원 위의 한 점을 이은 선분","r":"반지름"},{"l":"원의 중심을 지나 원 위의 두 점을 이은 선분","r":"지름"},{"l":"원의 둘레","r":"원주"}],"explanation":["원 안 정육각형의 한 변은 반지름, 원 밖 정사각형의 한 변은 지름이에요.","정육각형 둘레는 지름의 3배, 정사각형 둘레는 지름의 4배예요.","원 위를 한 바퀴 돈 거리가 원주예요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원 안 정육각형의 둘레","r":"지름의 3배"},{"l":"원 밖 정사각형의 둘레","r":"지름의 4배"},{"l":"지름","r":"반지름의 2배"}],"explanation":["원 안 정육각형의 한 변은 반지름, 원 밖 정사각형의 한 변은 지름이에요.","정육각형 둘레는 지름의 3배, 정사각형 둘레는 지름의 4배예요.","원 위를 한 바퀴 돈 거리가 원주예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#5','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'ox','auto','원 안에 꼭 맞는 정육각형의 둘레는 원주보다 짧아요.',ARRAY['M6-2-u5-X03']::text[],true,'{"seq":5,"concept":"M6-2-u5-C1","difficulty":3,"kind":"ox","stem":"원 안에 꼭 맞는 정육각형의 둘레는 원주보다 짧아요.","answer":"O","reason_options":[{"t":"두 점 사이를 이을 때 곧은 선이 굽은 선보다 짧기 때문에","correct":true},{"t":"정육각형의 한 변이 지름과 같기 때문에","mis":"M6-2-u5-X03"}],"mis":"M6-2-u5-X03","explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."],"variant_rule":{"alt":[{"stem":"원주는 지름의 4배보다 길어요.","answer":"X","reason_options":[{"t":"원주는 원 밖 정사각형의 둘레(지름의 4배)보다 짧기 때문에","correct":true},{"t":"원이 정사각형을 감싸고 있기 때문에","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]},{"stem":"지름이 다르면 원주도 달라요.","answer":"O","reason_options":[{"t":"지름이 길수록 원의 둘레도 길어지기 때문에","correct":true},{"t":"원주는 지름과 상관없이 늘 같기 때문에","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","원 밖 정사각형의 둘레는 지름의 4배예요.","원주는 그 사이 — 지름의 3배보다 길고 4배보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#6','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'mc','auto','반지름이 9 cm인 원과 지름이 16 cm인 원이 있어요. 원주가 더 긴 원은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X19']::text[],true,'{"seq":6,"concept":"M6-2-u5-C1","difficulty":3,"kind":"mc","stem":"반지름이 9 cm인 원과 지름이 16 cm인 원이 있어요. 원주가 더 긴 원은 어느 것인가요?","options":[{"t":"반지름이 9 cm인 원","correct":true},{"t":"지름이 16 cm인 원","mis":"M6-2-u5-X01"},{"t":"두 원의 원주가 같아요","mis":"M6-2-u5-X01"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려면 반지름을 지름으로 바꾸어요.","반지름 9 cm인 원의 지름은 18 cm예요.","지름이 긴 원이 원주도 길어요 — 반지름이 9 cm인 원예요."],"variant_rule":{"alt":[{"stem":"반지름이 7 cm인 원과 지름이 15 cm인 원이 있어요. 원주가 더 긴 원은 어느 것인가요?","options":[{"t":"지름이 15 cm인 원","correct":true},{"t":"반지름이 7 cm인 원","mis":"M6-2-u5-X01"},{"t":"두 원의 원주가 같아요","mis":"M6-2-u5-X01"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려면 반지름을 지름으로 바꾸어요.","반지름 7 cm인 원의 지름은 14 cm예요.","지름이 긴 원이 원주도 길어요 — 지름이 15 cm인 원예요."]},{"stem":"반지름이 12 cm인 원과 지름이 22 cm인 원이 있어요. 원주가 더 긴 원은 어느 것인가요?","options":[{"t":"반지름이 12 cm인 원","correct":true},{"t":"지름이 22 cm인 원","mis":"M6-2-u5-X01"},{"t":"두 원의 원주가 같아요","mis":"M6-2-u5-X01"},{"t":"견줄 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["같은 것끼리 견주려면 반지름을 지름으로 바꾸어요.","반지름 12 cm인 원의 지름은 24 cm예요.","지름이 긴 원이 원주도 길어요 — 반지름이 12 cm인 원예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#7','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',3,'mc','auto','지름이 16 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":7,"concept":"M6-2-u5-C1","difficulty":3,"kind":"mc","stem":"지름이 16 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"48 cm보다 길고 64 cm보다 짧아요","correct":true},{"t":"32 cm보다 길고 48 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"64 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 48 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 48 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 64 cm예요.","원주는 그 사이 — 48 cm보다 길고 64 cm보다 짧아요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"36 cm보다 길고 48 cm보다 짧아요","correct":true},{"t":"24 cm보다 길고 36 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"48 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 36 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 36 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 48 cm예요.","원주는 그 사이 — 36 cm보다 길고 48 cm보다 짧아요."]},{"stem":"지름이 20 cm인 원의 원주를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"60 cm보다 길고 80 cm보다 짧아요","correct":true},{"t":"40 cm보다 길고 60 cm보다 짧아요","mis":"M6-2-u5-X02"},{"t":"80 cm보다 길어요","mis":"M6-2-u5-X02"},{"t":"정확히 60 cm예요","mis":"M6-2-u5-X02"}],"explanation":["원 안 정육각형의 둘레는 지름의 3배인 60 cm예요.","원 밖 정사각형의 둘레는 지름의 4배인 80 cm예요.","원주는 그 사이 — 60 cm보다 길고 80 cm보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#8','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',4,'sa','auto','어떤 원 안에 꼭 맞는 정육각형의 둘레가 24 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u5-C1","difficulty":4,"kind":"sa","stem":"어떤 원 안에 꼭 맞는 정육각형의 둘레가 24 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?","answer":["32"],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","24 ÷ 3 = 8 — 지름은 8 cm예요.","원 밖 정사각형의 둘레는 지름의 4배 — 8 × 4 = 32 cm예요."],"variant_rule":{"alt":[{"stem":"어떤 원 안에 꼭 맞는 정육각형의 둘레가 18 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?","answer":["24"],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","18 ÷ 3 = 6 — 지름은 6 cm예요.","원 밖 정사각형의 둘레는 지름의 4배 — 6 × 4 = 24 cm예요."]},{"stem":"어떤 원 안에 꼭 맞는 정육각형의 둘레가 36 cm예요. 같은 원 밖에 꼭 맞는 정사각형의 둘레는 몇 cm인가요?","answer":["48"],"explanation":["원 안 정육각형의 둘레는 지름의 3배예요.","36 ÷ 3 = 12 — 지름은 12 cm예요.","원 밖 정사각형의 둘레는 지름의 4배 — 12 × 4 = 48 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#9','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',4,'sa','auto','어떤 원 밖에 꼭 맞는 정사각형의 둘레가 48 cm예요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C1","difficulty":4,"kind":"sa","stem":"어떤 원 밖에 꼭 맞는 정사각형의 둘레가 48 cm예요. 이 원의 반지름은 몇 cm인가요?","answer":["6"],"explanation":["원 밖 정사각형의 한 변은 지름과 같아요.","48 ÷ 4 = 12 — 지름은 12 cm예요.","반지름은 지름의 반 — 12 ÷ 2 = 6 cm예요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 둘레가 40 cm예요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["원 밖 정사각형의 한 변은 지름과 같아요.","40 ÷ 4 = 10 — 지름은 10 cm예요.","반지름은 지름의 반 — 10 ÷ 2 = 5 cm예요."]},{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 둘레가 64 cm예요. 이 원의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["원 밖 정사각형의 한 변은 지름과 같아요.","64 ÷ 4 = 16 — 지름은 16 cm예요.","반지름은 지름의 반 — 16 ÷ 2 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L02_challenge#10','math',6,2,'u5','L02','g6_2_math_u5_L02_challenge','lesson_challenge','M6-2-u5-C1',4,'essay','teacher','원주가 지름의 3배보다 길고 4배보다 짧은 까닭을 원 안에 꼭 맞는 정육각형과 원 밖에 꼭 맞는 정사각형을 이용하여 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C1","difficulty":4,"kind":"essay","stem":"원주가 지름의 3배보다 길고 4배보다 짧은 까닭을 원 안에 꼭 맞는 정육각형과 원 밖에 꼭 맞는 정사각형을 이용하여 설명해 보세요.","answer_guide":{"answer":"예: 원 안 정육각형의 한 변은 반지름과 같아 둘레가 지름의 3배이고, 곧은 선보다 굽은 선이 길어 원주는 그보다 길다. 원 밖 정사각형의 한 변은 지름과 같아 둘레가 지름의 4배이고, 꺾인 선보다 원의 굽은 선이 짧아 원주는 그보다 짧다.","scoring_points":["정육각형의 둘레가 지름의 3배임을 밝혔는가","정사각형의 둘레가 지름의 4배임을 밝혔는가","원주가 두 둘레 사이에 있는 까닭을 썼는가"]},"explanation":["정육각형의 한 변 = 반지름 → 둘레는 지름의 3배예요.","정사각형의 한 변 = 지름 → 둘레는 지름의 4배예요.","원주는 그 사이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#1','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',1,'mc','auto','원주율을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X04']::text[],true,'{"seq":1,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원주율을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (지름)","correct":true},{"t":"(지름) ÷ (원주)","mis":"M6-2-u5-X04"},{"t":"(원주) × (지름)","mis":"M6-2-u5-X04"},{"t":"(원주) ÷ (반지름)","mis":"M6-2-u5-X04"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비율은 (비교하는 양) ÷ (기준량) — 기준량은 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."],"variant_rule":{"alt":[{"stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."]},{"stem":"원주율을 어림하여 쓸 때 흔히 쓰는 값은 어느 것인가요?","options":[{"t":"3.14","correct":true},{"t":"4","mis":"M6-2-u5-X06"},{"t":"2","mis":"M6-2-u5-X06"},{"t":"0.314","mis":"M6-2-u5-X20"}],"explanation":["원주율을 소수로 나타내면 3.14159…처럼 끝없이 이어져요.","그래서 어림하여 쓰는데 흔히 3.14를 써요.","원주는 지름의 약 3.14배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#2','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C1',1,'sa','auto','공학 도구로 반지름이 3 cm인 원을 그렸어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"공학 도구로 반지름이 3 cm인 원을 그렸어요. 이 원의 지름은 몇 cm인가요?","answer":["6"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","3 × 2 = 6 — 지름은 6 cm예요."],"variant_rule":{"alt":[{"stem":"공학 도구로 반지름이 7 cm인 원을 그렸어요. 이 원의 지름은 몇 cm인가요?","answer":["14"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","7 × 2 = 14 — 지름은 14 cm예요."]},{"stem":"공학 도구로 반지름이 12 cm인 원을 그렸어요. 이 원의 지름은 몇 cm인가요?","answer":["24"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","12 × 2 = 24 — 지름은 24 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#3','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',1,'mc','auto','어떤 원의 원주가 15.7 cm, 지름이 5 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X20']::text[],true,'{"seq":3,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"어떤 원의 원주가 15.7 cm, 지름이 5 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"10.7","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","15.7 ÷ 5 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."],"variant_rule":{"alt":[{"stem":"원 모양 시계의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"21.4","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]},{"stem":"원 모양 쟁반의 원주가 62.8 cm, 지름이 20 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"42.8","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","62.8 ÷ 20 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#4','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',1,'ox','auto','지름이 길어지면 원주율도 커져요.',ARRAY['M6-2-u5-X05']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":1,"kind":"ox","stem":"지름이 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"지름이 길어지면 원주도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"큰 원일수록 둘레가 길어 원주율도 크기 때문에","mis":"M6-2-u5-X05"}],"mis":"M6-2-u5-X05","explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"작은 동전과 큰 접시의 원주율은 같아요.","answer":"O","reason_options":[{"t":"모든 원에서 지름에 대한 원주의 비율은 일정하기 때문에","correct":true},{"t":"동전과 접시는 크기가 달라 원주율도 달라야 하기 때문에","mis":"M6-2-u5-X05"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]},{"stem":"원주율 3.14는 정확한 값이에요.","answer":"X","reason_options":[{"t":"원주율은 끝없이 이어지는 소수라 3.14는 어림한 값이기 때문에","correct":true},{"t":"원주를 지름으로 나누면 언제나 3.14로 딱 떨어지기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#5','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'sa','auto','지름이 2 cm일 때 원주는 6.28 cm, 지름이 4 cm일 때 원주는 12.56 cm예요. 지름이 2배가 될 때 원주는 몇 배가 되나요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":2,"kind":"sa","stem":"지름이 2 cm일 때 원주는 6.28 cm, 지름이 4 cm일 때 원주는 12.56 cm예요. 지름이 2배가 될 때 원주는 몇 배가 되나요?","answer":["2"],"explanation":["12.56 ÷ 6.28 = 2예요.","지름이 2배가 되니 원주도 2배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."],"variant_rule":{"alt":[{"stem":"지름이 2 cm일 때 원주는 6.28 cm, 지름이 8 cm일 때 원주는 25.12 cm예요. 지름이 4배가 될 때 원주는 몇 배가 되나요?","answer":["4"],"explanation":["25.12 ÷ 6.28 = 4예요.","지름이 4배가 되니 원주도 4배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."]},{"stem":"지름이 3 cm일 때 원주는 9.42 cm, 지름이 9 cm일 때 원주는 28.26 cm예요. 지름이 3배가 될 때 원주는 몇 배가 되나요?","answer":["3"],"explanation":["28.26 ÷ 9.42 = 3이에요.","지름이 3배가 되니 원주도 3배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#6','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X04']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["22 ÷ 7 = 3.142857…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."],"variant_rule":{"alt":[{"stem":"물병의 원주를 재었더니 40.8 cm, 지름은 13 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["40.8 ÷ 13 = 3.13846…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]},{"stem":"연필꽂이의 원주를 재었더니 59.75 cm, 지름은 19 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["59.75 ÷ 19 = 3.14473…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#7','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?',ARRAY['M6-2-u5-X05','M6-2-u5-X06']::text[],true,'{"seq":7,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."],"variant_rule":{"alt":[{"stem":"물병의 (원주) ÷ (지름)은 3.13846…, 연필꽂이의 값은 3.14473…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."]},{"stem":"연필꽂이의 (원주) ÷ (지름)은 3.14473…, 냄비 뚜껑의 값은 3.142857…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#8','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?',ARRAY['M6-2-u5-X19']::text[],true,'{"seq":8,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주에 대한 원의 지름의 비율을 원주율이라고 합니다.","correct":true},{"t":"원의 크기가 달라져도 원주율은 일정합니다.","mis":"M6-2-u5-X19"},{"t":"반지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원주율은 지름에 대한 원주의 비율 — 기준량이 지름이에요.","나머지 세 문장은 모두 바른 설명이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원이 커지면 원주율도 커집니다.","correct":true},{"t":"지름이 길어지면 원주도 길어집니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 약 3.14배입니다.","mis":"M6-2-u5-X19"},{"t":"원주율을 소수로 나타내면 끝없이 계속됩니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","원이 커져도 원주와 지름이 함께 늘어 원주율은 그대로예요.","나머지 세 문장은 모두 바른 설명이에요."]},{"stem":"이번에는 다른 보기예요. 원주율에 대한 설명으로 잘못된 문장은 어느 것인가요?","options":[{"t":"원주율은 정확히 3.14입니다.","correct":true},{"t":"원주율은 원의 크기와 상관없이 일정합니다.","mis":"M6-2-u5-X19"},{"t":"원주율은 (원주) ÷ (지름)으로 구합니다.","mis":"M6-2-u5-X19"},{"t":"원주는 지름의 3배보다 길고 4배보다 짧습니다.","mis":"M6-2-u5-X19"}],"explanation":["보기를 하나씩 원주율의 뜻과 견주어 봐요.","3.14는 끝없이 이어지는 원주율을 어림한 값이에요.","나머지 세 문장은 모두 바른 설명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#9','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',2,'mc','auto','지름이 10 cm인 원의 원주는 31.4 cm예요. 원주는 지름의 약 몇 배인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X02']::text[],true,'{"seq":9,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"지름이 10 cm인 원의 원주는 31.4 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."],"variant_rule":{"alt":[{"stem":"지름이 5 cm인 원의 원주는 15.7 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","15.7 ÷ 5 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]},{"stem":"지름이 20 cm인 원의 원주는 62.8 cm예요. 원주는 지름의 약 몇 배인가요?","options":[{"t":"약 3.14배","correct":true},{"t":"약 6.28배","mis":"M6-2-u5-X04"},{"t":"약 0.32배","mis":"M6-2-u5-X04"},{"t":"약 4배","mis":"M6-2-u5-X02"}],"explanation":["(원주) ÷ (지름)을 계산해요.","62.8 ÷ 20 = 3.14예요.","원주는 지름의 약 3.14배 — 이 값이 원주율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_basic#10','math',6,2,'u5','L03','g6_2_math_u5_L03_basic','lesson_basic','M6-2-u5-C2',3,'sa','auto','원주가 지름보다 21.4 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u5-C2","difficulty":3,"kind":"sa","stem":"원주가 지름보다 21.4 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["10"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 21.4예요.","21.4 ÷ 2.14 = 10 — 지름은 10 cm예요."],"variant_rule":{"alt":[{"stem":"원주가 지름보다 10.7 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["5"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 10.7이에요.","10.7 ÷ 2.14 = 5 — 지름은 5 cm예요."]},{"stem":"원주가 지름보다 42.8 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["20"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 42.8이에요.","42.8 ÷ 2.14 = 20 — 지름은 20 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#1','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',2,'sa','auto','지름이 3 cm일 때 원주는 9.42 cm, 지름이 15 cm일 때 원주는 47.1 cm예요. 지름이 5배가 될 때 원주는 몇 배가 되나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C2","difficulty":2,"kind":"sa","stem":"지름이 3 cm일 때 원주는 9.42 cm, 지름이 15 cm일 때 원주는 47.1 cm예요. 지름이 5배가 될 때 원주는 몇 배가 되나요?","answer":["5"],"explanation":["47.1 ÷ 9.42 = 5예요.","지름이 5배가 되니 원주도 5배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."],"variant_rule":{"alt":[{"stem":"지름이 2 cm일 때 원주는 6.28 cm, 지름이 20 cm일 때 원주는 62.8 cm예요. 지름이 10배가 될 때 원주는 몇 배가 되나요?","answer":["10"],"explanation":["62.8 ÷ 6.28 = 10이에요.","지름이 10배가 되니 원주도 10배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."]},{"stem":"지름이 4 cm일 때 원주는 12.56 cm, 지름이 12 cm일 때 원주는 37.68 cm예요. 지름이 3배가 될 때 원주는 몇 배가 되나요?","answer":["3"],"explanation":["37.68 ÷ 12.56 = 3이에요.","지름이 3배가 되니 원주도 3배가 되었어요.","원주율이 일정해서 원주는 지름과 같은 배수로 늘어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#2','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',2,'mc','auto','원 모양 쟁반의 원주가 25.12 cm, 지름이 8 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X20']::text[],true,'{"seq":2,"concept":"M6-2-u5-C2","difficulty":2,"kind":"mc","stem":"원 모양 쟁반의 원주가 25.12 cm, 지름이 8 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"17.12","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","25.12 ÷ 8 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."],"variant_rule":{"alt":[{"stem":"원 모양 탬버린의 원주가 47.1 cm, 지름이 15 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"32.1","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","47.1 ÷ 15 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]},{"stem":"원 모양 거울의 원주가 37.68 cm, 지름이 12 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"25.68","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","37.68 ÷ 12 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#3','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'error','auto','원주율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u5-X05','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C2","difficulty":3,"kind":"error","stem":"원주율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「큰 원은 원주율도 더 커.」","correct":true,"mis_target":"M6-2-u5-X05"},{"t":"나린 — 「원주율은 (원주) ÷ (지름)이야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「원주율은 원의 크기와 상관없이 일정해.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「원주율은 끝없이 이어지는 소수야.」","mis":"M6-2-u5-X19"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","모든 원에서 일정하고 3.14159…로 끝없이 이어져요.","그래서 가온의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원주율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「원주율은 (지름) ÷ (원주)로 구해.」","correct":true,"mis_target":"M6-2-u5-X04"},{"t":"하린 — 「원주율은 (원주) ÷ (지름)이야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「원주율은 원의 크기와 상관없이 일정해.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「원주율은 끝없이 이어지는 소수야.」","mis":"M6-2-u5-X19"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","모든 원에서 일정하고 3.14159…로 끝없이 이어져요.","그래서 수아의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원주율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「3.14는 원주율의 정확한 값이야.」","correct":true,"mis_target":"M6-2-u5-X06"},{"t":"지호 — 「원주율은 (원주) ÷ (지름)이야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「원주율은 원의 크기와 상관없이 일정해.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「원주율은 끝없이 이어지는 소수야.」","mis":"M6-2-u5-X19"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","모든 원에서 일정하고 3.14159…로 끝없이 이어져요.","그래서 서아의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#4','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'ox','auto','반지름에 대한 원주의 비율도 3.14예요.',ARRAY['M6-2-u5-X04']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":3,"kind":"ox","stem":"반지름에 대한 원주의 비율도 3.14예요.","answer":"X","reason_options":[{"t":"원주는 반지름의 약 6.28배이기 때문에","correct":true},{"t":"반지름도 원의 길이니 비율이 같기 때문에","mis":"M6-2-u5-X04"}],"mis":"M6-2-u5-X04","explanation":["(원주율) = (원주) ÷ (지름)이에요.","원이 커져도 원주와 지름이 함께 늘어요.","그래서 원주율은 늘 약 3.14예요."],"variant_rule":{"alt":[{"stem":"원주가 31.4 cm인 원의 지름은 10 cm예요.","answer":"O","reason_options":[{"t":"31.4 ÷ 3.14 = 10이기 때문에","correct":true},{"t":"31.4 × 3.14가 10이기 때문에","mis":"M6-2-u5-X08"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","원이 커져도 원주와 지름이 함께 늘어요.","그래서 원주율은 늘 약 3.14예요."]},{"stem":"원주가 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"원주가 길어지면 지름도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"원주율은 원주에 비례하기 때문에","mis":"M6-2-u5-X05"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","원이 커져도 원주와 지름이 함께 늘어요.","그래서 원주율은 늘 약 3.14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#5','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"원주","r":"원의 둘레"},{"l":"원주율","r":"(원주) ÷ (지름)"},{"l":"지름","r":"(원주) ÷ (원주율)"}],"mis":"M6-2-u5-X04","explanation":["원주율은 (원주) ÷ (지름)이에요.","원주는 (지름) × (원주율), 지름은 (원주) ÷ (원주율)이에요.","원주율은 약 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원주","r":"(지름) × (원주율)"},{"l":"원주율","r":"약 3.14"},{"l":"반지름","r":"(지름) ÷ 2"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","원주는 (지름) × (원주율), 지름은 (원주) ÷ (원주율)이에요.","원주율은 약 3.14로 어림해 써요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"지름 10 cm인 원의 원주","r":"31.4 cm"},{"l":"지름 10 cm인 원의 원주율","r":"3.14"},{"l":"원주 31.4 cm인 원의 반지름","r":"5 cm"}],"explanation":["원주율은 (원주) ÷ (지름)이에요.","원주는 (지름) × (원주율), 지름은 (원주) ÷ (원주율)이에요.","원주율은 약 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#6','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'mc','auto','세 물건의 원주와 지름을 재었어요. ㉠ 원주 31.4 cm, 지름 10 cm · ㉡ 원주 47 cm, 지름 15 cm · ㉢ 원주 40 cm, 지름 10 cm 가운데 잘못 잰 것이 분명한 것은 어느 것인가요?',ARRAY['M6-2-u5-X06']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"세 물건의 원주와 지름을 재었어요. ㉠ 원주 31.4 cm, 지름 10 cm · ㉡ 원주 47 cm, 지름 15 cm · ㉢ 원주 40 cm, 지름 10 cm 가운데 잘못 잰 것이 분명한 것은 어느 것인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M6-2-u5-X06"},{"t":"㉡","mis":"M6-2-u5-X06"},{"t":"모두 바르게 재었다","mis":"M6-2-u5-X06"}],"explanation":["각각 (원주) ÷ (지름)을 계산해 봐요.","㉠ 3.14 · ㉡ 3.13 · ㉢ 4예요.","원주는 지름의 3배보다 길고 4배보다 짧아야 하니 ㉢는 잘못 잰 거예요."],"variant_rule":{"alt":[{"stem":"세 물건의 원주와 지름을 재었어요. ㉠ 원주 25 cm, 지름 10 cm · ㉡ 원주 62.8 cm, 지름 20 cm · ㉢ 원주 18.9 cm, 지름 6 cm 가운데 잘못 잰 것이 분명한 것은 어느 것인가요?","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M6-2-u5-X06"},{"t":"㉢","mis":"M6-2-u5-X06"},{"t":"모두 바르게 재었다","mis":"M6-2-u5-X06"}],"explanation":["각각 (원주) ÷ (지름)을 계산해 봐요.","㉠ 2.5 · ㉡ 3.14 · ㉢ 3.15예요.","원주는 지름의 3배보다 길고 4배보다 짧아야 하니 ㉠는 잘못 잰 거예요."]},{"stem":"세 물건의 원주와 지름을 재었어요. ㉠ 원주 9.4 cm, 지름 3 cm · ㉡ 원주 50 cm, 지름 10 cm · ㉢ 원주 37.7 cm, 지름 12 cm 가운데 잘못 잰 것이 분명한 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M6-2-u5-X06"},{"t":"㉢","mis":"M6-2-u5-X06"},{"t":"모두 바르게 재었다","mis":"M6-2-u5-X06"}],"explanation":["각각 (원주) ÷ (지름)을 계산해 봐요.","㉠ 3.13 · ㉡ 5 · ㉢ 3.14예요.","원주는 지름의 3배보다 길고 4배보다 짧아야 하니 ㉡는 잘못 잰 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#7','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',3,'mc','auto','지름이 6 cm인 원의 원주는 18.84 cm예요. 지름이 18 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":7,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"지름이 6 cm인 원의 원주는 18.84 cm예요. 지름이 18 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"30.84 cm","mis":"M6-2-u5-X18"},{"t":"169.56 cm","mis":"M6-2-u5-X18"},{"t":"28.26 cm","mis":"M6-2-u5-X20"}],"explanation":["지름이 3배가 되었어요.","원주율이 일정하니 원주도 3배가 돼요.","18.84 × 3 = 56.52 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원의 원주는 12.56 cm예요. 지름이 20 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"62.8 cm","correct":true},{"t":"28.56 cm","mis":"M6-2-u5-X18"},{"t":"314 cm","mis":"M6-2-u5-X18"},{"t":"31.4 cm","mis":"M6-2-u5-X20"}],"explanation":["지름이 5배가 되었어요.","원주율이 일정하니 원주도 5배가 돼요.","12.56 × 5 = 62.8 cm예요."]},{"stem":"지름이 10 cm인 원의 원주는 31.4 cm예요. 지름이 40 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"125.6 cm","correct":true},{"t":"61.4 cm","mis":"M6-2-u5-X18"},{"t":"502.4 cm","mis":"M6-2-u5-X18"},{"t":"62.8 cm","mis":"M6-2-u5-X20"}],"explanation":["지름이 4배가 되었어요.","원주율이 일정하니 원주도 4배가 돼요.","31.4 × 4 = 125.6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#8','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',4,'sa','auto','원주가 지름보다 64.2 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u5-C2","difficulty":4,"kind":"sa","stem":"원주가 지름보다 64.2 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["30"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 64.2예요.","64.2 ÷ 2.14 = 30 — 지름은 30 cm예요."],"variant_rule":{"alt":[{"stem":"원주가 지름보다 32.1 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["15"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 32.1이에요.","32.1 ÷ 2.14 = 15 — 지름은 15 cm예요."]},{"stem":"원주가 지름보다 53.5 cm 더 긴 원이 있어요. 원주율을 3.14로 할 때 이 원의 지름은 몇 cm인가요?","answer":["25"],"explanation":["원주는 지름의 3.14배이니 원주는 지름보다 지름의 2.14배만큼 더 길어요.","(지름) × 2.14 = 53.5예요.","53.5 ÷ 2.14 = 25 — 지름은 25 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#9','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',4,'essay','teacher','작은 동전과 큰 냄비 뚜껑은 크기가 아주 다른데도 (원주) ÷ (지름)이 둘 다 약 3.14로 나와요. 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C2","difficulty":4,"kind":"essay","stem":"작은 동전과 큰 냄비 뚜껑은 크기가 아주 다른데도 (원주) ÷ (지름)이 둘 다 약 3.14로 나와요. 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원이 커져 지름이 길어지면 원주도 같은 배수만큼 함께 길어진다. 그래서 원주를 지름으로 나눈 비율은 변하지 않고, 모든 원에서 원주율은 약 3.14로 일정하다.","scoring_points":["지름이 길어지면 원주도 함께 길어짐을 밝혔는가","비율((원주) ÷ (지름))이 변하지 않음을 썼는가","원주율이 모든 원에서 일정하다고 결론지었는가"]},"explanation":["원이 커지면 원주와 지름이 함께 늘어요.","함께 늘면 나눈 값은 그대로예요.","그래서 원주율은 늘 약 3.14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L03_challenge#10','math',6,2,'u5','L03','g6_2_math_u5_L03_challenge','lesson_challenge','M6-2-u5-C2',4,'essay','teacher','냄비 뚜껑을 재어 구한 (원주) ÷ (지름)은 3.142857…, 물병은 3.13846…이었어요. 두 값이 다르다고 원주율이 원마다 다르다고 말할 수 있는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C2","difficulty":4,"kind":"essay","stem":"냄비 뚜껑을 재어 구한 (원주) ÷ (지름)은 3.142857…, 물병은 3.13846…이었어요. 두 값이 다르다고 원주율이 원마다 다르다고 말할 수 있는지 설명해 보세요.","answer_guide":{"answer":"예: 말할 수 없다. 원주와 지름을 줄자·자로 정확하게 재기 어려워 생긴 작은 차이이다. 반올림하면 둘 다 3.14이고, 원주율은 모든 원에서 일정하다.","scoring_points":["원주율이 원마다 다르지 않다고 답했는가","재는 과정의 오차 때문이라고 설명했는가","반올림하면 3.14로 같음을 보였는가"]},"explanation":["원주율은 모든 원에서 일정해요.","잰 값의 작은 차이는 재기 어려워 생긴 것이에요.","반올림하면 둘 다 3.14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#1','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',1,'mc','auto','지름을 알 때 원주를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X08']::text[],true,'{"seq":1,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름을 알 때 원주를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(지름) × (원주율)","correct":true},{"t":"(지름) ÷ (원주율)","mis":"M6-2-u5-X08"},{"t":"(지름) + (원주율)","mis":"M6-2-u5-X08"},{"t":"(원주율) ÷ (지름)","mis":"M6-2-u5-X08"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","거꾸로 하면 (원주) = (지름) × (원주율)이에요.","지름에 3.14를 곱하면 원주가 나와요."],"variant_rule":{"alt":[{"stem":"원주를 알 때 지름을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (원주율)","correct":true},{"t":"(원주) × (원주율)","mis":"M6-2-u5-X08"},{"t":"(원주) - (원주율)","mis":"M6-2-u5-X08"},{"t":"(원주율) ÷ (원주)","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","곱셈으로 간 길을 나눗셈으로 되짚어요.","그래서 (지름) = (원주) ÷ (원주율)이에요."]},{"stem":"반지름을 알 때 원주를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(반지름) × 2 × (원주율)","correct":true},{"t":"(반지름) × (원주율)","mis":"M6-2-u5-X07"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X12"},{"t":"(반지름) ÷ (원주율)","mis":"M6-2-u5-X08"}],"explanation":["원주는 지름에 원주율을 곱해요.","반지름만 알면 2를 먼저 곱해 지름을 만들어요.","그래서 (반지름) × 2 × (원주율)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#2','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',1,'sa','auto','원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."],"variant_rule":{"alt":[{"stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."]},{"stem":"원 모양 탬버린의 원주를 재었더니 62.8 cm였어요. 이 탬버린의 지름은 몇 cm인가요?","answer":["20"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","62.8 ÷ 3.14를 계산해요.","62.8 ÷ 3.14 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#3','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',1,'mc','auto','지름이 10 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":3,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 10 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X01"},{"t":"62.8 cm","mis":"M6-2-u5-X01"},{"t":"78.5 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","10 × 3.14를 계산해요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 7 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"21.98 cm","correct":true},{"t":"10.99 cm","mis":"M6-2-u5-X01"},{"t":"43.96 cm","mis":"M6-2-u5-X01"},{"t":"38.465 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","7 × 3.14를 계산해요.","7 × 3.14 = 21.98 — 원주는 21.98 cm예요."]},{"stem":"지름이 15 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"47.1 cm","correct":true},{"t":"23.55 cm","mis":"M6-2-u5-X01"},{"t":"94.2 cm","mis":"M6-2-u5-X01"},{"t":"176.625 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","15 × 3.14를 계산해요.","15 × 3.14 = 47.1 — 원주는 47.1 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#4','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',1,'mc','auto','반지름이 6 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":4,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u5-X07"},{"t":"50.24 cm","mis":"M6-2-u5-X12"},{"t":"6.28 cm","mis":"M6-2-u5-X07"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 — 원주는 25.12 cm예요."]},{"stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#5','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',2,'mc','auto','자전거 바퀴의 지름은 80 cm예요. 바퀴가 한 바퀴 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":5,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"자전거 바퀴의 지름은 80 cm예요. 바퀴가 한 바퀴 굴러간 거리는 몇 cm인가요?","options":[{"t":"251.2 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X01"},{"t":"502.4 cm","mis":"M6-2-u5-X01"},{"t":"5024 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","80 × 3.14를 계산해요.","80 × 3.14 = 251.2 — 원주는 251.2 cm예요."],"variant_rule":{"alt":[{"stem":"유모차 바퀴의 지름은 60 cm예요. 바퀴가 한 바퀴 굴러간 거리는 몇 cm인가요?","options":[{"t":"188.4 cm","correct":true},{"t":"94.2 cm","mis":"M6-2-u5-X01"},{"t":"376.8 cm","mis":"M6-2-u5-X01"},{"t":"2826 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","60 × 3.14를 계산해요.","60 × 3.14 = 188.4 — 원주는 188.4 cm예요."]},{"stem":"수레바퀴의 지름은 70 cm예요. 바퀴가 한 바퀴 굴러간 거리는 몇 cm인가요?","options":[{"t":"219.8 cm","correct":true},{"t":"109.9 cm","mis":"M6-2-u5-X01"},{"t":"439.6 cm","mis":"M6-2-u5-X01"},{"t":"3846.5 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","70 × 3.14를 계산해요.","70 × 3.14 = 219.8 — 원주는 219.8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#6','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',2,'mc','auto','지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X07','M6-2-u5-X02']::text[],true,'{"seq":6,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"628 cm","correct":true},{"t":"62.8 cm","mis":"M6-2-u5-X19"},{"t":"314 cm","mis":"M6-2-u5-X07"},{"t":"200 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 30 cm인 원판을 5바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"471 cm","correct":true},{"t":"94.2 cm","mis":"M6-2-u5-X19"},{"t":"235.5 cm","mis":"M6-2-u5-X07"},{"t":"150 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 30 × 3.14 = 94.2 cm예요.","5바퀴면 94.2 × 5 = 471 cm예요."]},{"stem":"지름이 40 cm인 훌라후프를 3바퀴 굴렸어요. 훌라후프가 굴러간 거리는 몇 cm인가요?","options":[{"t":"376.8 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X19"},{"t":"188.4 cm","mis":"M6-2-u5-X07"},{"t":"120 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#7','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',2,'mc','auto','세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":7,"concept":"M6-2-u5-C4","difficulty":2,"kind":"mc","stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 15 cm · ㉡ 지름 16 cm · ㉢ 지름 18 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."],"variant_rule":{"alt":[{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 31.4 cm · ㉡ 지름이 12 cm · ㉢ 반지름이 7 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 10 cm · ㉡ 지름 12 cm · ㉢ 지름 14 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."]},{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 62.8 cm · ㉡ 지름이 18 cm · ㉢ 반지름이 11 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 20 cm · ㉡ 지름 18 cm · ㉢ 지름 22 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉠, ㉡예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#8','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',2,'sa','auto','체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["4"],"explanation":["먼저 지름을 구해요: 25.12 ÷ 3.14 = 8이에요.","반지름은 지름의 반이에요.","8 ÷ 2 = 4 — 반지름은 4예요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"운동장에 줄을 이용하여 원주가 31.4 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["5"],"explanation":["먼저 지름을 구해요: 31.4 ÷ 3.14 = 10이에요.","반지름은 지름의 반이에요.","10 ÷ 2 = 5 — 반지름은 5예요."]},{"stem":"꽃밭에 줄을 이용하여 원주가 37.68 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["6"],"explanation":["먼저 지름을 구해요: 37.68 ÷ 3.14 = 12예요.","반지름은 지름의 반이에요.","12 ÷ 2 = 6 — 반지름은 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#9','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C4',2,'sa','auto','원 모양 시계의 원주가 28.26 cm예요. 이 시계의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"원 모양 시계의 원주가 28.26 cm예요. 이 시계의 지름은 몇 cm인가요?","answer":["9"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","28.26 ÷ 3.14를 계산해요.","28.26 ÷ 3.14 = 9예요."],"variant_rule":{"alt":[{"stem":"원 모양 쟁반의 원주가 47.1 cm예요. 이 쟁반의 지름은 몇 cm인가요?","answer":["15"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","47.1 ÷ 3.14를 계산해요.","47.1 ÷ 3.14 = 15예요."]},{"stem":"원 모양 거울의 원주가 37.68 cm예요. 이 거울의 지름은 몇 cm인가요?","answer":["12"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","37.68 ÷ 3.14를 계산해요.","37.68 ÷ 3.14 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_basic#10','math',6,2,'u5','L04','g6_2_math_u5_L04_basic','lesson_basic','M6-2-u5-C3',3,'error','auto','반지름이 6 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X19']::text[],true,'{"seq":10,"concept":"M6-2-u5-C3","difficulty":3,"kind":"error","stem":"반지름이 6 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「6 × 3.14 = 18.84, 원주는 18.84 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"나린 — 「지름이 12 cm니 12 × 3.14 = 37.68이야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「6 × 2 × 3.14 = 37.68이야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「원주는 37.68 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 6 cm에 2를 먼저 곱해 지름 12 cm를 만들어야 해요.","가온는 반지름에 바로 3.14를 곱했어요 — 원주는 37.68 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"수아 — 「4 × 3.14 = 12.56, 원주는 12.56 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"하린 — 「지름이 8 cm니 8 × 3.14 = 25.12야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「4 × 2 × 3.14 = 25.12야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「원주는 25.12 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 4 cm에 2를 먼저 곱해 지름 8 cm를 만들어야 해요.","수아는 반지름에 바로 3.14를 곱했어요 — 원주는 25.12 cm예요."]},{"stem":"반지름이 7 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"서아 — 「7 × 3.14 = 21.98, 원주는 21.98 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"지호 — 「지름이 14 cm니 14 × 3.14 = 43.96이야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「7 × 2 × 3.14 = 43.96이야.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「원주는 43.96 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 7 cm에 2를 먼저 곱해 지름 14 cm를 만들어야 해요.","서아는 반지름에 바로 3.14를 곱했어요 — 원주는 43.96 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#1','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',2,'mc','auto','지름이 10 cm인 원과 지름이 15 cm인 원이 있어요. 두 원의 원주의 차는 몇 cm인가요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01','M6-2-u5-X19']::text[],true,'{"seq":1,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 10 cm인 원과 지름이 15 cm인 원이 있어요. 두 원의 원주의 차는 몇 cm인가요?","options":[{"t":"15.7 cm","correct":true},{"t":"5 cm","mis":"M6-2-u5-X02"},{"t":"31.4 cm","mis":"M6-2-u5-X01"},{"t":"78.5 cm","mis":"M6-2-u5-X19"}],"explanation":["두 원주를 각각 구해도 되고, 지름의 차에 원주율을 곱해도 돼요.","지름의 차는 15 - 10 = 5 cm예요.","5 × 3.14 = 15.7 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 8 cm인 원과 지름이 12 cm인 원이 있어요. 두 원의 원주의 차는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"4 cm","mis":"M6-2-u5-X02"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"62.8 cm","mis":"M6-2-u5-X19"}],"explanation":["두 원주를 각각 구해도 되고, 지름의 차에 원주율을 곱해도 돼요.","지름의 차는 12 - 8 = 4 cm예요.","4 × 3.14 = 12.56 cm예요."]},{"stem":"지름이 20 cm인 원과 지름이 25 cm인 원이 있어요. 두 원의 원주의 차는 몇 cm인가요?","options":[{"t":"15.7 cm","correct":true},{"t":"5 cm","mis":"M6-2-u5-X02"},{"t":"31.4 cm","mis":"M6-2-u5-X01"},{"t":"141.3 cm","mis":"M6-2-u5-X19"}],"explanation":["두 원주를 각각 구해도 되고, 지름의 차에 원주율을 곱해도 돼요.","지름의 차는 25 - 20 = 5 cm예요.","5 × 3.14 = 15.7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#2','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',2,'sa','auto','원주가 43.96 cm인 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"원주가 43.96 cm인 원의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["먼저 지름을 구해요: 43.96 ÷ 3.14 = 14예요.","반지름은 지름의 반이에요.","14 ÷ 2 = 7 — 반지름은 7이에요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"원주가 50.24 cm인 원의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["먼저 지름을 구해요: 50.24 ÷ 3.14 = 16이에요.","반지름은 지름의 반이에요.","16 ÷ 2 = 8 — 반지름은 8이에요."]},{"stem":"원주가 69.08 cm인 원의 반지름은 몇 cm인가요?","answer":["11"],"explanation":["먼저 지름을 구해요: 69.08 ÷ 3.14 = 22예요.","반지름은 지름의 반이에요.","22 ÷ 2 = 11 — 반지름은 11이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#3','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',3,'mc','auto','바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":3,"concept":"M6-2-u5-C3","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 50 cm인 굴렁쇠를 4바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.57 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","4바퀴면 157 × 4 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]},{"stem":"바깥쪽 원의 지름이 60 cm인 바퀴를 10바퀴 굴렸어요. 이 바퀴가 굴러간 거리는 몇 m인가요?","options":[{"t":"18.84 m","correct":true},{"t":"1884 m","mis":"M6-2-u5-X20"},{"t":"1.884 m","mis":"M6-2-u5-X19"},{"t":"9.42 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 60 × 3.14 = 188.4 cm예요.","10바퀴면 188.4 × 10 = 1884 cm예요.","100 cm = 1 m니 18.84 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#4','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',3,'ox','auto','반지름이 같은 두 원은 원주도 같아요.',ARRAY['M6-2-u5-X05']::text[],true,'{"seq":4,"concept":"M6-2-u5-C3","difficulty":3,"kind":"ox","stem":"반지름이 같은 두 원은 원주도 같아요.","answer":"O","reason_options":[{"t":"반지름이 같으면 지름이 같아 지름 × 3.14도 같기 때문에","correct":true},{"t":"반지름이 같아도 원주는 원마다 다르기 때문에","mis":"M6-2-u5-X05"}],"mis":"M6-2-u5-X05","explanation":["(원주) = (지름) × (원주율)이에요.","반지름만 알면 2를 먼저 곱해요.","지름이 같으면 원주도 같고, 지름이 2배면 원주도 2배예요."],"variant_rule":{"alt":[{"stem":"지름이 2배인 원은 원주도 2배예요.","answer":"O","reason_options":[{"t":"원주는 지름에 3.14를 곱한 값이기 때문에","correct":true},{"t":"원주는 지름에 3.14를 더한 값이기 때문에","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","반지름만 알면 2를 먼저 곱해요.","지름이 같으면 원주도 같고, 지름이 2배면 원주도 2배예요."]},{"stem":"반지름이 5 cm인 원의 원주는 5 × 3.14 = 15.7 cm예요.","answer":"X","reason_options":[{"t":"반지름에 2를 먼저 곱해 지름 10 cm로 계산해야 하기 때문에","correct":true},{"t":"원주는 반지름에 원주율을 곱한 값이기 때문에","mis":"M6-2-u5-X07"}],"explanation":["(원주) = (지름) × (원주율)이에요.","반지름만 알면 2를 먼저 곱해요.","지름이 같으면 원주도 같고, 지름이 2배면 원주도 2배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#5','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C3","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"반지름 2 cm","r":"원주 12.56 cm"},{"l":"지름 5 cm","r":"원주 15.7 cm"},{"l":"반지름 4 cm","r":"원주 25.12 cm"}],"mis":"M6-2-u5-X07","explanation":["(원주) = (지름) × 3.14예요.","반지름이면 2를 먼저 곱해 지름을 만들어요.","원주를 알면 3.14로 나누어 지름을 구해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"지름 3 cm","r":"원주 9.42 cm"},{"l":"반지름 3 cm","r":"원주 18.84 cm"},{"l":"지름 8 cm","r":"원주 25.12 cm"}],"explanation":["(원주) = (지름) × 3.14예요.","반지름이면 2를 먼저 곱해 지름을 만들어요.","원주를 알면 3.14로 나누어 지름을 구해요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원주 31.4 cm","r":"지름 10 cm"},{"l":"원주 62.8 cm","r":"지름 20 cm"},{"l":"원주 15.7 cm","r":"지름 5 cm"}],"explanation":["(원주) = (지름) × 3.14예요.","반지름이면 2를 먼저 곱해 지름을 만들어요.","원주를 알면 3.14로 나누어 지름을 구해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#6','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',3,'error','auto','반지름이 5 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X19']::text[],true,'{"seq":6,"concept":"M6-2-u5-C3","difficulty":3,"kind":"error","stem":"반지름이 5 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"세호 — 「5 × 3.14 = 15.7, 원주는 15.7 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"여울 — 「지름이 10 cm니 10 × 3.14 = 31.4야.」","mis":"M6-2-u5-X19"},{"t":"달곰 — 「5 × 2 × 3.14 = 31.4야.」","mis":"M6-2-u5-X19"},{"t":"순달 — 「원주는 31.4 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 5 cm에 2를 먼저 곱해 지름 10 cm를 만들어야 해요.","세호는 반지름에 바로 3.14를 곱했어요 — 원주는 31.4 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 8 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「8 × 3.14 = 25.12, 원주는 25.12 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"나린 — 「지름이 16 cm니 16 × 3.14 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「8 × 2 × 3.14 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「원주는 50.24 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 8 cm에 2를 먼저 곱해 지름 16 cm를 만들어야 해요.","가온는 반지름에 바로 3.14를 곱했어요 — 원주는 50.24 cm예요."]},{"stem":"반지름이 3 cm인 원의 원주를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"수아 — 「3 × 3.14 = 9.42, 원주는 9.42 cm야.」","correct":true,"mis_target":"M6-2-u5-X07"},{"t":"하린 — 「지름이 6 cm니 6 × 3.14 = 18.84야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「3 × 2 × 3.14 = 18.84야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「원주는 18.84 cm야.」","mis":"M6-2-u5-X19"}],"explanation":["원주는 (지름) × (원주율)이에요.","반지름 3 cm에 2를 먼저 곱해 지름 6 cm를 만들어야 해요.","수아는 반지름에 바로 3.14를 곱했어요 — 원주는 18.84 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#7','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',3,'sa','auto','원 모양 연못의 둘레가 94.2 m예요. 연못의 지름은 몇 m인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u5-C4","difficulty":3,"kind":"sa","stem":"원 모양 연못의 둘레가 94.2 m예요. 연못의 지름은 몇 m인가요?","answer":["30"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","94.2 ÷ 3.14를 계산해요.","94.2 ÷ 3.14 = 30이에요."],"variant_rule":{"alt":[{"stem":"원 모양 광장의 둘레가 125.6 m예요. 광장의 지름은 몇 m인가요?","answer":["40"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","125.6 ÷ 3.14를 계산해요.","125.6 ÷ 3.14 = 40이에요."]},{"stem":"원 모양 분수대의 둘레가 78.5 m예요. 분수대의 지름은 몇 m인가요?","answer":["25"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","78.5 ÷ 3.14를 계산해요.","78.5 ÷ 3.14 = 25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#8','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C3',4,'mc','auto','지름이 50 cm인 바퀴로 471 m를 가려고 해요. 바퀴는 몇 바퀴 굴러야 하나요?',ARRAY['M6-2-u5-X07','M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":8,"concept":"M6-2-u5-C3","difficulty":4,"kind":"mc","stem":"지름이 50 cm인 바퀴로 471 m를 가려고 해요. 바퀴는 몇 바퀴 굴러야 하나요?","options":[{"t":"300바퀴","correct":true},{"t":"600바퀴","mis":"M6-2-u5-X07"},{"t":"150바퀴","mis":"M6-2-u5-X01"},{"t":"3바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","471 m = 47100 cm예요.","47100 ÷ 157 = 300 — 300바퀴예요."],"variant_rule":{"alt":[{"stem":"지름이 40 cm인 바퀴로 628 m를 가려고 해요. 바퀴는 몇 바퀴 굴러야 하나요?","options":[{"t":"500바퀴","correct":true},{"t":"1000바퀴","mis":"M6-2-u5-X07"},{"t":"250바퀴","mis":"M6-2-u5-X01"},{"t":"5바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","628 m = 62800 cm예요.","62800 ÷ 125.6 = 500 — 500바퀴예요."]},{"stem":"지름이 50 cm인 바퀴로 314 m를 가려고 해요. 바퀴는 몇 바퀴 굴러야 하나요?","options":[{"t":"200바퀴","correct":true},{"t":"400바퀴","mis":"M6-2-u5-X07"},{"t":"100바퀴","mis":"M6-2-u5-X01"},{"t":"2바퀴","mis":"M6-2-u5-X20"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","314 m = 31400 cm예요.","31400 ÷ 157 = 200 — 200바퀴예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#9','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',4,'sa','auto','원주가 94.2 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u5-C4","difficulty":4,"kind":"sa","stem":"원주가 94.2 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["90"],"explanation":["지름은 94.2 ÷ 3.14 = 30 cm예요.","정육각형의 둘레는 지름의 3배예요.","30 × 3 = 90 cm예요."],"variant_rule":{"alt":[{"stem":"원주가 62.8 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["60"],"explanation":["지름은 62.8 ÷ 3.14 = 20 cm예요.","정육각형의 둘레는 지름의 3배예요.","20 × 3 = 60 cm예요."]},{"stem":"원주가 31.4 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["30"],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm예요.","정육각형의 둘레는 지름의 3배예요.","10 × 3 = 30 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L04_challenge#10','math',6,2,'u5','L04','g6_2_math_u5_L04_challenge','lesson_challenge','M6-2-u5-C4',4,'essay','teacher','원 모양 호수의 둘레가 157 m예요. 호수를 직접 재지 않고 중심을 지나는 다리의 길이를 구하는 방법과 답을 쓰고, 왜 나누면 지름이 나오는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C4","difficulty":4,"kind":"essay","stem":"원 모양 호수의 둘레가 157 m예요. 호수를 직접 재지 않고 중심을 지나는 다리의 길이를 구하는 방법과 답을 쓰고, 왜 나누면 지름이 나오는지 설명해 보세요.","answer_guide":{"answer":"예: 다리의 길이는 호수의 지름과 같다. (지름) = (원주) ÷ (원주율)이므로 157 ÷ 3.14 = 50 m이다. 지름에 원주율을 곱해 원주가 되었으니, 원주를 원주율로 나누면 다시 지름으로 돌아온다.","scoring_points":["다리의 길이가 지름임을 밝혔는가","157 ÷ 3.14 = 50 m를 구했는가","곱셈을 나눗셈으로 되짚는다는 까닭을 썼는가"]},"explanation":["다리는 중심을 지나니 지름이에요.","157 ÷ 3.14 = 50 m예요.","(원주) = (지름) × (원주율)을 거꾸로 되짚은 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#1','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'sa','auto','한 칸이 1 cm²인 모눈 위에 원을 그렸어요. 원 안에 온전히 들어간 칸은 60칸이고, 원에 걸친 칸은 28칸이에요. 걸친 칸까지 세면 모두 몇 칸인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C5","difficulty":1,"kind":"sa","stem":"한 칸이 1 cm²인 모눈 위에 원을 그렸어요. 원 안에 온전히 들어간 칸은 60칸이고, 원에 걸친 칸은 28칸이에요. 걸친 칸까지 세면 모두 몇 칸인가요?","answer":["88"],"explanation":["온전히 들어간 칸과 걸친 칸을 더해요.","60 + 28 = 88칸이에요.","그래서 원의 넓이는 88 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위에 원을 그렸어요. 원 안에 온전히 들어간 칸은 52칸이고, 원에 걸친 칸은 36칸이에요. 걸친 칸까지 세면 모두 몇 칸인가요?","answer":["88"],"explanation":["온전히 들어간 칸과 걸친 칸을 더해요.","52 + 36 = 88칸이에요.","그래서 원의 넓이는 88 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위에 원을 그렸어요. 원 안에 온전히 들어간 칸은 44칸이고, 원에 걸친 칸은 30칸이에요. 걸친 칸까지 세면 모두 몇 칸인가요?","answer":["74"],"explanation":["온전히 들어간 칸과 걸친 칸을 더해요.","44 + 30 = 74칸이에요.","그래서 원의 넓이는 74 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#2','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'mc','auto','한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X10']::text[],true,'{"seq":2,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"60 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"60 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"60 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 60 cm²보다 넓고 88 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 52칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"52 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"52 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"52 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 52 cm²보다 넓고 88 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 32칸, 걸친 칸까지 세면 52칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"32 cm²보다 넓고 52 cm²보다 좁아요","correct":true},{"t":"32 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"52 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"32 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 32 cm²보다 넓고 52 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#3','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'sa','auto','반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C5","difficulty":1,"kind":"sa","stem":"반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","10 × 10 ÷ 2 = 50이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","12 × 12 ÷ 2 = 72예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]},{"stem":"반지름이 7 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 14 cm예요. 넓이는 몇 cm²인가요?","answer":["98"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","14 × 14 ÷ 2 = 98이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#4','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',1,'sa','auto','반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C5","difficulty":1,"kind":"sa","stem":"반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["64"],"explanation":["원 밖 정사각형의 한 변은 지름 8 cm예요.","8 × 8 = 64예요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["원 밖 정사각형의 한 변은 지름 6 cm예요.","6 × 6 = 36이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]},{"stem":"반지름이 2 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["16"],"explanation":["원 밖 정사각형의 한 변은 지름 4 cm예요.","4 × 4 = 16이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#5','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'mc','auto','지름이 16 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":5,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"지름이 16 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"128 cm²보다 넓고 256 cm²보다 좁아요","correct":true},{"t":"64 cm²보다 넓고 128 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"256 cm²보다 넓고 512 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"16 cm²보다 넓고 32 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 8 cm예요.","원 안 정사각형은 8 × 8 × 2 = 128 cm², 원 밖 정사각형은 8 × 8 × 4 = 256 cm²예요.","원의 넓이는 그 사이 — 128 cm²보다 넓고 256 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"지름이 12 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"72 cm²보다 넓고 144 cm²보다 좁아요","correct":true},{"t":"36 cm²보다 넓고 72 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"144 cm²보다 넓고 288 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"12 cm²보다 넓고 24 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 6 cm예요.","원 안 정사각형은 6 × 6 × 2 = 72 cm², 원 밖 정사각형은 6 × 6 × 4 = 144 cm²예요.","원의 넓이는 그 사이 — 72 cm²보다 넓고 144 cm²보다 좁아요."]},{"stem":"지름이 20 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"200 cm²보다 넓고 400 cm²보다 좁아요","correct":true},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"400 cm²보다 넓고 800 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"20 cm²보다 넓고 40 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 10 cm예요.","원 안 정사각형은 10 × 10 × 2 = 200 cm², 원 밖 정사각형은 10 × 10 × 4 = 400 cm²예요.","원의 넓이는 그 사이 — 200 cm²보다 넓고 400 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#6','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'mc','auto','반지름이 5 cm인 원 모양 메달을 만들려고 해요. 메달의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X10','M6-2-u5-X01']::text[],true,'{"seq":6,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"반지름이 5 cm인 원 모양 메달을 만들려고 해요. 메달의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"75 cm²","correct":true},{"t":"25 cm²","mis":"M6-2-u5-X11"},{"t":"140 cm²","mis":"M6-2-u5-X10"},{"t":"10 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","5 × 5 = 25니 넓이는 50 cm²와 100 cm² 사이예요.","그 한가운데쯤인 약 3배 — 75 cm²가 가장 가까워요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원 모양 방석을 만들려고 해요. 방석의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"300 cm²","correct":true},{"t":"100 cm²","mis":"M6-2-u5-X11"},{"t":"515 cm²","mis":"M6-2-u5-X10"},{"t":"20 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","10 × 10 = 100이니 넓이는 200 cm²와 400 cm² 사이예요.","그 한가운데쯤인 약 3배 — 300 cm²가 가장 가까워요."]},{"stem":"반지름이 4 cm인 원 모양 컵받침을 만들려고 해요. 컵받침의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"48 cm²","correct":true},{"t":"16 cm²","mis":"M6-2-u5-X11"},{"t":"95 cm²","mis":"M6-2-u5-X10"},{"t":"8 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","4 × 4 = 16이니 넓이는 32 cm²와 64 cm² 사이예요.","그 한가운데쯤인 약 3배 — 48 cm²가 가장 가까워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#7','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'mc','auto','원 안에 꼭 맞는 정사각형은 반지름을 한 변으로 하는 정사각형 몇 개와 넓이가 같나요?',ARRAY['M6-2-u5-X11','M6-2-u5-X10']::text[],true,'{"seq":7,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"원 안에 꼭 맞는 정사각형은 반지름을 한 변으로 하는 정사각형 몇 개와 넓이가 같나요?","options":[{"t":"2개","correct":true},{"t":"4개","mis":"M6-2-u5-X11"},{"t":"1개","mis":"M6-2-u5-X11"},{"t":"3개","mis":"M6-2-u5-X10"}],"explanation":["원 안 정사각형을 두 대각선으로 자르면 직각삼각형 4개예요.","반지름을 한 변으로 하는 정사각형 하나는 그 삼각형 2개예요.","그래서 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"원 밖에 꼭 맞는 정사각형은 반지름을 한 변으로 하는 정사각형 몇 개와 넓이가 같나요?","options":[{"t":"4개","correct":true},{"t":"2개","mis":"M6-2-u5-X11"},{"t":"3개","mis":"M6-2-u5-X10"},{"t":"8개","mis":"M6-2-u5-X11"}],"explanation":["원 밖 정사각형의 한 변은 지름 — 반지름의 2배예요.","가로로 2개, 세로로 2개 들어가요.","그래서 정사각형 4개와 넓이가 같아요."]},{"stem":"원의 넓이는 반지름을 한 변으로 하는 정사각형 몇 개의 넓이와 가장 비슷한가요?","options":[{"t":"약 3개","correct":true},{"t":"약 1개","mis":"M6-2-u5-X11"},{"t":"약 6개","mis":"M6-2-u5-X10"},{"t":"약 5개","mis":"M6-2-u5-X10"}],"explanation":["원의 넓이는 반지름 정사각형 2개보다 넓어요.","또 4개보다 좁아요.","그 한가운데쯤인 약 3개와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#8','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'ox','auto','원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.',ARRAY['M6-2-u5-X11']::text[],true,'{"seq":8,"concept":"M6-2-u5-C5","difficulty":2,"kind":"ox","stem":"원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","answer":"O","reason_options":[{"t":"원 안 정사각형은 2배, 원 밖 정사각형은 4배와 넓이가 같기 때문에","correct":true},{"t":"원의 넓이는 반지름의 4배와 정확히 같기 때문에","mis":"M6-2-u5-X11"}],"mis":"M6-2-u5-X11","explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"원 밖에 꼭 맞는 정사각형의 넓이는 (반지름) × (반지름)의 2배예요.","answer":"X","reason_options":[{"t":"원 밖 정사각형의 한 변은 지름이라 반지름 정사각형 4개와 같기 때문에","correct":true},{"t":"원 밖 정사각형의 한 변이 반지름이기 때문에","mis":"M6-2-u5-X11"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]},{"stem":"모눈으로 어림한 넓이는 원의 정확한 넓이예요.","answer":"X","reason_options":[{"t":"어림은 넓이가 들어갈 범위를 찾는 것이기 때문에","correct":true},{"t":"칸을 빠짐없이 셌으니 정확하기 때문에","mis":"M6-2-u5-X10"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#9','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',2,'mc','auto','반지름이 6 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u5-X10','M6-2-u5-X11']::text[],true,'{"seq":9,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"반지름이 6 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"70 cm²","mis":"M6-2-u5-X10"},{"t":"150 cm²","mis":"M6-2-u5-X10"},{"t":"36 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 6 × 6 × 2 = 72 cm²보다 넓어요.","또 6 × 6 × 4 = 144 cm²보다 좁아요.","그 사이에 있는 것은 113.04 cm²뿐이에요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"48 cm²","mis":"M6-2-u5-X10"},{"t":"106 cm²","mis":"M6-2-u5-X10"},{"t":"25 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 5 × 5 × 2 = 50 cm²보다 넓어요.","또 5 × 5 × 4 = 100 cm²보다 좁아요.","그 사이에 있는 것은 78.5 cm²뿐이에요."]},{"stem":"반지름이 4 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"30 cm²","mis":"M6-2-u5-X10"},{"t":"70 cm²","mis":"M6-2-u5-X10"},{"t":"16 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 4 × 4 × 2 = 32 cm²보다 넓어요.","또 4 × 4 × 4 = 64 cm²보다 좁아요.","그 사이에 있는 것은 50.24 cm²뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_basic#10','math',6,2,'u5','L05','g6_2_math_u5_L05_basic','lesson_basic','M6-2-u5-C5',3,'mc','auto','반지름이 5 cm인 원의 넓이를 모눈으로 세었더니 60 cm²보다 넓고 88 cm²보다 좁았고, 정사각형으로 어림했더니 50 cm²보다 넓고 100 cm²보다 좁았어요. 범위를 더 좁게 어림한 방법은 어느 것인가요?',ARRAY['M6-2-u5-X10','M6-2-u5-X19']::text[],true,'{"seq":10,"concept":"M6-2-u5-C5","difficulty":3,"kind":"mc","stem":"반지름이 5 cm인 원의 넓이를 모눈으로 세었더니 60 cm²보다 넓고 88 cm²보다 좁았고, 정사각형으로 어림했더니 50 cm²보다 넓고 100 cm²보다 좁았어요. 범위를 더 좁게 어림한 방법은 어느 것인가요?","options":[{"t":"모눈 칸 세기","correct":true},{"t":"정사각형으로 어림하기","mis":"M6-2-u5-X10"},{"t":"두 방법의 범위가 같아요","mis":"M6-2-u5-X10"},{"t":"알 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["모눈으로 얻은 범위의 폭은 88 - 60 = 28 cm²예요.","정사각형으로 얻은 범위의 폭은 100 - 50 = 50 cm²예요.","폭이 좁은 모눈 칸 세기가 더 좁게 어림한 방법이에요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원의 넓이를 모눈으로 세었더니 276 cm²보다 넓고 344 cm²보다 좁았고, 정사각형으로 어림했더니 200 cm²보다 넓고 400 cm²보다 좁았어요. 범위를 더 좁게 어림한 방법은 어느 것인가요?","options":[{"t":"모눈 칸 세기","correct":true},{"t":"정사각형으로 어림하기","mis":"M6-2-u5-X10"},{"t":"두 방법의 범위가 같아요","mis":"M6-2-u5-X10"},{"t":"알 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["모눈으로 얻은 범위의 폭은 344 - 276 = 68 cm²예요.","정사각형으로 얻은 범위의 폭은 400 - 200 = 200 cm²예요.","폭이 좁은 모눈 칸 세기가 더 좁게 어림한 방법이에요."]},{"stem":"반지름이 4 cm인 원의 넓이를 모눈으로 세었더니 32 cm²보다 넓고 60 cm²보다 좁았고, 정사각형으로 어림했더니 32 cm²보다 넓고 64 cm²보다 좁았어요. 범위를 더 좁게 어림한 방법은 어느 것인가요?","options":[{"t":"모눈 칸 세기","correct":true},{"t":"정사각형으로 어림하기","mis":"M6-2-u5-X10"},{"t":"두 방법의 범위가 같아요","mis":"M6-2-u5-X10"},{"t":"알 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["모눈으로 얻은 범위의 폭은 60 - 32 = 28 cm²예요.","정사각형으로 얻은 범위의 폭은 64 - 32 = 32 cm²예요.","폭이 좁은 모눈 칸 세기가 더 좁게 어림한 방법이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#1','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',2,'mc','auto','지름이 10 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":1,"concept":"M6-2-u5-C5","difficulty":2,"kind":"mc","stem":"지름이 10 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"50 cm²보다 넓고 100 cm²보다 좁아요","correct":true},{"t":"25 cm²보다 넓고 50 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"100 cm²보다 넓고 200 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"10 cm²보다 넓고 20 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 5 cm예요.","원 안 정사각형은 5 × 5 × 2 = 50 cm², 원 밖 정사각형은 5 × 5 × 4 = 100 cm²예요.","원의 넓이는 그 사이 — 50 cm²보다 넓고 100 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"지름이 14 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"98 cm²보다 넓고 196 cm²보다 좁아요","correct":true},{"t":"49 cm²보다 넓고 98 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"196 cm²보다 넓고 392 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"14 cm²보다 넓고 28 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 7 cm예요.","원 안 정사각형은 7 × 7 × 2 = 98 cm², 원 밖 정사각형은 7 × 7 × 4 = 196 cm²예요.","원의 넓이는 그 사이 — 98 cm²보다 넓고 196 cm²보다 좁아요."]},{"stem":"지름이 18 cm인 원의 넓이를 원 안과 밖에 꼭 맞는 정사각형으로 어림했어요. 알맞은 범위는 어느 것인가요?","options":[{"t":"162 cm²보다 넓고 324 cm²보다 좁아요","correct":true},{"t":"81 cm²보다 넓고 162 cm²보다 좁아요","mis":"M6-2-u5-X11"},{"t":"324 cm²보다 넓고 648 cm²보다 좁아요","mis":"M6-2-u5-X01"},{"t":"18 cm²보다 넓고 36 cm²보다 좁아요","mis":"M6-2-u5-X12"}],"explanation":["반지름은 9 cm예요.","원 안 정사각형은 9 × 9 × 2 = 162 cm², 원 밖 정사각형은 9 × 9 × 4 = 324 cm²예요.","원의 넓이는 그 사이 — 162 cm²보다 넓고 324 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#2','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',2,'sa','auto','반지름이 4 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 8 cm예요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 4 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 8 cm예요. 넓이는 몇 cm²인가요?","answer":["32"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","8 × 8 ÷ 2 = 32예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 6 cm예요. 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","6 × 6 ÷ 2 = 18이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]},{"stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","12 × 12 ÷ 2 = 72예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#3','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'error','auto','반지름이 5 cm인 원의 넓이를 어림하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C5","difficulty":3,"kind":"error","stem":"반지름이 5 cm인 원의 넓이를 어림하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「원의 넓이는 100 cm²보다 넓어.」","correct":true,"mis_target":"M6-2-u5-X11"},{"t":"나린 — 「원 안 정사각형의 넓이는 50 cm²야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「원 밖 정사각형의 넓이는 100 cm²야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「원의 넓이는 약 75 cm²쯤이야.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정사각형은 50 cm², 원 밖 정사각형은 100 cm²예요.","원은 원 밖 정사각형 안에 들어 있어요.","그래서 원이 100 cm²보다 넓다는 가온의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원의 넓이를 어림하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「원의 넓이는 144 cm²보다 넓어.」","correct":true,"mis_target":"M6-2-u5-X11"},{"t":"하린 — 「원 안 정사각형의 넓이는 72 cm²야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「원 밖 정사각형의 넓이는 144 cm²야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「원의 넓이는 약 108 cm²쯤이야.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정사각형은 72 cm², 원 밖 정사각형은 144 cm²예요.","원은 원 밖 정사각형 안에 들어 있어요.","그래서 원이 144 cm²보다 넓다는 수아의 말이 잘못되었어요."]},{"stem":"반지름이 4 cm인 원의 넓이를 어림하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「원의 넓이는 64 cm²보다 넓어.」","correct":true,"mis_target":"M6-2-u5-X11"},{"t":"지호 — 「원 안 정사각형의 넓이는 32 cm²야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「원 밖 정사각형의 넓이는 64 cm²야.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「원의 넓이는 약 48 cm²쯤이야.」","mis":"M6-2-u5-X19"}],"explanation":["원 안 정사각형은 32 cm², 원 밖 정사각형은 64 cm²예요.","원은 원 밖 정사각형 안에 들어 있어요.","그래서 원이 64 cm²보다 넓다는 서아의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#4','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'ox','auto','원의 넓이는 원 밖에 꼭 맞는 정사각형 넓이의 반보다 넓어요.',ARRAY['M6-2-u5-X11']::text[],true,'{"seq":4,"concept":"M6-2-u5-C5","difficulty":3,"kind":"ox","stem":"원의 넓이는 원 밖에 꼭 맞는 정사각형 넓이의 반보다 넓어요.","answer":"O","reason_options":[{"t":"원 안 정사각형이 원 밖 정사각형의 반이고 원은 그보다 넓기 때문에","correct":true},{"t":"원이 원 밖 정사각형보다 넓기 때문에","mis":"M6-2-u5-X11"}],"mis":"M6-2-u5-X11","explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"원 안에 꼭 맞는 정사각형의 넓이는 원 밖에 꼭 맞는 정사각형 넓이의 반이에요.","answer":"O","reason_options":[{"t":"반지름 정사각형 2개와 4개이기 때문에","correct":true},{"t":"두 정사각형의 넓이가 같기 때문에","mis":"M6-2-u5-X11"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]},{"stem":"원의 넓이는 원 안에 꼭 맞는 정사각형보다 좁아요.","answer":"X","reason_options":[{"t":"정사각형이 원 안에 들어 있으니 원이 더 넓기 때문에","correct":true},{"t":"정사각형은 모서리가 있어 더 넓기 때문에","mis":"M6-2-u5-X10"}],"explanation":["원 안 정사각형은 반지름 정사각형 2개, 원 밖 정사각형은 4개와 넓이가 같아요.","원의 넓이는 그 사이에 있어요.","어림은 정확한 값이 아니라 범위를 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#5','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'match','auto','원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C5","difficulty":3,"kind":"match","stem":"원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.","pairs":[{"l":"반지름 3 cm","r":"18 cm²보다 넓고 36 cm²보다 좁아요"},{"l":"반지름 4 cm","r":"32 cm²보다 넓고 64 cm²보다 좁아요"},{"l":"반지름 6 cm","r":"72 cm²보다 넓고 144 cm²보다 좁아요"}],"mis":"M6-2-u5-X11","explanation":["원 안 정사각형은 (반지름) × (반지름) × 2예요.","원 밖 정사각형은 (반지름) × (반지름) × 4예요.","원의 넓이는 그 사이에 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.","pairs":[{"l":"반지름 2 cm","r":"8 cm²보다 넓고 16 cm²보다 좁아요"},{"l":"반지름 5 cm","r":"50 cm²보다 넓고 100 cm²보다 좁아요"},{"l":"반지름 7 cm","r":"98 cm²보다 넓고 196 cm²보다 좁아요"}],"explanation":["원 안 정사각형은 (반지름) × (반지름) × 2예요.","원 밖 정사각형은 (반지름) × (반지름) × 4예요.","원의 넓이는 그 사이에 있어요."]},{"stem":"이번에는 다른 보기예요. 원의 넓이를 정사각형으로 어림한 범위끼리 이으세요.","pairs":[{"l":"반지름 1 cm","r":"2 cm²보다 넓고 4 cm²보다 좁아요"},{"l":"반지름 8 cm","r":"128 cm²보다 넓고 256 cm²보다 좁아요"},{"l":"반지름 10 cm","r":"200 cm²보다 넓고 400 cm²보다 좁아요"}],"explanation":["원 안 정사각형은 (반지름) × (반지름) × 2예요.","원 밖 정사각형은 (반지름) × (반지름) × 4예요.","원의 넓이는 그 사이에 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#6','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'mc','auto','반지름이 7 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u5-X10','M6-2-u5-X11']::text[],true,'{"seq":6,"concept":"M6-2-u5-C5","difficulty":3,"kind":"mc","stem":"반지름이 7 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u5-X10"},{"t":"202 cm²","mis":"M6-2-u5-X10"},{"t":"49 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 7 × 7 × 2 = 98 cm²보다 넓어요.","또 7 × 7 × 4 = 196 cm²보다 좁아요.","그 사이에 있는 것은 153.86 cm²뿐이에요."],"variant_rule":{"alt":[{"stem":"반지름이 8 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"126 cm²","mis":"M6-2-u5-X10"},{"t":"262 cm²","mis":"M6-2-u5-X10"},{"t":"64 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 8 × 8 × 2 = 128 cm²보다 넓어요.","또 8 × 8 × 4 = 256 cm²보다 좁아요.","그 사이에 있는 것은 200.96 cm²뿐이에요."]},{"stem":"반지름이 9 cm인 원의 넓이가 될 수 있는 것은 어느 것인가요?","options":[{"t":"254.34 cm²","correct":true},{"t":"160 cm²","mis":"M6-2-u5-X10"},{"t":"330 cm²","mis":"M6-2-u5-X10"},{"t":"81 cm²","mis":"M6-2-u5-X11"}],"explanation":["원의 넓이는 9 × 9 × 2 = 162 cm²보다 넓어요.","또 9 × 9 × 4 = 324 cm²보다 좁아요.","그 사이에 있는 것은 254.34 cm²뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#7','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',3,'mc','auto','반지름이 8 cm인 원 모양 시계를 만들려고 해요. 시계의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X10','M6-2-u5-X01']::text[],true,'{"seq":7,"concept":"M6-2-u5-C5","difficulty":3,"kind":"mc","stem":"반지름이 8 cm인 원 모양 시계를 만들려고 해요. 시계의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"192 cm²","correct":true},{"t":"64 cm²","mis":"M6-2-u5-X11"},{"t":"335 cm²","mis":"M6-2-u5-X10"},{"t":"16 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","8 × 8 = 64니 넓이는 128 cm²와 256 cm² 사이예요.","그 한가운데쯤인 약 3배 — 192 cm²가 가장 가까워요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원 모양 케이크를 만들려고 해요. 케이크의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"108 cm²","correct":true},{"t":"36 cm²","mis":"M6-2-u5-X11"},{"t":"195 cm²","mis":"M6-2-u5-X10"},{"t":"12 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","6 × 6 = 36이니 넓이는 72 cm²와 144 cm² 사이예요.","그 한가운데쯤인 약 3배 — 108 cm²가 가장 가까워요."]},{"stem":"반지름이 9 cm인 원 모양 쟁반을 만들려고 해요. 쟁반의 넓이를 가장 가깝게 어림한 것은 어느 것인가요?","options":[{"t":"243 cm²","correct":true},{"t":"81 cm²","mis":"M6-2-u5-X11"},{"t":"420 cm²","mis":"M6-2-u5-X10"},{"t":"18 cm²","mis":"M6-2-u5-X01"}],"explanation":["원의 넓이는 (반지름) × (반지름)의 2배보다 넓고 4배보다 좁아요.","9 × 9 = 81이니 넓이는 162 cm²와 324 cm² 사이예요.","그 한가운데쯤인 약 3배 — 243 cm²가 가장 가까워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#8','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',4,'sa','auto','어떤 원 밖에 꼭 맞는 정사각형의 넓이가 64 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u5-C5","difficulty":4,"kind":"sa","stem":"어떤 원 밖에 꼭 맞는 정사각형의 넓이가 64 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?","answer":["32"],"explanation":["원 밖 정사각형은 반지름 정사각형 4개, 원 안 정사각형은 2개와 넓이가 같아요.","그래서 원 안 정사각형은 원 밖 정사각형의 반이에요.","64 ÷ 2 = 32 cm²예요."],"variant_rule":{"alt":[{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 넓이가 36 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["원 밖 정사각형은 반지름 정사각형 4개, 원 안 정사각형은 2개와 넓이가 같아요.","그래서 원 안 정사각형은 원 밖 정사각형의 반이에요.","36 ÷ 2 = 18 cm²예요."]},{"stem":"어떤 원 밖에 꼭 맞는 정사각형의 넓이가 16 cm²예요. 같은 원 안에 꼭 맞는 정사각형의 넓이는 몇 cm²인가요?","answer":["8"],"explanation":["원 밖 정사각형은 반지름 정사각형 4개, 원 안 정사각형은 2개와 넓이가 같아요.","그래서 원 안 정사각형은 원 밖 정사각형의 반이에요.","16 ÷ 2 = 8 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#9','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',4,'essay','teacher','반지름이 5 cm인 원의 넓이가 약 75 cm²쯤이라고 어림할 수 있는 까닭을 원 안과 밖에 꼭 맞는 정사각형으로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C5","difficulty":4,"kind":"essay","stem":"반지름이 5 cm인 원의 넓이가 약 75 cm²쯤이라고 어림할 수 있는 까닭을 원 안과 밖에 꼭 맞는 정사각형으로 설명해 보세요.","answer_guide":{"answer":"예: 원 안 정사각형은 5 × 5 × 2 = 50 cm², 원 밖 정사각형은 5 × 5 × 4 = 100 cm²이다. 원의 넓이는 50 cm²보다 넓고 100 cm²보다 좁으니, 그 한가운데쯤인 (반지름) × (반지름)의 약 3배, 곧 약 75 cm²로 어림할 수 있다.","scoring_points":["원 안 정사각형 50 cm²를 구했는가","원 밖 정사각형 100 cm²를 구했는가","그 사이의 약 3배로 75 cm²를 어림했는가"]},"explanation":["원 안 정사각형은 50 cm²예요.","원 밖 정사각형은 100 cm²예요.","그 사이 한가운데쯤 — 약 75 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L05_challenge#10','math',6,2,'u5','L05','g6_2_math_u5_L05_challenge','lesson_challenge','M6-2-u5-C5',4,'essay','teacher','모눈 칸 세기와 정사각형 어림, 두 방법으로 원의 넓이를 어림했어요. 두 방법의 좋은 점을 하나씩 쓰고, 어림이 무엇을 찾는 일인지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C5","difficulty":4,"kind":"essay","stem":"모눈 칸 세기와 정사각형 어림, 두 방법으로 원의 넓이를 어림했어요. 두 방법의 좋은 점을 하나씩 쓰고, 어림이 무엇을 찾는 일인지 설명해 보세요.","answer_guide":{"answer":"예: 모눈 칸 세기는 범위를 더 좁게 찾을 수 있고, 정사각형 어림은 칸을 세지 않고 반지름만으로 빠르게 범위를 구할 수 있다. 어림은 정확한 값이 아니라 넓이가 들어갈 범위를 찾는 일이다.","scoring_points":["모눈 칸 세기의 좋은 점을 썼는가","정사각형 어림의 좋은 점을 썼는가","어림은 범위를 찾는 일이라고 밝혔는가"]},"explanation":["모눈은 범위가 좁아요.","정사각형은 반지름만으로 빨라요.","어림은 넓이가 들어갈 범위를 찾는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#1','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','원을 한없이 잘라서 이어 붙이면 직사각형이 돼요. 이 직사각형의 가로는 원의 무엇과 같나요?',ARRAY['M6-2-u5-X15']::text[],true,'{"seq":1,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"원을 한없이 잘라서 이어 붙이면 직사각형이 돼요. 이 직사각형의 가로는 원의 무엇과 같나요?","options":[{"t":"원주의 반","correct":true},{"t":"원주","mis":"M6-2-u5-X15"},{"t":"지름","mis":"M6-2-u5-X15"},{"t":"반지름","mis":"M6-2-u5-X15"}],"explanation":["잘라 낸 부채꼴이 위아래로 번갈아 놓여요.","원주의 반은 위쪽에, 나머지 반은 아래쪽에 놓여요.","그래서 가로는 원주의 반이에요."],"variant_rule":{"alt":[{"stem":"원을 한없이 잘라서 이어 붙여 만든 직사각형에서 세로는 원의 무엇과 같나요?","options":[{"t":"반지름","correct":true},{"t":"지름","mis":"M6-2-u5-X15"},{"t":"원주","mis":"M6-2-u5-X15"},{"t":"원주의 반","mis":"M6-2-u5-X15"}],"explanation":["부채꼴 한 조각의 길이가 반지름이에요.","조각을 세워 이어 붙이니 높이가 반지름이 돼요.","그래서 세로는 반지름이에요."]},{"stem":"원을 한없이 잘라 이어 붙여 만든 직사각형의 넓이는 처음 원의 넓이와 견주어 어떤가요?","options":[{"t":"같아요","correct":true},{"t":"더 넓어요","mis":"M6-2-u5-X17"},{"t":"더 좁아요","mis":"M6-2-u5-X17"},{"t":"두 배예요","mis":"M6-2-u5-X15"}],"explanation":["원을 자르고 이어 붙였을 뿐이에요.","조각을 더하거나 덜어 내지 않았어요.","그래서 직사각형의 넓이는 원의 넓이와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#2','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','원의 넓이를 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X13','M6-2-u5-X14']::text[],true,'{"seq":2,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"원의 넓이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(반지름) × (반지름) × (원주율)","correct":true},{"t":"(지름) × (원주율)","mis":"M6-2-u5-X12"},{"t":"(지름) × (지름) × (원주율)","mis":"M6-2-u5-X13"},{"t":"(반지름) × (원주율)","mis":"M6-2-u5-X14"}],"explanation":["직사각형의 넓이는 (가로) × (세로)예요.","가로는 원주의 반 — (반지름) × (원주율), 세로는 반지름이에요.","그래서 (원의 넓이) = (반지름) × (반지름) × (원주율)이에요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 넓이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"5 × 5 × 3.14","correct":true},{"t":"10 × 3.14","mis":"M6-2-u5-X12"},{"t":"10 × 10 × 3.14","mis":"M6-2-u5-X13"},{"t":"5 × 3.14","mis":"M6-2-u5-X14"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름 5를 두 번 곱하고 3.14를 곱해요.","10 × 3.14는 원주를 구하는 식이에요."]},{"stem":"반지름이 3 cm인 원의 넓이를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 × 3 × 3.14","correct":true},{"t":"6 × 3.14","mis":"M6-2-u5-X12"},{"t":"6 × 6 × 3.14","mis":"M6-2-u5-X13"},{"t":"3 × 3.14","mis":"M6-2-u5-X14"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름 3을 두 번 곱하고 3.14를 곱해요.","6 × 3.14는 원주를 구하는 식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#3','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','반지름이 3 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":3,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 2 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"12.56 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X14"},{"t":"50.24 cm²","mis":"M6-2-u5-X13"},{"t":"4 cm²","mis":"M6-2-u5-X20"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","2 × 2 × 3.14를 계산해요.","2 × 2 × 3.14 = 12.56 — 넓이는 12.56 cm²예요."]},{"stem":"반지름이 4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"},{"t":"200.96 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#4','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',1,'mc','auto','반지름이 10 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":4,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 10 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"},{"t":"1256 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"},{"t":"314 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]},{"stem":"반지름이 6 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#5','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','지름이 24 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":5,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"지름이 24 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 24 ÷ 2 = 12 cm예요.","12 × 12 × 3.14를 계산해요.","12 × 12 × 3.14 = 452.16 — 넓이는 452.16 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 10 ÷ 2 = 5 cm예요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]},{"stem":"지름이 16 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"},{"t":"25.12 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 16 ÷ 2 = 8 cm예요.","8 × 8 × 3.14를 계산해요.","8 × 8 × 3.14 = 200.96 — 넓이는 200.96 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#6','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','반지름이 5 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X15']::text[],true,'{"seq":6,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"반지름이 5 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 15.7 cm, 세로 5 cm","correct":true},{"t":"가로 31.4 cm, 세로 5 cm","mis":"M6-2-u5-X15"},{"t":"가로 15.7 cm, 세로 10 cm","mis":"M6-2-u5-X15"},{"t":"가로 31.4 cm, 세로 10 cm","mis":"M6-2-u5-X15"}],"explanation":["원주는 10 × 3.14 = 31.4 cm예요.","가로는 원주의 반 — 15.7 cm예요.","세로는 반지름 — 5 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 9.42 cm, 세로 3 cm","correct":true},{"t":"가로 18.84 cm, 세로 3 cm","mis":"M6-2-u5-X15"},{"t":"가로 9.42 cm, 세로 6 cm","mis":"M6-2-u5-X15"},{"t":"가로 18.84 cm, 세로 6 cm","mis":"M6-2-u5-X15"}],"explanation":["원주는 6 × 3.14 = 18.84 cm예요.","가로는 원주의 반 — 9.42 cm예요.","세로는 반지름 — 3 cm예요."]},{"stem":"반지름이 10 cm인 원을 한없이 잘라 이어 붙여 직사각형을 만들었어요. 이 직사각형의 가로와 세로로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 31.4 cm, 세로 10 cm","correct":true},{"t":"가로 62.8 cm, 세로 10 cm","mis":"M6-2-u5-X15"},{"t":"가로 31.4 cm, 세로 20 cm","mis":"M6-2-u5-X15"},{"t":"가로 62.8 cm, 세로 20 cm","mis":"M6-2-u5-X15"}],"explanation":["원주는 20 × 3.14 = 62.8 cm예요.","가로는 원주의 반 — 31.4 cm예요.","세로는 반지름 — 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#7','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','반지름이 30 cm인 원 모양 거울과 가로 70 cm, 세로 40 cm인 직사각형 모양 거울이 있어요. 넓이가 더 넓은 거울은 어느 것인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19']::text[],true,'{"seq":7,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"반지름이 30 cm인 원 모양 거울과 가로 70 cm, 세로 40 cm인 직사각형 모양 거울이 있어요. 넓이가 더 넓은 거울은 어느 것인가요?","options":[{"t":"원 모양 거울","correct":true},{"t":"직사각형 모양 거울","mis":"M6-2-u5-X20"},{"t":"두 거울의 넓이가 같다","mis":"M6-2-u5-X20"},{"t":"넓이를 비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원 모양 거울은 30 × 30 × 3.14 = 2826 cm²예요.","직사각형 모양 거울은 70 × 40 = 2800 cm²예요.","그래서 원 모양 거울이 더 넓어요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원 모양 거울과 가로 18 cm, 세로 18 cm인 직사각형 모양 거울이 있어요. 넓이가 더 넓은 거울은 어느 것인가요?","options":[{"t":"직사각형 모양 거울","correct":true},{"t":"원 모양 거울","mis":"M6-2-u5-X20"},{"t":"두 거울의 넓이가 같다","mis":"M6-2-u5-X20"},{"t":"넓이를 비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원 모양 거울은 10 × 10 × 3.14 = 314 cm²예요.","직사각형 모양 거울은 18 × 18 = 324 cm²예요.","그래서 직사각형 모양 거울이 더 넓어요."]},{"stem":"반지름이 20 cm인 원 모양 거울과 가로 40 cm, 세로 30 cm인 직사각형 모양 거울이 있어요. 넓이가 더 넓은 거울은 어느 것인가요?","options":[{"t":"원 모양 거울","correct":true},{"t":"직사각형 모양 거울","mis":"M6-2-u5-X20"},{"t":"두 거울의 넓이가 같다","mis":"M6-2-u5-X20"},{"t":"넓이를 비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원 모양 거울은 20 × 20 × 3.14 = 1256 cm²예요.","직사각형 모양 거울은 40 × 30 = 1200 cm²예요.","그래서 원 모양 거울이 더 넓어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#8','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u5-X19']::text[],true,'{"seq":8,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"(지름) × (원주율)","correct":true},{"t":"(반지름) × (원주) × ⟨1/2⟩","mis":"M6-2-u5-X19"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X19"},{"t":"(반지름) × (지름) × (원주율) × ⟨1/2⟩","mis":"M6-2-u5-X19"}],"explanation":["(원의 넓이) = (반지름) × (원주) × ⟨1/2⟩이에요.","원주 대신 (지름) × (원주율)을 넣고 정리하면 (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 넓이를 구하는 식이 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"(반지름) × 2 × (원주율)","correct":true},{"t":"(반지름) × (원주) × ⟨1/2⟩","mis":"M6-2-u5-X19"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X19"},{"t":"(반지름) × (지름) × (원주율) × ⟨1/2⟩","mis":"M6-2-u5-X19"}],"explanation":["(원의 넓이) = (반지름) × (원주) × ⟨1/2⟩이에요.","원주 대신 (지름) × (원주율)을 넣고 정리하면 (반지름) × (반지름) × (원주율)이에요.","(반지름) × 2 × (원주율)은 넓이를 구하는 식이 아니에요."]},{"stem":"이번에는 다른 보기예요. 원의 넓이를 구하는 방법을 식으로 잘못 나타낸 것은 어느 것인가요?","options":[{"t":"(지름) × (지름) × (원주율)","correct":true},{"t":"(반지름) × (원주) × ⟨1/2⟩","mis":"M6-2-u5-X19"},{"t":"(반지름) × (반지름) × (원주율)","mis":"M6-2-u5-X19"},{"t":"(반지름) × (지름) × (원주율) × ⟨1/2⟩","mis":"M6-2-u5-X19"}],"explanation":["(원의 넓이) = (반지름) × (원주) × ⟨1/2⟩이에요.","원주 대신 (지름) × (원주율)을 넣고 정리하면 (반지름) × (반지름) × (원주율)이에요.","(지름) × (지름) × (원주율)은 넓이를 구하는 식이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#9','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',2,'mc','auto','반지름이 30 cm인 원 모양 거울이 있어요. 이 거울의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":9,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"반지름이 30 cm인 원 모양 거울이 있어요. 이 거울의 넓이는 몇 cm²인가요?","options":[{"t":"2826 cm²","correct":true},{"t":"188.4 cm²","mis":"M6-2-u5-X12"},{"t":"94.2 cm²","mis":"M6-2-u5-X14"},{"t":"11304 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","30 × 30 × 3.14를 계산해요.","30 × 30 × 3.14 = 2826 — 넓이는 2826 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 20 cm인 원 모양 식탁보가 있어요. 이 식탁보의 넓이는 몇 cm²인가요?","options":[{"t":"1256 cm²","correct":true},{"t":"125.6 cm²","mis":"M6-2-u5-X12"},{"t":"62.8 cm²","mis":"M6-2-u5-X14"},{"t":"5024 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","20 × 20 × 3.14를 계산해요.","20 × 20 × 3.14 = 1256 — 넓이는 1256 cm²예요."]},{"stem":"반지름이 15 cm인 원 모양 매트가 있어요. 이 매트의 넓이는 몇 cm²인가요?","options":[{"t":"706.5 cm²","correct":true},{"t":"94.2 cm²","mis":"M6-2-u5-X12"},{"t":"47.1 cm²","mis":"M6-2-u5-X14"},{"t":"2826 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","15 × 15 × 3.14를 계산해요.","15 × 15 × 3.14 = 706.5 — 넓이는 706.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_basic#10','math',6,2,'u5','L06','g6_2_math_u5_L06_basic','lesson_basic','M6-2-u5-C6',3,'sa','auto','넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."]},{"stem":"넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["(반지름) × (반지름) × 3.14 = 28.26이에요.","28.26 ÷ 3.14 = 9니 (반지름) × (반지름) = 9예요.","같은 수를 두 번 곱해 9가 되는 수는 3 — 반지름은 3 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#1','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',2,'mc','auto','반지름이 7 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":1,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"반지름이 7 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"43.96 cm²","mis":"M6-2-u5-X12"},{"t":"21.98 cm²","mis":"M6-2-u5-X14"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","7 × 7 × 3.14를 계산해요.","7 × 7 × 3.14 = 153.86 — 넓이는 153.86 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 8 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X12"},{"t":"25.12 cm²","mis":"M6-2-u5-X14"},{"t":"803.84 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","8 × 8 × 3.14를 계산해요.","8 × 8 × 3.14 = 200.96 — 넓이는 200.96 cm²예요."]},{"stem":"반지름이 9 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"254.34 cm²","correct":true},{"t":"56.52 cm²","mis":"M6-2-u5-X12"},{"t":"28.26 cm²","mis":"M6-2-u5-X14"},{"t":"1017.36 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","9 × 9 × 3.14를 계산해요.","9 × 9 × 3.14 = 254.34 — 넓이는 254.34 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#2','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',2,'sa','auto','넓이가 314 cm²인 원 모양 접시가 있어요. 이 접시의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C6","difficulty":2,"kind":"sa","stem":"넓이가 314 cm²인 원 모양 접시가 있어요. 이 접시의 지름은 몇 cm인가요?","answer":["20"],"explanation":["314 ÷ 3.14 = 100 — (반지름) × (반지름) = 100이에요.","반지름은 10 cm예요.","지름은 반지름의 2배 — 20 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 50.24 cm²인 원 모양 접시가 있어요. 이 접시의 지름은 몇 cm인가요?","answer":["8"],"explanation":["50.24 ÷ 3.14 = 16 — (반지름) × (반지름) = 16이에요.","반지름은 4 cm예요.","지름은 반지름의 2배 — 8 cm예요."]},{"stem":"넓이가 113.04 cm²인 원 모양 접시가 있어요. 이 접시의 지름은 몇 cm인가요?","answer":["12"],"explanation":["113.04 ÷ 3.14 = 36 — (반지름) × (반지름) = 36이에요.","반지름은 6 cm예요.","지름은 반지름의 2배 — 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#3','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'error','auto','반지름이 4 cm인 원의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C6","difficulty":3,"kind":"error","stem":"반지름이 4 cm인 원의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「8 × 8 × 3.14 = 200.96이야.」","correct":true,"mis_target":"M6-2-u5-X13"},{"t":"나린 — 「4 × 4 × 3.14 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「12.56 × 4 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「넓이는 50.24 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","가온는 지름 8 cm를 두 번 곱했어요.","바른 넓이는 4 × 4 × 3.14 = 50.24 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"수아 — 「10 × 10 × 3.14 = 314야.」","correct":true,"mis_target":"M6-2-u5-X13"},{"t":"하린 — 「5 × 5 × 3.14 = 78.5야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「15.7 × 5 = 78.5야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「넓이는 78.5 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","수아는 지름 10 cm를 두 번 곱했어요.","바른 넓이는 5 × 5 × 3.14 = 78.5 cm²예요."]},{"stem":"반지름이 3 cm인 원의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"서아 — 「6 × 6 × 3.14 = 113.04야.」","correct":true,"mis_target":"M6-2-u5-X13"},{"t":"지호 — 「3 × 3 × 3.14 = 28.26이야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「9.42 × 3 = 28.26이야.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「넓이는 28.26 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","서아는 지름 6 cm를 두 번 곱했어요.","바른 넓이는 3 × 3 × 3.14 = 28.26 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#4','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'ox','auto','원의 넓이는 (반지름) × (원주) × ⟨1/2⟩로도 구할 수 있어요.',ARRAY['M6-2-u5-X15']::text[],true,'{"seq":4,"concept":"M6-2-u5-C6","difficulty":3,"kind":"ox","stem":"원의 넓이는 (반지름) × (원주) × ⟨1/2⟩로도 구할 수 있어요.","answer":"O","reason_options":[{"t":"이어 붙인 직사각형의 가로가 원주의 반, 세로가 반지름이기 때문에","correct":true},{"t":"원주의 반이 넓이이기 때문에","mis":"M6-2-u5-X15"}],"mis":"M6-2-u5-X15","explanation":["원을 잘라 이어 붙인 직사각형은 가로가 원주의 반, 세로가 반지름이에요.","그래서 넓이는 (반지름) × (원주) × ⟨1/2⟩ = (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 원주예요."],"variant_rule":{"alt":[{"stem":"원의 넓이는 (지름) × (원주율)로 구해요.","answer":"X","reason_options":[{"t":"(지름) × (원주율)은 원주를 구하는 식이기 때문에","correct":true},{"t":"넓이도 둘레처럼 지름에 원주율을 곱하기 때문에","mis":"M6-2-u5-X12"}],"explanation":["원을 잘라 이어 붙인 직사각형은 가로가 원주의 반, 세로가 반지름이에요.","그래서 넓이는 (반지름) × (원주) × ⟨1/2⟩ = (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 원주예요."]},{"stem":"반지름이 5 cm인 원의 넓이는 5 × 3.14로 구해요.","answer":"X","reason_options":[{"t":"반지름을 두 번 곱해 5 × 5 × 3.14로 구해야 하기 때문에","correct":true},{"t":"반지름에 원주율을 한 번 곱하면 넓이이기 때문에","mis":"M6-2-u5-X14"}],"explanation":["원을 잘라 이어 붙인 직사각형은 가로가 원주의 반, 세로가 반지름이에요.","그래서 넓이는 (반지름) × (원주) × ⟨1/2⟩ = (반지름) × (반지름) × (원주율)이에요.","(지름) × (원주율)은 원주예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#5','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'match','auto','반지름과 원의 넓이를 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C6","difficulty":3,"kind":"match","stem":"반지름과 원의 넓이를 이으세요.","pairs":[{"l":"반지름 1 cm","r":"3.14 cm²"},{"l":"반지름 2 cm","r":"12.56 cm²"},{"l":"반지름 5 cm","r":"78.5 cm²"}],"mis":"M6-2-u5-X14","explanation":["(원의 넓이) = (반지름) × (반지름) × 3.14예요.","1 × 1 × 3.14 = 3.14 · 2 × 2 × 3.14 = 12.56이에요.","5 × 5 × 3.14 = 78.5예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 반지름과 원의 넓이를 이으세요.","pairs":[{"l":"반지름 3 cm","r":"28.26 cm²"},{"l":"반지름 4 cm","r":"50.24 cm²"},{"l":"반지름 10 cm","r":"314 cm²"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × 3.14예요.","3 × 3 × 3.14 = 28.26 · 4 × 4 × 3.14 = 50.24예요.","10 × 10 × 3.14 = 314예요."]},{"stem":"이번에는 다른 보기예요. 반지름과 원의 넓이를 이으세요.","pairs":[{"l":"반지름 6 cm","r":"113.04 cm²"},{"l":"반지름 7 cm","r":"153.86 cm²"},{"l":"반지름 8 cm","r":"200.96 cm²"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × 3.14예요.","6 × 6 × 3.14 = 113.04 · 7 × 7 × 3.14 = 153.86이에요.","8 × 8 × 3.14 = 200.96이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#6','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'mc','auto','원주가 31.4 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":6,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"원주가 31.4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm, 반지름은 5 cm예요.","넓이는 5 × 5 × 3.14예요.","5 × 5 × 3.14 = 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"원주가 18.84 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X13"},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 18.84 ÷ 3.14 = 6 cm, 반지름은 3 cm예요.","넓이는 3 × 3 × 3.14예요.","3 × 3 × 3.14 = 28.26 cm²예요."]},{"stem":"원주가 62.8 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["지름은 62.8 ÷ 3.14 = 20 cm, 반지름은 10 cm예요.","넓이는 10 × 10 × 3.14예요.","10 × 10 × 3.14 = 314 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#7','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',3,'mc','auto','원을 한없이 잘라 이어 붙였더니 가로 15.7 cm, 세로 5 cm인 직사각형이 되었어요. 처음 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X15','M6-2-u5-X12','M6-2-u5-X20']::text[],true,'{"seq":7,"concept":"M6-2-u5-C6","difficulty":3,"kind":"mc","stem":"원을 한없이 잘라 이어 붙였더니 가로 15.7 cm, 세로 5 cm인 직사각형이 되었어요. 처음 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"157 cm²","mis":"M6-2-u5-X15"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"20.7 cm²","mis":"M6-2-u5-X20"}],"explanation":["자르고 이어 붙였을 뿐이니 넓이는 그대로예요.","직사각형의 넓이는 15.7 × 5예요.","15.7 × 5 = 78.5 — 원의 넓이도 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"원을 한없이 잘라 이어 붙였더니 가로 9.42 cm, 세로 3 cm인 직사각형이 되었어요. 처음 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"56.52 cm²","mis":"M6-2-u5-X15"},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"12.42 cm²","mis":"M6-2-u5-X20"}],"explanation":["자르고 이어 붙였을 뿐이니 넓이는 그대로예요.","직사각형의 넓이는 9.42 × 3이에요.","9.42 × 3 = 28.26 — 원의 넓이도 28.26 cm²예요."]},{"stem":"원을 한없이 잘라 이어 붙였더니 가로 31.4 cm, 세로 10 cm인 직사각형이 되었어요. 처음 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"628 cm²","mis":"M6-2-u5-X15"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"41.4 cm²","mis":"M6-2-u5-X20"}],"explanation":["자르고 이어 붙였을 뿐이니 넓이는 그대로예요.","직사각형의 넓이는 31.4 × 10이에요.","31.4 × 10 = 314 — 원의 넓이도 314 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#8','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',4,'mc','auto','가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":8,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X19"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 30 cm, 세로가 16 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X19"},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 16 cm를 넘을 수 없어요.","반지름은 8 cm예요.","8 × 8 × 3.14 = 200.96 cm²예요."]},{"stem":"가로가 12 cm, 세로가 25 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"490.625 cm²","mis":"M6-2-u5-X19"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#9','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',4,'mc','auto','길이가 62.8 cm인 끈으로 원 하나와 정사각형 하나를 각각 만들었어요. 넓이가 더 넓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X14','M6-2-u5-X19']::text[],true,'{"seq":9,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"길이가 62.8 cm인 끈으로 원 하나와 정사각형 하나를 각각 만들었어요. 넓이가 더 넓은 것은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"정사각형","mis":"M6-2-u5-X20"},{"t":"두 넓이가 같다","mis":"M6-2-u5-X14"},{"t":"비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원은 지름 20 cm, 반지름 10 cm — 넓이 314 cm²예요.","정사각형은 한 변 15.7 cm — 넓이 246.49 cm²예요.","둘레가 같을 때 원이 더 넓어요."],"variant_rule":{"alt":[{"stem":"길이가 125.6 cm인 끈으로 원 하나와 정사각형 하나를 각각 만들었어요. 넓이가 더 넓은 것은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"정사각형","mis":"M6-2-u5-X20"},{"t":"두 넓이가 같다","mis":"M6-2-u5-X14"},{"t":"비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원은 지름 40 cm, 반지름 20 cm — 넓이 1256 cm²예요.","정사각형은 한 변 31.4 cm — 넓이 985.96 cm²예요.","둘레가 같을 때 원이 더 넓어요."]},{"stem":"길이가 31.4 cm인 끈으로 원 하나와 정사각형 하나를 각각 만들었어요. 넓이가 더 넓은 것은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"정사각형","mis":"M6-2-u5-X20"},{"t":"두 넓이가 같다","mis":"M6-2-u5-X14"},{"t":"비교할 수 없다","mis":"M6-2-u5-X19"}],"explanation":["원은 지름 10 cm, 반지름 5 cm — 넓이 78.5 cm²예요.","정사각형은 한 변 7.85 cm — 넓이 61.6225 cm²예요.","둘레가 같을 때 원이 더 넓어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L06_challenge#10','math',6,2,'u5','L06','g6_2_math_u5_L06_challenge','lesson_challenge','M6-2-u5-C6',4,'essay','teacher','원을 한없이 잘라 이어 붙인 직사각형을 이용하여 (원의 넓이) = (반지름) × (반지름) × (원주율)이 되는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C6","difficulty":4,"kind":"essay","stem":"원을 한없이 잘라 이어 붙인 직사각형을 이용하여 (원의 넓이) = (반지름) × (반지름) × (원주율)이 되는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원을 한없이 잘라 이어 붙이면 가로가 원주의 반, 세로가 반지름인 직사각형이 된다. 넓이는 (원주) × ⟨1/2⟩ × (반지름)이고, 원주는 (지름) × (원주율)이며 지름의 반은 반지름이므로 (반지름) × (반지름) × (원주율)이 된다.","scoring_points":["직사각형의 가로가 원주의 반, 세로가 반지름임을 밝혔는가","원주 = (지름) × (원주율)을 넣었는가","지름의 반이 반지름임을 써서 식을 완성했는가"]},"explanation":["가로는 원주의 반, 세로는 반지름이에요.","원주의 반은 (지름) × (원주율) × ⟨1/2⟩ = (반지름) × (원주율)이에요.","그래서 넓이는 (반지름) × (반지름) × (원주율)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#1','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'mc','auto','달곰이 작품의 가 부분은 반지름이 1 cm인 원이에요. 가 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X13','M6-2-u5-X17']::text[],true,'{"seq":1,"concept":"M6-2-u5-C7","difficulty":1,"kind":"mc","stem":"달곰이 작품의 가 부분은 반지름이 1 cm인 원이에요. 가 부분의 넓이는 몇 cm²인가요?","options":[{"t":"3.14 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X13"},{"t":"1.57 cm²","mis":"M6-2-u5-X17"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","1 × 1 × 3.14를 계산해요.","1 × 1 × 3.14 = 3.14 — 넓이는 3.14 cm²예요."],"variant_rule":{"alt":[{"stem":"여울이 작품의 한가운데는 반지름이 2 cm인 원이에요. 이 부분의 넓이는 몇 cm²인가요?","options":[{"t":"12.56 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X14"},{"t":"50.24 cm²","mis":"M6-2-u5-X13"},{"t":"4 cm²","mis":"M6-2-u5-X20"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","2 × 2 × 3.14를 계산해요.","2 × 2 × 3.14 = 12.56 — 넓이는 12.56 cm²예요."]},{"stem":"순달이 작품의 한가운데는 반지름이 3 cm인 원이에요. 이 부분의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#2','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'mc','auto','나 부분은 반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":2,"concept":"M6-2-u5-C7","difficulty":1,"kind":"mc","stem":"나 부분은 반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 - 3.14 = 47.1 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"25.12 cm²","correct":true},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"12.56 cm²","mis":"M6-2-u5-X16"},{"t":"31.4 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 3 × 3 × 3.14 = 28.26 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","28.26 - 3.14 = 25.12 cm²예요."]},{"stem":"반지름이 5 cm인 원에서 반지름이 2 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"65.94 cm²","correct":true},{"t":"78.5 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"91.06 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 5 × 5 × 3.14 = 78.5 cm²예요.","작은 원의 넓이는 2 × 2 × 3.14 = 12.56 cm²예요.","78.5 - 12.56 = 65.94 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#3','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'sa','auto','아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 10 cm, 세로 5 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C7","difficulty":1,"kind":"sa","stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 10 cm, 세로 5 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","10 × 5 = 50 cm²예요."],"variant_rule":{"alt":[{"stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 8 cm, 세로 4 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["32"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","8 × 4 = 32 cm²예요."]},{"stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 12 cm, 세로 6 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","12 × 6 = 72 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#4','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',1,'mc','auto','원의 일부를 잘라서 다른 자리로 옮겨 붙이면 넓이는 어떻게 되나요?',ARRAY['M6-2-u5-X17']::text[],true,'{"seq":4,"concept":"M6-2-u5-C7","difficulty":1,"kind":"mc","stem":"원의 일부를 잘라서 다른 자리로 옮겨 붙이면 넓이는 어떻게 되나요?","options":[{"t":"변하지 않아요","correct":true},{"t":"넓어져요","mis":"M6-2-u5-X17"},{"t":"좁아져요","mis":"M6-2-u5-X17"},{"t":"두 배가 돼요","mis":"M6-2-u5-X17"}],"explanation":["조각을 더하지도 덜어 내지도 않았어요.","자리만 옮기면 모양은 변해도 넓이는 그대로예요.","5학년 때 평행사변형을 직사각형으로 바꾼 것과 같은 방법이에요."],"variant_rule":{"alt":[{"stem":"반원 하나를 잘라 반대쪽에 붙여 새 모양을 만들었어요. 처음 모양과 견주어 넓이는 어떻게 되나요?","options":[{"t":"변하지 않아요","correct":true},{"t":"넓어져요","mis":"M6-2-u5-X17"},{"t":"좁아져요","mis":"M6-2-u5-X17"},{"t":"두 배가 돼요","mis":"M6-2-u5-X17"}],"explanation":["조각을 더하지도 덜어 내지도 않았어요.","자리만 옮기면 모양은 변해도 넓이는 그대로예요.","5학년 때 평행사변형을 직사각형으로 바꾼 것과 같은 방법이에요."]},{"stem":"부채꼴 조각을 번갈아 뒤집어 이어 붙였어요. 처음 원과 견주어 넓이는 어떻게 되나요?","options":[{"t":"변하지 않아요","correct":true},{"t":"넓어져요","mis":"M6-2-u5-X17"},{"t":"좁아져요","mis":"M6-2-u5-X17"},{"t":"두 배가 돼요","mis":"M6-2-u5-X17"}],"explanation":["조각을 더하지도 덜어 내지도 않았어요.","자리만 옮기면 모양은 변해도 넓이는 그대로예요.","5학년 때 평행사변형을 직사각형으로 바꾼 것과 같은 방법이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#5','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','다 부분은 반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":5,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"다 부분은 반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 - 50.24 = 103.62 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"84.78 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"141.3 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","작은 원의 넓이는 3 × 3 × 3.14 = 28.26 cm²예요.","113.04 - 28.26 = 84.78 cm²예요."]},{"stem":"반지름이 8 cm인 원에서 반지름이 5 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"122.46 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"279.46 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 8 × 8 × 3.14 = 200.96 cm²예요.","작은 원의 넓이는 5 × 5 × 3.14 = 78.5 cm²예요.","200.96 - 78.5 = 122.46 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#6','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','반지름이 4 cm인 반원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":6,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 4 cm인 반원의 넓이는 몇 cm²인가요?","options":[{"t":"25.12 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X17"},{"t":"12.56 cm²","mis":"M6-2-u5-X17"},{"t":"100.48 cm²","mis":"M6-2-u5-X13"}],"explanation":["반원은 원을 똑같이 2로 나눈 것 가운데 하나예요.","원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","50.24 ÷ 2 = 25.12 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 반원의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X17"},{"t":"28.26 cm²","mis":"M6-2-u5-X17"},{"t":"18.84 cm²","mis":"M6-2-u5-X12"}],"explanation":["반원은 원을 똑같이 2로 나눈 것 가운데 하나예요.","원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","113.04 ÷ 2 = 56.52 cm²예요."]},{"stem":"반지름이 10 cm인 사분원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"15.7 cm²","mis":"M6-2-u5-X12"}],"explanation":["사분원은 원을 똑같이 4로 나눈 것 가운데 하나예요.","원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","314 ÷ 4 = 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#7','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":7,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X17"},{"t":"226.08 cm²","mis":"M6-2-u5-X13"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 24 ÷ 2 = 12 cm예요.","피자 전체는 12 × 12 × 3.14 = 452.16 cm²예요.","8조각 중 한 조각은 452.16 ÷ 8 = 56.52 cm²예요."],"variant_rule":{"alt":[{"stem":"하린은 지름이 20 cm인 원 모양 팬케이크를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 하린이 먹은 팬케이크의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"15.7 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 20 ÷ 2 = 10 cm예요.","팬케이크 전체는 10 × 10 × 3.14 = 314 cm²예요.","4조각 중 한 조각은 314 ÷ 4 = 78.5 cm²예요."]},{"stem":"도윤은 지름이 30 cm인 원 모양 케이크를 똑같이 6조각으로 나눈 것 가운데 한 조각을 먹었어요. 도윤이 먹은 케이크의 넓이는 몇 cm²인가요?","options":[{"t":"117.75 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X17"},{"t":"471 cm²","mis":"M6-2-u5-X13"},{"t":"235.5 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 30 ÷ 2 = 15 cm예요.","케이크 전체는 15 × 15 × 3.14 = 706.5 cm²예요.","6조각 중 한 조각은 706.5 ÷ 6 = 117.75 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#8','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','꽃밭 가는 반지름이 4 m인 원 모양이고, 꽃밭 나는 반지름이 8 m인 원의 사분원 모양이에요. 두 꽃밭의 넓이를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X18','M6-2-u5-X19']::text[],true,'{"seq":8,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"꽃밭 가는 반지름이 4 m인 원 모양이고, 꽃밭 나는 반지름이 8 m인 원의 사분원 모양이에요. 두 꽃밭의 넓이를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"가와 나의 넓이가 같아요","correct":true},{"t":"가가 나보다 넓어요","mis":"M6-2-u5-X17"},{"t":"나가 가보다 넓어요","mis":"M6-2-u5-X18"},{"t":"넓이를 비교할 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["가는 4 × 4 × 3.14 = 50.24 m²예요.","나는 8 × 8 × 3.14 ÷ 4 = 50.24 m²예요.","두 꽃밭의 넓이는 같아요."],"variant_rule":{"alt":[{"stem":"꽃밭 가는 반지름이 3 m인 원 모양이고, 꽃밭 나는 반지름이 6 m인 원의 사분원 모양이에요. 두 꽃밭의 넓이를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"가와 나의 넓이가 같아요","correct":true},{"t":"가가 나보다 넓어요","mis":"M6-2-u5-X17"},{"t":"나가 가보다 넓어요","mis":"M6-2-u5-X18"},{"t":"넓이를 비교할 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["가는 3 × 3 × 3.14 = 28.26 m²예요.","나는 6 × 6 × 3.14 ÷ 4 = 28.26 m²예요.","두 꽃밭의 넓이는 같아요."]},{"stem":"꽃밭 가는 반지름이 5 m인 원 모양이고, 꽃밭 나는 반지름이 10 m인 원의 사분원 모양이에요. 두 꽃밭의 넓이를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"가와 나의 넓이가 같아요","correct":true},{"t":"가가 나보다 넓어요","mis":"M6-2-u5-X17"},{"t":"나가 가보다 넓어요","mis":"M6-2-u5-X18"},{"t":"넓이를 비교할 수 없어요","mis":"M6-2-u5-X19"}],"explanation":["가는 5 × 5 × 3.14 = 78.5 m²예요.","나는 10 × 10 × 3.14 ÷ 4 = 78.5 m²예요.","두 꽃밭의 넓이는 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#9','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',2,'mc','auto','반지름이 10 cm인 큰 원 안에 반지름이 5 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X16','M6-2-u5-X19']::text[],true,'{"seq":9,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 10 cm인 큰 원 안에 반지름이 5 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"157 cm²","correct":true},{"t":"235.5 cm²","mis":"M6-2-u5-X17"},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"78.5 cm²","mis":"M6-2-u5-X19"}],"explanation":["큰 원은 10 × 10 × 3.14 = 314 cm²예요.","작은 원 하나는 5 × 5 × 3.14 = 78.5 cm², 두 개는 157 cm²예요.","314 - 157 = 157 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 8 cm인 큰 원 안에 반지름이 4 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"100.48 cm²","correct":true},{"t":"150.72 cm²","mis":"M6-2-u5-X17"},{"t":"200.96 cm²","mis":"M6-2-u5-X16"},{"t":"50.24 cm²","mis":"M6-2-u5-X19"}],"explanation":["큰 원은 8 × 8 × 3.14 = 200.96 cm²예요.","작은 원 하나는 4 × 4 × 3.14 = 50.24 cm², 두 개는 100.48 cm²예요.","200.96 - 100.48 = 100.48 cm²예요."]},{"stem":"반지름이 6 cm인 큰 원 안에 반지름이 3 cm인 원 두 개가 들어 있어요. 큰 원에서 작은 원 두 개를 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"84.78 cm²","mis":"M6-2-u5-X17"},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X19"}],"explanation":["큰 원은 6 × 6 × 3.14 = 113.04 cm²예요.","작은 원 하나는 3 × 3 × 3.14 = 28.26 cm², 두 개는 56.52 cm²예요.","113.04 - 56.52 = 56.52 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_basic#10','math',6,2,'u5','L07','g6_2_math_u5_L07_basic','lesson_basic','M6-2-u5-C7',3,'sa','auto','한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u5-C7","difficulty":3,"kind":"sa","stem":"한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","400 - 314 = 86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 20 cm, 세로 10 cm인 직사각형 안에 반지름이 10 cm인 반원이 꼭 맞게 들어 있어요. 직사각형에서 반원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["43"],"explanation":["직사각형의 넓이는 20 × 10 = 200 cm²예요.","반원은 10 × 10 × 3.14 ÷ 2 = 157 cm²예요.","200 - 157 = 43 cm²예요."]},{"stem":"한 변이 20 cm인 정사각형의 한 꼭짓점을 중심으로 반지름이 20 cm인 사분원을 그렸어요. 정사각형에서 사분원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","사분원은 20 × 20 × 3.14 ÷ 4 = 314 cm²예요.","400 - 314 = 86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#1','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',2,'mc','auto','라 부분은 반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":1,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"라 부분은 반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 - 153.86 = 160.14 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 9 cm인 원에서 반지름이 6 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"141.3 cm²","correct":true},{"t":"254.34 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"367.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 9 × 9 × 3.14 = 254.34 cm²예요.","작은 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","254.34 - 113.04 = 141.3 cm²예요."]},{"stem":"반지름이 12 cm인 원에서 반지름이 10 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"138.16 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X16"},{"t":"12.56 cm²","mis":"M6-2-u5-X16"},{"t":"766.16 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 12 × 12 × 3.14 = 452.16 cm²예요.","작은 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","452.16 - 314 = 138.16 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#2','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',2,'mc','auto','반지름이 8 cm인 사분원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X12']::text[],true,'{"seq":2,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 8 cm인 사분원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X17"},{"t":"100.48 cm²","mis":"M6-2-u5-X17"},{"t":"12.56 cm²","mis":"M6-2-u5-X12"}],"explanation":["사분원은 원을 똑같이 4로 나눈 것 가운데 하나예요.","원의 넓이는 8 × 8 × 3.14 = 200.96 cm²예요.","200.96 ÷ 4 = 50.24 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 12 cm인 반원의 넓이는 몇 cm²인가요?","options":[{"t":"226.08 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X17"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["반원은 원을 똑같이 2로 나눈 것 가운데 하나예요.","원의 넓이는 12 × 12 × 3.14 = 452.16 cm²예요.","452.16 ÷ 2 = 226.08 cm²예요."]},{"stem":"반지름이 2 cm인 사분원의 넓이는 몇 cm²인가요?","options":[{"t":"3.14 cm²","correct":true},{"t":"12.56 cm²","mis":"M6-2-u5-X17"},{"t":"6.28 cm²","mis":"M6-2-u5-X17"},{"t":"25.12 cm²","mis":"M6-2-u5-X20"}],"explanation":["사분원은 원을 똑같이 4로 나눈 것 가운데 하나예요.","원의 넓이는 2 × 2 × 3.14 = 12.56 cm²예요.","12.56 ÷ 4 = 3.14 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#3','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'error','auto','반지름이 5 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C7","difficulty":3,"kind":"error","stem":"반지름이 5 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「5 - 3 = 2니 2 × 2 × 3.14 = 12.56이야.」","correct":true,"mis_target":"M6-2-u5-X16"},{"t":"나린 — 「78.5 - 28.26 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「(5 × 5 - 3 × 3) × 3.14 = 50.24야.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「넓이는 50.24 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["고리의 넓이는 큰 원의 넓이에서 작은 원의 넓이를 빼요.","반지름의 차로 원을 그리면 고리와 넓이가 달라요.","바른 넓이는 50.24 cm² — 가온의 방법이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원에서 반지름이 2 cm인 원을 뺀 고리 모양의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"수아 — 「6 - 2 = 4니 4 × 4 × 3.14 = 50.24야.」","correct":true,"mis_target":"M6-2-u5-X16"},{"t":"하린 — 「113.04 - 12.56 = 100.48이야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「(6 × 6 - 2 × 2) × 3.14 = 100.48이야.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「넓이는 100.48 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["고리의 넓이는 큰 원의 넓이에서 작은 원의 넓이를 빼요.","반지름의 차로 원을 그리면 고리와 넓이가 달라요.","바른 넓이는 100.48 cm² — 수아의 방법이 잘못되었어요."]},{"stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"서아 — 「7 - 4 = 3이니 3 × 3 × 3.14 = 28.26이야.」","correct":true,"mis_target":"M6-2-u5-X16"},{"t":"지호 — 「153.86 - 50.24 = 103.62야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「(7 × 7 - 4 × 4) × 3.14 = 103.62야.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「넓이는 103.62 cm²야.」","mis":"M6-2-u5-X19"}],"explanation":["고리의 넓이는 큰 원의 넓이에서 작은 원의 넓이를 빼요.","반지름의 차로 원을 그리면 고리와 넓이가 달라요.","바른 넓이는 103.62 cm² — 서아의 방법이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#4','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'ox','auto','반지름이 4 m인 원과 반지름이 8 m인 사분원은 넓이가 같아요.',ARRAY['M6-2-u5-X17']::text[],true,'{"seq":4,"concept":"M6-2-u5-C7","difficulty":3,"kind":"ox","stem":"반지름이 4 m인 원과 반지름이 8 m인 사분원은 넓이가 같아요.","answer":"O","reason_options":[{"t":"8 × 8 × 3.14 ÷ 4 = 4 × 4 × 3.14이기 때문에","correct":true},{"t":"사분원은 원의 반이기 때문에","mis":"M6-2-u5-X17"}],"mis":"M6-2-u5-X17","explanation":["고리 모양은 큰 원에서 작은 원을 빼요.","반원·사분원은 원의 넓이를 2·4로 나누어요.","자리만 옮기면 넓이는 그대로예요."],"variant_rule":{"alt":[{"stem":"고리 모양의 넓이는 두 반지름의 차를 반지름으로 하는 원의 넓이와 같아요.","answer":"X","reason_options":[{"t":"큰 원의 넓이에서 작은 원의 넓이를 빼야 하기 때문에","correct":true},{"t":"고리의 폭이 반지름의 차이기 때문에","mis":"M6-2-u5-X16"}],"explanation":["고리 모양은 큰 원에서 작은 원을 빼요.","반원·사분원은 원의 넓이를 2·4로 나누어요.","자리만 옮기면 넓이는 그대로예요."]},{"stem":"원을 잘라 다른 자리에 옮겨 붙이면 넓이가 넓어져요.","answer":"X","reason_options":[{"t":"조각을 더하거나 덜지 않고 자리만 옮겼기 때문에","correct":true},{"t":"모양이 바뀌면 넓이도 바뀌기 때문에","mis":"M6-2-u5-X17"}],"explanation":["고리 모양은 큰 원에서 작은 원을 빼요.","반원·사분원은 원의 넓이를 2·4로 나누어요.","자리만 옮기면 넓이는 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#5','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'match','auto','반지름이 2 cm인 도형과 넓이를 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C7","difficulty":3,"kind":"match","stem":"반지름이 2 cm인 도형과 넓이를 이으세요.","pairs":[{"l":"원","r":"12.56 cm²"},{"l":"반원","r":"6.28 cm²"},{"l":"사분원","r":"3.14 cm²"}],"mis":"M6-2-u5-X17","explanation":["원의 넓이는 2 × 2 × 3.14 = 12.56 cm²예요.","반원은 그 반 — 6.28 cm²예요.","사분원은 4로 나눈 하나 — 3.14 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 도형과 넓이를 이으세요.","pairs":[{"l":"원","r":"50.24 cm²"},{"l":"반원","r":"25.12 cm²"},{"l":"사분원","r":"12.56 cm²"}],"explanation":["원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","반원은 그 반 — 25.12 cm²예요.","사분원은 4로 나눈 하나 — 12.56 cm²예요."]},{"stem":"반지름이 10 cm인 도형과 넓이를 이으세요.","pairs":[{"l":"원","r":"314 cm²"},{"l":"반원","r":"157 cm²"},{"l":"사분원","r":"78.5 cm²"}],"explanation":["원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","반원은 그 반 — 157 cm²예요.","사분원은 4로 나눈 하나 — 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#6','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'mc','auto','가로 20 cm, 세로 10 cm인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":6,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"가로 20 cm, 세로 10 cm인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 cm²인가요?","options":[{"t":"278.5 cm²","correct":true},{"t":"239.25 cm²","mis":"M6-2-u5-X17"},{"t":"357 cm²","mis":"M6-2-u5-X17"},{"t":"514 cm²","mis":"M6-2-u5-X13"}],"explanation":["직사각형은 20 × 10 = 200 cm²예요.","양쪽 반원 두 개를 모으면 반지름 5 cm인 원 하나 — 78.5 cm²예요.","200 + 78.5 = 278.5 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 30 cm, 세로 20 cm인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 cm²인가요?","options":[{"t":"914 cm²","correct":true},{"t":"757 cm²","mis":"M6-2-u5-X17"},{"t":"1228 cm²","mis":"M6-2-u5-X17"},{"t":"1856 cm²","mis":"M6-2-u5-X13"}],"explanation":["직사각형은 30 × 20 = 600 cm²예요.","양쪽 반원 두 개를 모으면 반지름 10 cm인 원 하나 — 314 cm²예요.","600 + 314 = 914 cm²예요."]},{"stem":"가로 10 cm, 세로 8 cm인 직사각형의 양쪽 세로 변에 반원을 하나씩 붙인 운동장 모양이 있어요. 전체 넓이는 몇 cm²인가요?","options":[{"t":"130.24 cm²","correct":true},{"t":"105.12 cm²","mis":"M6-2-u5-X17"},{"t":"180.48 cm²","mis":"M6-2-u5-X17"},{"t":"280.96 cm²","mis":"M6-2-u5-X13"}],"explanation":["직사각형은 10 × 8 = 80 cm²예요.","양쪽 반원 두 개를 모으면 반지름 4 cm인 원 하나 — 50.24 cm²예요.","80 + 50.24 = 130.24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#7','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',3,'mc','auto','바깥쪽 원의 반지름이 6 cm이고 폭이 2 cm인 고리 모양 과녁 띠가 있어요. 이 띠의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X01']::text[],true,'{"seq":7,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 반지름이 6 cm이고 폭이 2 cm인 고리 모양 과녁 띠가 있어요. 이 띠의 넓이는 몇 cm²인가요?","options":[{"t":"62.8 cm²","correct":true},{"t":"12.56 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"100.48 cm²","mis":"M6-2-u5-X01"}],"explanation":["안쪽 원의 반지름은 6 - 2 = 4 cm예요.","큰 원 113.04 cm²에서 작은 원 50.24 cm²를 빼요.","113.04 - 50.24 = 62.8 cm²예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 반지름이 10 cm이고 폭이 3 cm인 고리 모양 과녁 띠가 있어요. 이 띠의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"285.74 cm²","mis":"M6-2-u5-X01"}],"explanation":["안쪽 원의 반지름은 10 - 3 = 7 cm예요.","큰 원 314 cm²에서 작은 원 153.86 cm²를 빼요.","314 - 153.86 = 160.14 cm²예요."]},{"stem":"바깥쪽 원의 반지름이 5 cm이고 폭이 1 cm인 고리 모양 과녁 띠가 있어요. 이 띠의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"3.14 cm²","mis":"M6-2-u5-X16"},{"t":"78.5 cm²","mis":"M6-2-u5-X16"},{"t":"75.36 cm²","mis":"M6-2-u5-X01"}],"explanation":["안쪽 원의 반지름은 5 - 1 = 4 cm예요.","큰 원 78.5 cm²에서 작은 원 50.24 cm²를 빼요.","78.5 - 50.24 = 28.26 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#8','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',4,'mc','auto','반지름이 10 cm인 원 안에 꼭 맞는 정사각형을 그렸어요. 원에서 정사각형을 뺀 부분의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X11','M6-2-u5-X17']::text[],true,'{"seq":8,"concept":"M6-2-u5-C7","difficulty":4,"kind":"mc","stem":"반지름이 10 cm인 원 안에 꼭 맞는 정사각형을 그렸어요. 원에서 정사각형을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"114 cm²","correct":true},{"t":"86 cm²","mis":"M6-2-u5-X11"},{"t":"214 cm²","mis":"M6-2-u5-X11"},{"t":"314 cm²","mis":"M6-2-u5-X17"}],"explanation":["원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","원 안 정사각형은 대각선이 20 cm — 20 × 20 ÷ 2 = 200 cm²예요.","314 - 200 = 114 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원 안에 꼭 맞는 정사각형을 그렸어요. 원에서 정사각형을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"28.5 cm²","correct":true},{"t":"21.5 cm²","mis":"M6-2-u5-X11"},{"t":"53.5 cm²","mis":"M6-2-u5-X11"},{"t":"78.5 cm²","mis":"M6-2-u5-X17"}],"explanation":["원의 넓이는 5 × 5 × 3.14 = 78.5 cm²예요.","원 안 정사각형은 대각선이 10 cm — 10 × 10 ÷ 2 = 50 cm²예요.","78.5 - 50 = 28.5 cm²예요."]},{"stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형을 그렸어요. 원에서 정사각형을 뺀 부분의 넓이는 몇 cm²인가요?","options":[{"t":"41.04 cm²","correct":true},{"t":"30.96 cm²","mis":"M6-2-u5-X11"},{"t":"77.04 cm²","mis":"M6-2-u5-X11"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","원 안 정사각형은 대각선이 12 cm — 12 × 12 ÷ 2 = 72 cm²예요.","113.04 - 72 = 41.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#9','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',4,'mc','auto','달곰이의 작품은 반지름이 1 cm, 4 cm, 7 cm, 10 cm인 원을 겹겹이 그린 모양이에요. 다 부분과 라 부분을 합한 넓이(반지름 10 cm인 원에서 반지름 4 cm인 원을 뺀 부분)는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":9,"concept":"M6-2-u5-C7","difficulty":4,"kind":"mc","stem":"달곰이의 작품은 반지름이 1 cm, 4 cm, 7 cm, 10 cm인 원을 겹겹이 그린 모양이에요. 다 부분과 라 부분을 합한 넓이(반지름 10 cm인 원에서 반지름 4 cm인 원을 뺀 부분)는 몇 cm²인가요?","options":[{"t":"263.76 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"364.24 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","314 - 50.24 = 263.76 cm²예요."],"variant_rule":{"alt":[{"stem":"달곰이의 작품은 반지름이 1 cm, 4 cm, 7 cm, 10 cm인 원을 겹겹이 그린 모양이에요. 나 부분과 다 부분을 합한 넓이(반지름 7 cm인 원에서 반지름 1 cm인 원을 뺀 부분)는 몇 cm²인가요?","options":[{"t":"150.72 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"157 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","153.86 - 3.14 = 150.72 cm²예요."]},{"stem":"달곰이의 작품은 반지름이 1 cm, 4 cm, 7 cm, 10 cm인 원을 겹겹이 그린 모양이에요. 나·다·라 부분을 합한 넓이(반지름 10 cm인 원에서 반지름 1 cm인 원을 뺀 부분)는 몇 cm²인가요?","options":[{"t":"310.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"254.34 cm²","mis":"M6-2-u5-X16"},{"t":"317.14 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","314 - 3.14 = 310.86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L07_challenge#10','math',6,2,'u5','L07','g6_2_math_u5_L07_challenge','lesson_challenge','M6-2-u5-C7',4,'essay','teacher','반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양의 넓이를 구하고, 친구가 (7 - 4) × (7 - 4) × 3.14로 구한 방법이 왜 틀렸는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C7","difficulty":4,"kind":"essay","stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양의 넓이를 구하고, 친구가 (7 - 4) × (7 - 4) × 3.14로 구한 방법이 왜 틀렸는지 설명해 보세요.","answer_guide":{"answer":"예: 고리의 넓이는 7 × 7 × 3.14 - 4 × 4 × 3.14 = 153.86 - 50.24 = 103.62 cm²이다. 반지름의 차 3 cm로 그린 원은 넓이가 28.26 cm²로 고리보다 훨씬 좁다. 고리는 큰 원에서 작은 원을 빼야 한다.","scoring_points":["고리의 넓이 103.62 cm²를 구했는가","반지름의 차로 만든 원의 넓이가 다름을 보였는가","큰 원에서 작은 원을 빼야 한다고 설명했는가"]},"explanation":["큰 원 153.86 cm² - 작은 원 50.24 cm² = 103.62 cm²예요.","(7 - 4) × (7 - 4) × 3.14 = 28.26 cm²로 달라요.","고리는 큰 원에서 작은 원을 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#1','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'mc','auto','동물 보호소에 반지름이 10 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":1,"concept":"M6-2-u5-C8","difficulty":1,"kind":"mc","stem":"동물 보호소에 반지름이 10 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"},{"t":"1256 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."],"variant_rule":{"alt":[{"stem":"동물 보호소에 반지름이 20 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"1256 cm²","correct":true},{"t":"125.6 cm²","mis":"M6-2-u5-X12"},{"t":"62.8 cm²","mis":"M6-2-u5-X14"},{"t":"5024 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","20 × 20 × 3.14를 계산해요.","20 × 20 × 3.14 = 1256 — 넓이는 1256 cm²예요."]},{"stem":"동물 보호소에 반지름이 5 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"},{"t":"314 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#2','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'sa','auto','반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 20 cm인 방석의 넓이는 1256 cm²예요. 반지름이 2배가 되면 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 20 cm인 방석의 넓이는 1256 cm²예요. 반지름이 2배가 되면 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["1256 ÷ 314 = 4예요.","반지름이 2배가 되니 넓이는 2 × 2 = 4배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 방석의 넓이는 78.5 cm², 반지름이 10 cm인 방석의 넓이는 314 cm²예요. 반지름이 2배가 되면 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["314 ÷ 78.5 = 4예요.","반지름이 2배가 되니 넓이는 2 × 2 = 4배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."]},{"stem":"반지름이 3 cm인 방석의 넓이는 28.26 cm², 반지름이 6 cm인 방석의 넓이는 113.04 cm²예요. 반지름이 2배가 되면 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["113.04 ÷ 28.26 = 4예요.","반지름이 2배가 되니 넓이는 2 × 2 = 4배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#3','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'mc','auto','반지름이 2배가 될 때 원의 넓이가 4배가 되는 까닭은 무엇인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X05','M6-2-u5-X01']::text[],true,'{"seq":3,"concept":"M6-2-u5-C8","difficulty":1,"kind":"mc","stem":"반지름이 2배가 될 때 원의 넓이가 4배가 되는 까닭은 무엇인가요?","options":[{"t":"넓이를 구할 때 반지름을 두 번 곱하므로 2 × 2 = 4배가 되어서","correct":true},{"t":"반지름에 2를 더하기 때문에","mis":"M6-2-u5-X18"},{"t":"원주율이 2배가 되기 때문에","mis":"M6-2-u5-X05"},{"t":"지름이 4배가 되기 때문에","mis":"M6-2-u5-X01"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름이 2배면 곱하는 두 반지름이 모두 2배예요.","그래서 넓이는 2 × 2 = 4배예요."],"variant_rule":{"alt":[{"stem":"반지름이 3배가 될 때 원의 넓이가 9배가 되는 까닭은 무엇인가요?","options":[{"t":"넓이를 구할 때 반지름을 두 번 곱하므로 3 × 3 = 9배가 되어서","correct":true},{"t":"반지름에 3을 더하기 때문에","mis":"M6-2-u5-X18"},{"t":"원주율이 3배가 되기 때문에","mis":"M6-2-u5-X05"},{"t":"지름이 9배가 되기 때문에","mis":"M6-2-u5-X01"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 곱하는 두 반지름이 모두 3배예요.","그래서 넓이는 3 × 3 = 9배예요."]},{"stem":"반지름이 4배가 될 때 원의 넓이가 16배가 되는 까닭은 무엇인가요?","options":[{"t":"넓이를 구할 때 반지름을 두 번 곱하므로 4 × 4 = 16배가 되어서","correct":true},{"t":"반지름에 4를 더하기 때문에","mis":"M6-2-u5-X18"},{"t":"원주율이 4배가 되기 때문에","mis":"M6-2-u5-X05"},{"t":"지름이 16배가 되기 때문에","mis":"M6-2-u5-X01"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","반지름이 4배면 곱하는 두 반지름이 모두 4배예요.","그래서 넓이는 4 × 4 = 16배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#4','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',1,'sa','auto','원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 두 번 곱하는 반지름이 모두 3배예요.","3 × 3 = 9배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 4배가 되면 원의 넓이는 몇 배가 되나요?","answer":["16"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 4배면 두 번 곱하는 반지름이 모두 4배예요.","4 × 4 = 16배가 돼요."]},{"stem":"원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","answer":["25"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 5배면 두 번 곱하는 반지름이 모두 5배예요.","5 × 5 = 25배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#5','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'mc','auto','동물 보호소에 반지름이 30 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":5,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"동물 보호소에 반지름이 30 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"2826 cm²","correct":true},{"t":"188.4 cm²","mis":"M6-2-u5-X12"},{"t":"94.2 cm²","mis":"M6-2-u5-X14"},{"t":"11304 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","30 × 30 × 3.14를 계산해요.","30 × 30 × 3.14 = 2826 — 넓이는 2826 cm²예요."],"variant_rule":{"alt":[{"stem":"동물 보호소에 반지름이 15 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"706.5 cm²","correct":true},{"t":"94.2 cm²","mis":"M6-2-u5-X12"},{"t":"47.1 cm²","mis":"M6-2-u5-X14"},{"t":"2826 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","15 × 15 × 3.14를 계산해요.","15 × 15 × 3.14 = 706.5 — 넓이는 706.5 cm²예요."]},{"stem":"동물 보호소에 반지름이 25 cm인 원 모양 방석이 있어요. 이 방석의 넓이는 몇 cm²인가요?","options":[{"t":"1962.5 cm²","correct":true},{"t":"157 cm²","mis":"M6-2-u5-X12"},{"t":"78.5 cm²","mis":"M6-2-u5-X14"},{"t":"7850 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","25 × 25 × 3.14를 계산해요.","25 × 25 × 3.14 = 1962.5 — 넓이는 1962.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#6','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'sa','auto','반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 30 cm인 방석의 넓이는 2826 cm²예요. 반지름이 3배가 되면 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u5-C8","difficulty":2,"kind":"sa","stem":"반지름이 10 cm인 방석의 넓이는 314 cm², 반지름이 30 cm인 방석의 넓이는 2826 cm²예요. 반지름이 3배가 되면 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["2826 ÷ 314 = 9예요.","반지름이 3배가 되니 넓이는 3 × 3 = 9배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 방석의 넓이는 78.5 cm², 반지름이 15 cm인 방석의 넓이는 706.5 cm²예요. 반지름이 3배가 되면 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["706.5 ÷ 78.5 = 9예요.","반지름이 3배가 되니 넓이는 3 × 3 = 9배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."]},{"stem":"반지름이 5 cm인 방석의 넓이는 78.5 cm², 반지름이 20 cm인 방석의 넓이는 1256 cm²예요. 반지름이 4배가 되면 넓이는 몇 배가 되나요?","answer":["16"],"explanation":["1256 ÷ 78.5 = 16이에요.","반지름이 4배가 되니 넓이는 4 × 4 = 16배가 되었어요.","넓이를 구할 때 반지름을 두 번 곱하기 때문이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#7','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'mc','auto','반지름이 24 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":7,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"반지름이 24 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"8배","mis":"M6-2-u5-X20"},{"t":"24배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 24 ÷ 12 = 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요.","계산해 봐도 1808.64 ÷ 452.16 = 4예요."],"variant_rule":{"alt":[{"stem":"반지름이 36 cm인 원의 넓이는 반지름이 12 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"27배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 36 ÷ 12 = 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요.","계산해 봐도 4069.44 ÷ 452.16 = 9예요."]},{"stem":"반지름이 20 cm인 원의 넓이는 반지름이 5 cm인 원의 넓이의 몇 배인가요?","options":[{"t":"16배","correct":true},{"t":"4배","mis":"M6-2-u5-X18"},{"t":"8배","mis":"M6-2-u5-X18"},{"t":"64배","mis":"M6-2-u5-X20"}],"explanation":["반지름이 20 ÷ 5 = 4배예요.","넓이는 반지름을 두 번 곱하니 4 × 4 = 16배예요.","계산해 봐도 1256 ÷ 78.5 = 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#8','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'mc','auto','원의 지름이 2배가 되면 원의 넓이는 몇 배가 되나요?',ARRAY['M6-2-u5-X18','M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":8,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"원의 지름이 2배가 되면 원의 넓이는 몇 배가 되나요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M6-2-u5-X18"},{"t":"16배","mis":"M6-2-u5-X01"},{"t":"8배","mis":"M6-2-u5-X20"}],"explanation":["지름이 2배면 반지름도 2배예요.","넓이는 반지름을 두 번 곱해요.","2 × 2 = 4배예요."],"variant_rule":{"alt":[{"stem":"원의 지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M6-2-u5-X18"},{"t":"6배","mis":"M6-2-u5-X18"},{"t":"36배","mis":"M6-2-u5-X01"}],"explanation":["지름이 3배면 반지름도 3배예요.","넓이는 반지름을 두 번 곱해요.","3 × 3 = 9배예요."]},{"stem":"원의 지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","options":[{"t":"25배","correct":true},{"t":"5배","mis":"M6-2-u5-X18"},{"t":"10배","mis":"M6-2-u5-X18"},{"t":"100배","mis":"M6-2-u5-X01"}],"explanation":["지름이 5배면 반지름도 5배예요.","넓이는 반지름을 두 번 곱해요.","5 × 5 = 25배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#9','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',2,'mc','auto','반지름이 20 cm인 큰 방석 한 개를 만드는 천으로, 반지름이 10 cm인 작은 방석을 몇 개 만들 수 있을까요? (자투리 없이 쓴다고 생각해요.)',ARRAY['M6-2-u5-X18','M6-2-u5-X20']::text[],true,'{"seq":9,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"반지름이 20 cm인 큰 방석 한 개를 만드는 천으로, 반지름이 10 cm인 작은 방석을 몇 개 만들 수 있을까요? (자투리 없이 쓴다고 생각해요.)","options":[{"t":"4개","correct":true},{"t":"2개","mis":"M6-2-u5-X18"},{"t":"8개","mis":"M6-2-u5-X20"},{"t":"6개","mis":"M6-2-u5-X18"}],"explanation":["반지름이 2배인 방석이에요.","넓이는 2 × 2 = 4배예요.","그래서 작은 방석 4개를 만들 수 있어요."],"variant_rule":{"alt":[{"stem":"반지름이 30 cm인 큰 방석 한 개를 만드는 천으로, 반지름이 10 cm인 작은 방석을 몇 개 만들 수 있을까요? (자투리 없이 쓴다고 생각해요.)","options":[{"t":"9개","correct":true},{"t":"3개","mis":"M6-2-u5-X18"},{"t":"6개","mis":"M6-2-u5-X18"},{"t":"18개","mis":"M6-2-u5-X20"}],"explanation":["반지름이 3배인 방석이에요.","넓이는 3 × 3 = 9배예요.","그래서 작은 방석 9개를 만들 수 있어요."]},{"stem":"반지름이 20 cm인 큰 방석 한 개를 만드는 천으로, 반지름이 5 cm인 작은 방석을 몇 개 만들 수 있을까요? (자투리 없이 쓴다고 생각해요.)","options":[{"t":"16개","correct":true},{"t":"4개","mis":"M6-2-u5-X18"},{"t":"8개","mis":"M6-2-u5-X18"},{"t":"32개","mis":"M6-2-u5-X20"}],"explanation":["반지름이 4배인 방석이에요.","넓이는 4 × 4 = 16배예요.","그래서 작은 방석 16개를 만들 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_basic#10','math',6,2,'u5','L08','g6_2_math_u5_L08_basic','lesson_basic','M6-2-u5-C8',3,'error','auto','반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 3배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X19']::text[],true,'{"seq":10,"concept":"M6-2-u5-C8","difficulty":3,"kind":"error","stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 3배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세호 — 「2배일 때 4배였으니 3배면 6배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"여울 — 「반지름을 두 번 곱하니 3 × 3 = 9배야.」","mis":"M6-2-u5-X19"},{"t":"달곰 — 「계산해 보면 넓이가 9배로 나와.」","mis":"M6-2-u5-X19"},{"t":"순달 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 3배면 넓이는 3 × 3 = 9배예요.","세호는 2배씩 늘린다고 생각했어요 — 6배가 아니에요."],"variant_rule":{"alt":[{"stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 4배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「2배일 때 4배였으니 4배면 8배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"나린 — 「반지름을 두 번 곱하니 4 × 4 = 16배야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「계산해 보면 넓이가 16배로 나와.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 4배면 넓이는 4 × 4 = 16배예요.","가온는 2배씩 늘린다고 생각했어요 — 8배가 아니에요."]},{"stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 5배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「2배일 때 4배였으니 5배면 10배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"하린 — 「반지름을 두 번 곱하니 5 × 5 = 25배야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「계산해 보면 넓이가 25배로 나와.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 5배면 넓이는 5 × 5 = 25배예요.","수아는 2배씩 늘린다고 생각했어요 — 10배가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#1','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',2,'sa','auto','원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u5-C8","difficulty":2,"kind":"sa","stem":"원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","answer":["25"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 5배면 두 번 곱하는 반지름이 모두 5배예요.","5 × 5 = 25배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 6배가 되면 원의 넓이는 몇 배가 되나요?","answer":["36"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 6배면 두 번 곱하는 반지름이 모두 6배예요.","6 × 6 = 36배가 돼요."]},{"stem":"원의 반지름이 7배가 되면 원의 넓이는 몇 배가 되나요?","answer":["49"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 7배면 두 번 곱하는 반지름이 모두 7배예요.","7 × 7 = 49배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#2','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',2,'mc','auto','원의 반지름이 2배가 되면 원주와 넓이는 각각 몇 배가 되나요?',ARRAY['M6-2-u5-X18']::text[],true,'{"seq":2,"concept":"M6-2-u5-C8","difficulty":2,"kind":"mc","stem":"원의 반지름이 2배가 되면 원주와 넓이는 각각 몇 배가 되나요?","options":[{"t":"원주는 2배, 넓이는 4배","correct":true},{"t":"원주는 2배, 넓이는 2배","mis":"M6-2-u5-X18"},{"t":"원주는 4배, 넓이는 4배","mis":"M6-2-u5-X18"},{"t":"원주는 4배, 넓이는 2배","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","그래서 원주는 2배예요.","넓이는 반지름을 두 번 곱하니 2 × 2 = 4배예요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 3배가 되면 원주와 넓이는 각각 몇 배가 되나요?","options":[{"t":"원주는 3배, 넓이는 9배","correct":true},{"t":"원주는 3배, 넓이는 3배","mis":"M6-2-u5-X18"},{"t":"원주는 9배, 넓이는 9배","mis":"M6-2-u5-X18"},{"t":"원주는 9배, 넓이는 3배","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","그래서 원주는 3배예요.","넓이는 반지름을 두 번 곱하니 3 × 3 = 9배예요."]},{"stem":"원의 반지름이 4배가 되면 원주와 넓이는 각각 몇 배가 되나요?","options":[{"t":"원주는 4배, 넓이는 16배","correct":true},{"t":"원주는 4배, 넓이는 4배","mis":"M6-2-u5-X18"},{"t":"원주는 16배, 넓이는 16배","mis":"M6-2-u5-X18"},{"t":"원주는 16배, 넓이는 4배","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","그래서 원주는 4배예요.","넓이는 반지름을 두 번 곱하니 4 × 4 = 16배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#3','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'error','auto','반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 6배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X19']::text[],true,'{"seq":3,"concept":"M6-2-u5-C8","difficulty":3,"kind":"error","stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 6배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「2배일 때 4배였으니 6배면 12배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"지호 — 「반지름을 두 번 곱하니 6 × 6 = 36배야.」","mis":"M6-2-u5-X19"},{"t":"가온 — 「계산해 보면 넓이가 36배로 나와.」","mis":"M6-2-u5-X19"},{"t":"나린 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 6배면 넓이는 6 × 6 = 36배예요.","서아는 2배씩 늘린다고 생각했어요 — 12배가 아니에요."],"variant_rule":{"alt":[{"stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 4배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「2배일 때 4배였으니 4배면 8배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"하린 — 「반지름을 두 번 곱하니 4 × 4 = 16배야.」","mis":"M6-2-u5-X19"},{"t":"도윤 — 「계산해 보면 넓이가 16배로 나와.」","mis":"M6-2-u5-X19"},{"t":"민준 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 4배면 넓이는 4 × 4 = 16배예요.","수아는 2배씩 늘린다고 생각했어요 — 8배가 아니에요."]},{"stem":"반지름이 2배일 때 원의 넓이가 4배였어요. 반지름이 3배일 때를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「2배일 때 4배였으니 3배면 6배일 거야.」","correct":true,"mis_target":"M6-2-u5-X18"},{"t":"나린 — 「반지름을 두 번 곱하니 3 × 3 = 9배야.」","mis":"M6-2-u5-X19"},{"t":"지호 — 「계산해 보면 넓이가 9배로 나와.」","mis":"M6-2-u5-X19"},{"t":"유진 — 「반지름이 몇 배든 그 수를 두 번 곱한 만큼 넓어져.」","mis":"M6-2-u5-X19"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 3배면 넓이는 3 × 3 = 9배예요.","가온는 2배씩 늘린다고 생각했어요 — 6배가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#4','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'ox','auto','반지름이 3배가 되면 원주는 9배가 돼요.',ARRAY['M6-2-u5-X18']::text[],true,'{"seq":4,"concept":"M6-2-u5-C8","difficulty":3,"kind":"ox","stem":"반지름이 3배가 되면 원주는 9배가 돼요.","answer":"X","reason_options":[{"t":"원주는 길이를 한 번 곱하므로 3배가 되기 때문에","correct":true},{"t":"넓이처럼 원주도 3 × 3배가 되기 때문에","mis":"M6-2-u5-X18"}],"mis":"M6-2-u5-X18","explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","넓이는 (반지름) × (반지름) × (원주율) — 두 번 곱해요.","그래서 반지름이 □배면 원주는 □배, 넓이는 □ × □배예요."],"variant_rule":{"alt":[{"stem":"반지름이 2배가 되면 원의 넓이는 4배가 돼요.","answer":"O","reason_options":[{"t":"넓이를 구할 때 반지름을 두 번 곱하기 때문에","correct":true},{"t":"반지름에 2를 두 번 더하기 때문에","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","넓이는 (반지름) × (반지름) × (원주율) — 두 번 곱해요.","그래서 반지름이 □배면 원주는 □배, 넓이는 □ × □배예요."]},{"stem":"지름이 2배가 되면 원의 넓이도 2배가 돼요.","answer":"X","reason_options":[{"t":"지름이 2배면 반지름도 2배라 넓이는 2 × 2 = 4배이기 때문에","correct":true},{"t":"지름과 넓이는 같은 배수로 늘기 때문에","mis":"M6-2-u5-X18"}],"explanation":["원주는 (지름) × (원주율) — 길이를 한 번 곱해요.","넓이는 (반지름) × (반지름) × (원주율) — 두 번 곱해요.","그래서 반지름이 □배면 원주는 □배, 넓이는 □ × □배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#5','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'match','auto','반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u5-C8","difficulty":3,"kind":"match","stem":"반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.","pairs":[{"l":"반지름 2배","r":"넓이 4배"},{"l":"반지름 3배","r":"넓이 9배"},{"l":"반지름 4배","r":"넓이 16배"}],"mis":"M6-2-u5-X18","explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 □배면 넓이는 □ × □배예요.","2 × 2 = 4 · 3 × 3 = 9 · 4 × 4 = 16이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.","pairs":[{"l":"반지름 3배","r":"넓이 9배"},{"l":"반지름 5배","r":"넓이 25배"},{"l":"반지름 6배","r":"넓이 36배"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 □배면 넓이는 □ × □배예요.","3 × 3 = 9 · 5 × 5 = 25 · 6 × 6 = 36이에요."]},{"stem":"이번에는 다른 보기예요. 반지름이 늘어난 배수와 넓이가 늘어난 배수를 이으세요.","pairs":[{"l":"반지름 2배","r":"넓이 4배"},{"l":"반지름 4배","r":"넓이 16배"},{"l":"반지름 10배","r":"넓이 100배"}],"explanation":["넓이는 반지름을 두 번 곱해요.","반지름이 □배면 넓이는 □ × □배예요.","2 × 2 = 4 · 4 × 4 = 16 · 10 × 10 = 100이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#6','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'sa','auto','원의 넓이가 9배가 되었어요. 반지름은 몇 배가 되었나요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u5-C8","difficulty":3,"kind":"sa","stem":"원의 넓이가 9배가 되었어요. 반지름은 몇 배가 되었나요?","answer":["3"],"explanation":["반지름이 □배면 넓이는 □ × □배예요.","□ × □ = 9인 수를 찾아요.","3 × 3 = 9 — 반지름은 3배예요."],"variant_rule":{"alt":[{"stem":"원의 넓이가 16배가 되었어요. 반지름은 몇 배가 되었나요?","answer":["4"],"explanation":["반지름이 □배면 넓이는 □ × □배예요.","□ × □ = 16인 수를 찾아요.","4 × 4 = 16 — 반지름은 4배예요."]},{"stem":"원의 넓이가 25배가 되었어요. 반지름은 몇 배가 되었나요?","answer":["5"],"explanation":["반지름이 □배면 넓이는 □ × □배예요.","□ × □ = 25인 수를 찾아요.","5 × 5 = 25 — 반지름은 5배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#7','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',3,'sa','auto','반지름이 10 cm인 원 모양 방석보다 넓이가 4배인 원 모양 방석을 만들려고 해요. 새 방석의 반지름은 몇 cm로 하면 되나요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u5-C8","difficulty":3,"kind":"sa","stem":"반지름이 10 cm인 원 모양 방석보다 넓이가 4배인 원 모양 방석을 만들려고 해요. 새 방석의 반지름은 몇 cm로 하면 되나요?","answer":["20"],"explanation":["넓이가 4배가 되려면 반지름은 □ × □ = 4인 □배예요.","□ = 2예요.","10 × 2 = 20 — 반지름을 20 cm로 해요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원 모양 방석보다 넓이가 9배인 원 모양 방석을 만들려고 해요. 새 방석의 반지름은 몇 cm로 하면 되나요?","answer":["30"],"explanation":["넓이가 9배가 되려면 반지름은 □ × □ = 9인 □배예요.","□ = 3이에요.","10 × 3 = 30 — 반지름을 30 cm로 해요."]},{"stem":"반지름이 15 cm인 원 모양 방석보다 넓이가 4배인 원 모양 방석을 만들려고 해요. 새 방석의 반지름은 몇 cm로 하면 되나요?","answer":["30"],"explanation":["넓이가 4배가 되려면 반지름은 □ × □ = 4인 □배예요.","□ = 2예요.","15 × 2 = 30 — 반지름을 30 cm로 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#8','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',4,'mc','auto','반지름이 10 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?',ARRAY['M6-2-u5-X18','M6-2-u5-X19','M6-2-u5-X20']::text[],true,'{"seq":8,"concept":"M6-2-u5-C8","difficulty":4,"kind":"mc","stem":"반지름이 10 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?","options":[{"t":"942 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X18"},{"t":"1256 cm²","mis":"M6-2-u5-X19"},{"t":"1570 cm²","mis":"M6-2-u5-X20"}],"explanation":["작은 방석은 10 × 10 × 3.14 = 314 cm²예요.","큰 방석은 반지름이 2배라 넓이가 4배 — 1256 cm²예요.","1256 - 314 = 942 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 방석과 반지름이 30 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?","options":[{"t":"2512 cm²","correct":true},{"t":"628 cm²","mis":"M6-2-u5-X18"},{"t":"1256 cm²","mis":"M6-2-u5-X16"},{"t":"2826 cm²","mis":"M6-2-u5-X19"}],"explanation":["작은 방석은 10 × 10 × 3.14 = 314 cm²예요.","큰 방석은 반지름이 3배라 넓이가 9배 — 2826 cm²예요.","2826 - 314 = 2512 cm²예요."]},{"stem":"반지름이 5 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석은 작은 방석보다 몇 cm² 더 넓은가요?","options":[{"t":"1177.5 cm²","correct":true},{"t":"235.5 cm²","mis":"M6-2-u5-X18"},{"t":"706.5 cm²","mis":"M6-2-u5-X16"},{"t":"1256 cm²","mis":"M6-2-u5-X19"}],"explanation":["작은 방석은 5 × 5 × 3.14 = 78.5 cm²예요.","큰 방석은 반지름이 4배라 넓이가 16배 — 1256 cm²예요.","1256 - 78.5 = 1177.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#9','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',4,'essay','teacher','순달이는 「반지름이 2배일 때 넓이가 4배였으니, 3배면 그 한 배 반인 6배가 되겠지!」라고 예상했어요. 반지름 10 cm와 30 cm인 방석의 넓이를 구해 예상을 확인하고, 바른 규칙을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"순달이는 「반지름이 2배일 때 넓이가 4배였으니, 3배면 그 한 배 반인 6배가 되겠지!」라고 예상했어요. 반지름 10 cm와 30 cm인 방석의 넓이를 구해 예상을 확인하고, 바른 규칙을 설명해 보세요.","answer_guide":{"answer":"예: 반지름 10 cm인 방석은 10 × 10 × 3.14 = 314 cm², 30 cm인 방석은 30 × 30 × 3.14 = 2826 cm²이다. 2826 ÷ 314 = 9이므로 6배가 아니라 9배이다. 넓이를 구할 때 반지름을 두 번 곱하므로 반지름이 □배면 넓이는 □ × □배가 된다.","scoring_points":["두 방석의 넓이 314 cm²와 2826 cm²를 구했는가","9배임을 보여 예상이 틀렸음을 밝혔는가","반지름을 두 번 곱하므로 □ × □배라는 규칙을 썼는가"]},"explanation":["314 cm²와 2826 cm²예요.","2826 ÷ 314 = 9 — 9배예요.","반지름을 두 번 곱하니 3 × 3 = 9배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_L08_challenge#10','math',6,2,'u5','L08','g6_2_math_u5_L08_challenge','lesson_challenge','M6-2-u5-C8',4,'essay','teacher','반지름이 2배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"반지름이 2배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원주는 2배, 넓이는 4배가 된다. 원주는 (지름) × (원주율)로 길이를 한 번만 곱하지만, 넓이는 (반지름) × (반지름) × (원주율)로 반지름을 두 번 곱하기 때문에 2 × 2 = 4배가 된다.","scoring_points":["원주 2배를 썼는가","넓이 4배를 썼는가","길이를 한 번 곱하는지 두 번 곱하는지로 까닭을 설명했는가"]},"explanation":["원주는 2배예요.","넓이는 2 × 2 = 4배예요.","넓이는 반지름을 두 번 곱하기 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#1','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C1',1,'mc','auto','원의 둘레를 무엇이라고 하나요?',ARRAY['M6-2-u5-X02']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심과 원 위의 한 점을 이은 선분을 반지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심을 지나도록 원 위의 두 점을 이은 선분을 지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#2','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C1',1,'sa','auto','반지름이 5 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"반지름이 5 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["10"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","5 × 2 = 10 — 지름은 10 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["16"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","8 × 2 = 16 — 지름은 16 cm예요."]},{"stem":"반지름이 11 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["22"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","11 × 2 = 22 — 지름은 22 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#3','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C1',2,'sa','auto','지름이 5 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 5 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["15"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 2.5이고 변이 6개이니 둘레는 2.5 × 6이에요.","2.5 × 6 = 15 — 지름의 3배인 15 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 5 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["20"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 5 cm이고 변이 4개예요.","5 × 4 = 20 — 지름의 4배인 20 cm예요."]},{"stem":"지름이 9 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["27"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 4.5이고 변이 6개이니 둘레는 4.5 × 6이에요.","4.5 × 6 = 27 — 지름의 3배인 27 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#4','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',1,'mc','auto','원주율을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X04']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원주율을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (지름)","correct":true},{"t":"(지름) ÷ (원주)","mis":"M6-2-u5-X04"},{"t":"(원주) × (지름)","mis":"M6-2-u5-X04"},{"t":"(원주) ÷ (반지름)","mis":"M6-2-u5-X04"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비율은 (비교하는 양) ÷ (기준량) — 기준량은 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."],"variant_rule":{"alt":[{"stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."]},{"stem":"원주율을 어림하여 쓸 때 흔히 쓰는 값은 어느 것인가요?","options":[{"t":"3.14","correct":true},{"t":"4","mis":"M6-2-u5-X06"},{"t":"2","mis":"M6-2-u5-X06"},{"t":"0.314","mis":"M6-2-u5-X20"}],"explanation":["원주율을 소수로 나타내면 3.14159…처럼 끝없이 이어져요.","그래서 어림하여 쓰는데 흔히 3.14를 써요.","원주는 지름의 약 3.14배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#5','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',2,'ox','auto','지름이 길어지면 원주율도 커져요.',ARRAY['M6-2-u5-X05']::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":2,"kind":"ox","stem":"지름이 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"지름이 길어지면 원주도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"큰 원일수록 둘레가 길어 원주율도 크기 때문에","mis":"M6-2-u5-X05"}],"mis":"M6-2-u5-X05","explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"작은 동전과 큰 접시의 원주율은 같아요.","answer":"O","reason_options":[{"t":"모든 원에서 지름에 대한 원주의 비율은 일정하기 때문에","correct":true},{"t":"동전과 접시는 크기가 달라 원주율도 달라야 하기 때문에","mis":"M6-2-u5-X05"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]},{"stem":"원주율 3.14는 정확한 값이에요.","answer":"X","reason_options":[{"t":"원주율은 끝없이 이어지는 소수라 3.14는 어림한 값이기 때문에","correct":true},{"t":"원주를 지름으로 나누면 언제나 3.14로 딱 떨어지기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#6','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C2',3,'mc','auto','냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X04']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["22 ÷ 7 = 3.142857…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."],"variant_rule":{"alt":[{"stem":"물병의 원주를 재었더니 40.8 cm, 지름은 13 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["40.8 ÷ 13 = 3.13846…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]},{"stem":"연필꽂이의 원주를 재었더니 59.75 cm, 지름은 19 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["59.75 ÷ 19 = 3.14473…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#7','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 10 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":7,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 10 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X01"},{"t":"62.8 cm","mis":"M6-2-u5-X01"},{"t":"78.5 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","10 × 3.14를 계산해요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 7 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"21.98 cm","correct":true},{"t":"10.99 cm","mis":"M6-2-u5-X01"},{"t":"43.96 cm","mis":"M6-2-u5-X01"},{"t":"38.465 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","7 × 3.14를 계산해요.","7 × 3.14 = 21.98 — 원주는 21.98 cm예요."]},{"stem":"지름이 15 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"47.1 cm","correct":true},{"t":"23.55 cm","mis":"M6-2-u5-X01"},{"t":"94.2 cm","mis":"M6-2-u5-X01"},{"t":"176.625 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","15 × 3.14를 계산해요.","15 × 3.14 = 47.1 — 원주는 47.1 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#8','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',2,'mc','auto','반지름이 4 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12']::text[],true,'{"seq":8,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"반지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u5-X07"},{"t":"50.24 cm","mis":"M6-2-u5-X12"},{"t":"6.28 cm","mis":"M6-2-u5-X07"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 — 원주는 25.12 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."]},{"stem":"반지름이 5 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X07"},{"t":"78.5 cm","mis":"M6-2-u5-X12"},{"t":"62.8 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 5 cm에 2를 곱해 지름 10 cm를 먼저 만들어요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#9','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',2,'mc','auto','지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X07','M6-2-u5-X02']::text[],true,'{"seq":9,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"628 cm","correct":true},{"t":"62.8 cm","mis":"M6-2-u5-X19"},{"t":"314 cm","mis":"M6-2-u5-X07"},{"t":"200 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 30 cm인 원판을 5바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"471 cm","correct":true},{"t":"94.2 cm","mis":"M6-2-u5-X19"},{"t":"235.5 cm","mis":"M6-2-u5-X07"},{"t":"150 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 30 × 3.14 = 94.2 cm예요.","5바퀴면 94.2 × 5 = 471 cm예요."]},{"stem":"지름이 40 cm인 훌라후프를 3바퀴 굴렸어요. 훌라후프가 굴러간 거리는 몇 cm인가요?","options":[{"t":"376.8 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X19"},{"t":"188.4 cm","mis":"M6-2-u5-X07"},{"t":"120 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#10','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',3,'mc','auto','바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":10,"concept":"M6-2-u5-C3","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 50 cm인 굴렁쇠를 4바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.57 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","4바퀴면 157 × 4 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]},{"stem":"바깥쪽 원의 지름이 60 cm인 바퀴를 10바퀴 굴렸어요. 이 바퀴가 굴러간 거리는 몇 m인가요?","options":[{"t":"18.84 m","correct":true},{"t":"1884 m","mis":"M6-2-u5-X20"},{"t":"1.884 m","mis":"M6-2-u5-X19"},{"t":"9.42 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 60 × 3.14 = 188.4 cm예요.","10바퀴면 188.4 × 10 = 1884 cm예요.","100 cm = 1 m니 18.84 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#11','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C4',1,'sa','auto','길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?","answer":["25"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","78.5 ÷ 3.14를 계산해요.","78.5 ÷ 3.14 = 25예요."],"variant_rule":{"alt":[{"stem":"원 모양 탬버린의 원주를 재었더니 62.8 cm였어요. 이 탬버린의 지름은 몇 cm인가요?","answer":["20"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","62.8 ÷ 3.14를 계산해요.","62.8 ÷ 3.14 = 20이에요."]},{"stem":"원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#12','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C4',2,'sa','auto','체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["4"],"explanation":["먼저 지름을 구해요: 25.12 ÷ 3.14 = 8이에요.","반지름은 지름의 반이에요.","8 ÷ 2 = 4 — 반지름은 4예요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"원주가 43.96 cm인 원의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["먼저 지름을 구해요: 43.96 ÷ 3.14 = 14예요.","반지름은 지름의 반이에요.","14 ÷ 2 = 7 — 반지름은 7이에요."]},{"stem":"원주가 50.24 cm인 원의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["먼저 지름을 구해요: 50.24 ÷ 3.14 = 16이에요.","반지름은 지름의 반이에요.","16 ÷ 2 = 8 — 반지름은 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#13','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C4',3,'mc','auto','세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":13,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 15 cm · ㉡ 지름 16 cm · ㉢ 지름 18 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."],"variant_rule":{"alt":[{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 31.4 cm · ㉡ 지름이 12 cm · ㉢ 반지름이 7 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 10 cm · ㉡ 지름 12 cm · ㉢ 지름 14 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."]},{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 62.8 cm · ㉡ 지름이 18 cm · ㉢ 반지름이 11 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 20 cm · ㉡ 지름 18 cm · ㉢ 지름 22 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉠, ㉡예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#14','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C5',1,'mc','auto','한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X10']::text[],true,'{"seq":14,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"60 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"60 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"60 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 60 cm²보다 넓고 88 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 52칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"52 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"52 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"52 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 52 cm²보다 넓고 88 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 32칸, 걸친 칸까지 세면 52칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"32 cm²보다 넓고 52 cm²보다 좁아요","correct":true},{"t":"32 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"52 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"32 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 32 cm²보다 넓고 52 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#15','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C5',2,'sa','auto','반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","10 × 10 ÷ 2 = 50이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["64"],"explanation":["원 밖 정사각형의 한 변은 지름 8 cm예요.","8 × 8 = 64예요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]},{"stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","12 × 12 ÷ 2 = 72예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#16','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 3 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":16,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 2 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"12.56 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X14"},{"t":"50.24 cm²","mis":"M6-2-u5-X13"},{"t":"4 cm²","mis":"M6-2-u5-X20"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","2 × 2 × 3.14를 계산해요.","2 × 2 × 3.14 = 12.56 — 넓이는 12.56 cm²예요."]},{"stem":"반지름이 4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"},{"t":"200.96 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#17','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',2,'mc','auto','지름이 24 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"지름이 24 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 24 ÷ 2 = 12 cm예요.","12 × 12 × 3.14를 계산해요.","12 × 12 × 3.14 = 452.16 — 넓이는 452.16 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 10 ÷ 2 = 5 cm예요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]},{"stem":"지름이 16 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"},{"t":"25.12 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 16 ÷ 2 = 8 cm예요.","8 × 8 × 3.14를 계산해요.","8 × 8 × 3.14 = 200.96 — 넓이는 200.96 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#18','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."]},{"stem":"넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["(반지름) × (반지름) × 3.14 = 28.26이에요.","28.26 ÷ 3.14 = 9니 (반지름) × (반지름) = 9예요.","같은 수를 두 번 곱해 9가 되는 수는 3 — 반지름은 3 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#19','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C6',4,'mc','auto','가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":19,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X19"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 30 cm, 세로가 16 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X19"},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 16 cm를 넘을 수 없어요.","반지름은 8 cm예요.","8 × 8 × 3.14 = 200.96 cm²예요."]},{"stem":"가로가 12 cm, 세로가 25 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"490.625 cm²","mis":"M6-2-u5-X19"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#20','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":20,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 - 3.14 = 47.1 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 - 50.24 = 103.62 cm²예요."]},{"stem":"반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 - 153.86 = 160.14 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#21','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C7',3,'mc','auto','세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":21,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X17"},{"t":"226.08 cm²","mis":"M6-2-u5-X13"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 24 ÷ 2 = 12 cm예요.","피자 전체는 12 × 12 × 3.14 = 452.16 cm²예요.","8조각 중 한 조각은 452.16 ÷ 8 = 56.52 cm²예요."],"variant_rule":{"alt":[{"stem":"하린은 지름이 20 cm인 원 모양 팬케이크를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 하린이 먹은 팬케이크의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"15.7 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 20 ÷ 2 = 10 cm예요.","팬케이크 전체는 10 × 10 × 3.14 = 314 cm²예요.","4조각 중 한 조각은 314 ÷ 4 = 78.5 cm²예요."]},{"stem":"도윤은 지름이 30 cm인 원 모양 케이크를 똑같이 6조각으로 나눈 것 가운데 한 조각을 먹었어요. 도윤이 먹은 케이크의 넓이는 몇 cm²인가요?","options":[{"t":"117.75 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X17"},{"t":"471 cm²","mis":"M6-2-u5-X13"},{"t":"235.5 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 30 ÷ 2 = 15 cm예요.","케이크 전체는 15 × 15 × 3.14 = 706.5 cm²예요.","6조각 중 한 조각은 706.5 ÷ 6 = 117.75 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#22','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C7',3,'sa','auto','한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":22,"concept":"M6-2-u5-C7","difficulty":3,"kind":"sa","stem":"한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","400 - 314 = 86 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 20 cm, 세로 10 cm인 직사각형 안에 반지름이 10 cm인 반원이 꼭 맞게 들어 있어요. 직사각형에서 반원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["43"],"explanation":["직사각형의 넓이는 20 × 10 = 200 cm²예요.","반원은 10 × 10 × 3.14 ÷ 2 = 157 cm²예요.","200 - 157 = 43 cm²예요."]},{"stem":"한 변이 20 cm인 정사각형의 한 꼭짓점을 중심으로 반지름이 20 cm인 사분원을 그렸어요. 정사각형에서 사분원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","사분원은 20 × 20 × 3.14 ÷ 4 = 314 cm²예요.","400 - 314 = 86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#23','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C8',1,'sa','auto','원의 반지름이 2배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"원의 반지름이 2배가 되면 원의 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 2배면 두 번 곱하는 반지름이 모두 2배예요.","2 × 2 = 4배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 두 번 곱하는 반지름이 모두 3배예요.","3 × 3 = 9배가 돼요."]},{"stem":"원의 반지름이 4배가 되면 원의 넓이는 몇 배가 되나요?","answer":["16"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 4배면 두 번 곱하는 반지름이 모두 4배예요.","4 × 4 = 16배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#24','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C8',4,'essay','teacher','세호는 「반지름이 4배가 되면 넓이도 4배야.」라고 말했어요. 세호의 말이 맞는지 판단하고, 반지름이 1 cm와 4 cm인 원의 넓이를 구해 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"세호는 「반지름이 4배가 되면 넓이도 4배야.」라고 말했어요. 세호의 말이 맞는지 판단하고, 반지름이 1 cm와 4 cm인 원의 넓이를 구해 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 반지름 1 cm인 원은 3.14 cm², 4 cm인 원은 50.24 cm²로 50.24 ÷ 3.14 = 16배이다. 넓이는 반지름을 두 번 곱하므로 4 × 4 = 16배가 된다.","scoring_points":["세호의 말이 틀렸다고 판단했는가","두 넓이를 구해 16배를 보였는가","두 번 곱하는 규칙을 썼는가"]},"explanation":["3.14 cm²와 50.24 cm²예요.","50.24 ÷ 3.14 = 16배예요.","4 × 4 = 16배 — 4배가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_a#25','math',6,2,'u5','','g6_2_math_u5_review_a','unit_review','M6-2-u5-C3',4,'essay','teacher','반지름이 6 cm인 원의 원주를 6 × 3.14 = 18.84 cm로 구한 친구가 있어요. 무엇이 잘못되었는지 쓰고 바르게 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u5-C3","difficulty":4,"kind":"essay","stem":"반지름이 6 cm인 원의 원주를 6 × 3.14 = 18.84 cm로 구한 친구가 있어요. 무엇이 잘못되었는지 쓰고 바르게 구해 보세요.","answer_guide":{"answer":"예: 반지름에 바로 원주율을 곱했다. 원주는 (지름) × (원주율)이므로 반지름에 2를 곱한 지름 12 cm를 써서 12 × 3.14 = 37.68 cm이다.","scoring_points":["반지름에 바로 곱한 것이 잘못임을 밝혔는가","지름 12 cm를 만들었는가","37.68 cm를 구했는가"]},"explanation":["반지름에 바로 3.14를 곱하면 안 돼요.","지름은 12 cm예요.","12 × 3.14 = 37.68 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#1','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C1',1,'mc','auto','원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심과 원 위의 한 점을 이은 선분을 반지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심을 지나도록 원 위의 두 점을 이은 선분을 지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원을 그릴 때 누름 못이 꽂혔던 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원을 그릴 때 누름 못이 꽂혔던 점을 원의 중심이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#2','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C1',1,'sa','auto','반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["16"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","8 × 2 = 16 — 지름은 16 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 11 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["22"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","11 × 2 = 22 — 지름은 22 cm예요."]},{"stem":"반지름이 13 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["26"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","13 × 2 = 26 — 지름은 26 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#3','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C1',2,'sa','auto','지름이 5 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 5 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["20"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 5 cm이고 변이 4개예요.","5 × 4 = 20 — 지름의 4배인 20 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 9 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["27"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 4.5이고 변이 6개이니 둘레는 4.5 × 6이에요.","4.5 × 6 = 27 — 지름의 3배인 27 cm예요."]},{"stem":"지름이 9 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 9 cm이고 변이 4개예요.","9 × 4 = 36 — 지름의 4배인 36 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#4','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',1,'mc','auto','원의 지름에 대한 원주의 비율을 무엇이라고 하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."],"variant_rule":{"alt":[{"stem":"원주율을 어림하여 쓸 때 흔히 쓰는 값은 어느 것인가요?","options":[{"t":"3.14","correct":true},{"t":"4","mis":"M6-2-u5-X06"},{"t":"2","mis":"M6-2-u5-X06"},{"t":"0.314","mis":"M6-2-u5-X20"}],"explanation":["원주율을 소수로 나타내면 3.14159…처럼 끝없이 이어져요.","그래서 어림하여 쓰는데 흔히 3.14를 써요.","원주는 지름의 약 3.14배예요."]},{"stem":"어떤 원의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"21.4","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#5','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',2,'ox','auto','작은 동전과 큰 접시의 원주율은 같아요.',ARRAY['M6-2-u5-X05']::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":2,"kind":"ox","stem":"작은 동전과 큰 접시의 원주율은 같아요.","answer":"O","reason_options":[{"t":"모든 원에서 지름에 대한 원주의 비율은 일정하기 때문에","correct":true},{"t":"동전과 접시는 크기가 달라 원주율도 달라야 하기 때문에","mis":"M6-2-u5-X05"}],"mis":"M6-2-u5-X05","explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"원주율 3.14는 정확한 값이에요.","answer":"X","reason_options":[{"t":"원주율은 끝없이 이어지는 소수라 3.14는 어림한 값이기 때문에","correct":true},{"t":"원주를 지름으로 나누면 언제나 3.14로 딱 떨어지기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]},{"stem":"원주는 지름의 약 3.14배예요.","answer":"O","reason_options":[{"t":"원주율이 약 3.14이기 때문에","correct":true},{"t":"원주는 지름에 3.14를 더한 값이기 때문에","mis":"M6-2-u5-X08"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","원주율은 약 3.14예요.","그래서 원주는 지름의 약 3.14배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#6','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C2',3,'mc','auto','물병의 원주를 재었더니 40.8 cm, 지름은 13 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X04']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"물병의 원주를 재었더니 40.8 cm, 지름은 13 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["40.8 ÷ 13 = 3.13846…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."],"variant_rule":{"alt":[{"stem":"연필꽂이의 원주를 재었더니 59.75 cm, 지름은 19 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["59.75 ÷ 19 = 3.14473…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]},{"stem":"냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#7','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 7 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":7,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 7 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"21.98 cm","correct":true},{"t":"10.99 cm","mis":"M6-2-u5-X01"},{"t":"43.96 cm","mis":"M6-2-u5-X01"},{"t":"38.465 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","7 × 3.14를 계산해요.","7 × 3.14 = 21.98 — 원주는 21.98 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 15 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"47.1 cm","correct":true},{"t":"23.55 cm","mis":"M6-2-u5-X01"},{"t":"94.2 cm","mis":"M6-2-u5-X01"},{"t":"176.625 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","15 × 3.14를 계산해요.","15 × 3.14 = 47.1 — 원주는 47.1 cm예요."]},{"stem":"지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X01"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"7.14 cm","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","4 × 3.14를 계산해요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#8','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C3',2,'mc','auto','반지름이 9 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":8,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X07"},{"t":"78.5 cm","mis":"M6-2-u5-X12"},{"t":"62.8 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 5 cm에 2를 곱해 지름 10 cm를 먼저 만들어요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."]},{"stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#9','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C3',2,'mc','auto','지름이 30 cm인 원판을 5바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X07','M6-2-u5-X02']::text[],true,'{"seq":9,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 30 cm인 원판을 5바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"471 cm","correct":true},{"t":"94.2 cm","mis":"M6-2-u5-X19"},{"t":"235.5 cm","mis":"M6-2-u5-X07"},{"t":"150 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 30 × 3.14 = 94.2 cm예요.","5바퀴면 94.2 × 5 = 471 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 40 cm인 훌라후프를 3바퀴 굴렸어요. 훌라후프가 굴러간 거리는 몇 cm인가요?","options":[{"t":"376.8 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X19"},{"t":"188.4 cm","mis":"M6-2-u5-X07"},{"t":"120 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요."]},{"stem":"지름이 50 cm인 바퀴를 2바퀴 굴렸어요. 바퀴가 굴러간 거리는 몇 cm인가요?","options":[{"t":"314 cm","correct":true},{"t":"157 cm","mis":"M6-2-u5-X19"},{"t":"100 cm","mis":"M6-2-u5-X02"},{"t":"628 cm","mis":"M6-2-u5-X01"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 50 × 3.14 = 157 cm예요.","2바퀴면 157 × 2 = 314 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#10','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C3',3,'mc','auto','바깥쪽 원의 지름이 50 cm인 굴렁쇠를 4바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":10,"concept":"M6-2-u5-C3","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 지름이 50 cm인 굴렁쇠를 4바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.57 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","4바퀴면 157 × 4 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 60 cm인 바퀴를 10바퀴 굴렸어요. 이 바퀴가 굴러간 거리는 몇 m인가요?","options":[{"t":"18.84 m","correct":true},{"t":"1884 m","mis":"M6-2-u5-X20"},{"t":"1.884 m","mis":"M6-2-u5-X19"},{"t":"9.42 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 60 × 3.14 = 188.4 cm예요.","10바퀴면 188.4 × 10 = 1884 cm예요.","100 cm = 1 m니 18.84 m예요."]},{"stem":"바깥쪽 원의 지름이 40 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.256 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","5바퀴면 125.6 × 5 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#11','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C4',1,'sa','auto','원 모양 탬버린의 원주를 재었더니 62.8 cm였어요. 이 탬버린의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"원 모양 탬버린의 원주를 재었더니 62.8 cm였어요. 이 탬버린의 지름은 몇 cm인가요?","answer":["20"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","62.8 ÷ 3.14를 계산해요.","62.8 ÷ 3.14 = 20이에요."],"variant_rule":{"alt":[{"stem":"원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."]},{"stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#12','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C4',2,'sa','auto','원주가 43.96 cm인 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"원주가 43.96 cm인 원의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["먼저 지름을 구해요: 43.96 ÷ 3.14 = 14예요.","반지름은 지름의 반이에요.","14 ÷ 2 = 7 — 반지름은 7이에요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"원주가 50.24 cm인 원의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["먼저 지름을 구해요: 50.24 ÷ 3.14 = 16이에요.","반지름은 지름의 반이에요.","16 ÷ 2 = 8 — 반지름은 8이에요."]},{"stem":"운동장에 줄을 이용하여 원주가 31.4 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["5"],"explanation":["먼저 지름을 구해요: 31.4 ÷ 3.14 = 10이에요.","반지름은 지름의 반이에요.","10 ÷ 2 = 5 — 반지름은 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#13','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C4',3,'mc','auto','세 원의 크기를 견주려고 해요. ㉠ 원주가 31.4 cm · ㉡ 지름이 12 cm · ㉢ 반지름이 7 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X20']::text[],true,'{"seq":13,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 31.4 cm · ㉡ 지름이 12 cm · ㉢ 반지름이 7 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 10 cm · ㉡ 지름 12 cm · ㉢ 지름 14 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."],"variant_rule":{"alt":[{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 62.8 cm · ㉡ 지름이 18 cm · ㉢ 반지름이 11 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 20 cm · ㉡ 지름 18 cm · ㉢ 지름 22 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉠, ㉡예요."]},{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 40.82 cm · ㉡ 지름이 14 cm · ㉢ 반지름이 6 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉡, ㉠, ㉢","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉢, ㉠, ㉡","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 13 cm · ㉡ 지름 14 cm · ㉢ 지름 12 cm예요.","지름이 긴 원부터 놓으면 ㉡, ㉠, ㉢예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#14','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C5',1,'mc','auto','한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 52칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X10']::text[],true,'{"seq":14,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 52칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"52 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"52 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"52 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 52 cm²보다 넓고 88 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 32칸, 걸친 칸까지 세면 52칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"32 cm²보다 넓고 52 cm²보다 좁아요","correct":true},{"t":"32 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"52 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"32 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 32 cm²보다 넓고 52 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 276칸, 걸친 칸까지 세면 344칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"276 cm²보다 넓고 344 cm²보다 좁아요","correct":true},{"t":"276 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"344 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"276 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 276 cm²보다 넓고 344 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#15','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C5',2,'sa','auto','반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["64"],"explanation":["원 밖 정사각형의 한 변은 지름 8 cm예요.","8 × 8 = 64예요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","12 × 12 ÷ 2 = 72예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]},{"stem":"반지름이 3 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["원 밖 정사각형의 한 변은 지름 6 cm예요.","6 × 6 = 36이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#16','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 2 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X14','M6-2-u5-X13','M6-2-u5-X20']::text[],true,'{"seq":16,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 2 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"12.56 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X14"},{"t":"50.24 cm²","mis":"M6-2-u5-X13"},{"t":"4 cm²","mis":"M6-2-u5-X20"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","2 × 2 × 3.14를 계산해요.","2 × 2 × 3.14 = 12.56 — 넓이는 12.56 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"},{"t":"200.96 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."]},{"stem":"반지름이 6 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#17','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',2,'mc','auto','지름이 10 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"지름이 10 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 10 ÷ 2 = 5 cm예요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 16 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"},{"t":"25.12 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 16 ÷ 2 = 8 cm예요.","8 × 8 × 3.14를 계산해요.","8 × 8 × 3.14 = 200.96 — 넓이는 200.96 cm²예요."]},{"stem":"지름이 20 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 20 ÷ 2 = 10 cm예요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#18','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["(반지름) × (반지름) × 3.14 = 28.26이에요.","28.26 ÷ 3.14 = 9니 (반지름) × (반지름) = 9예요.","같은 수를 두 번 곱해 9가 되는 수는 3 — 반지름은 3 cm예요."]},{"stem":"넓이가 50.24 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["(반지름) × (반지름) × 3.14 = 50.24예요.","50.24 ÷ 3.14 = 16이니 (반지름) × (반지름) = 16이에요.","같은 수를 두 번 곱해 16이 되는 수는 4 — 반지름은 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#19','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C6',4,'mc','auto','가로가 30 cm, 세로가 16 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":19,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"가로가 30 cm, 세로가 16 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X19"},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 16 cm를 넘을 수 없어요.","반지름은 8 cm예요.","8 × 8 × 3.14 = 200.96 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 12 cm, 세로가 25 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"490.625 cm²","mis":"M6-2-u5-X19"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."]},{"stem":"가로가 18 cm, 세로가 10 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"254.34 cm²","mis":"M6-2-u5-X19"},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 10 cm를 넘을 수 없어요.","반지름은 5 cm예요.","5 × 5 × 3.14 = 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#20','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":20,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 - 50.24 = 103.62 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 - 153.86 = 160.14 cm²예요."]},{"stem":"반지름이 6 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"84.78 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"141.3 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","작은 원의 넓이는 3 × 3 × 3.14 = 28.26 cm²예요.","113.04 - 28.26 = 84.78 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#21','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C7',3,'mc','auto','하린은 지름이 20 cm인 원 모양 팬케이크를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 하린이 먹은 팬케이크의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X12']::text[],true,'{"seq":21,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"하린은 지름이 20 cm인 원 모양 팬케이크를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 하린이 먹은 팬케이크의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"15.7 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 20 ÷ 2 = 10 cm예요.","팬케이크 전체는 10 × 10 × 3.14 = 314 cm²예요.","4조각 중 한 조각은 314 ÷ 4 = 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"도윤은 지름이 30 cm인 원 모양 케이크를 똑같이 6조각으로 나눈 것 가운데 한 조각을 먹었어요. 도윤이 먹은 케이크의 넓이는 몇 cm²인가요?","options":[{"t":"117.75 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X17"},{"t":"471 cm²","mis":"M6-2-u5-X13"},{"t":"235.5 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 30 ÷ 2 = 15 cm예요.","케이크 전체는 15 × 15 × 3.14 = 706.5 cm²예요.","6조각 중 한 조각은 706.5 ÷ 6 = 117.75 cm²예요."]},{"stem":"여울은 지름이 16 cm인 원 모양 부침개를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 여울이 먹은 부침개의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X17"},{"t":"100.48 cm²","mis":"M6-2-u5-X17"},{"t":"12.56 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 16 ÷ 2 = 8 cm예요.","부침개 전체는 8 × 8 × 3.14 = 200.96 cm²예요.","4조각 중 한 조각은 200.96 ÷ 4 = 50.24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#22','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C7',3,'sa','auto','가로 20 cm, 세로 10 cm인 직사각형 안에 반지름이 10 cm인 반원이 꼭 맞게 들어 있어요. 직사각형에서 반원을 뺀 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":22,"concept":"M6-2-u5-C7","difficulty":3,"kind":"sa","stem":"가로 20 cm, 세로 10 cm인 직사각형 안에 반지름이 10 cm인 반원이 꼭 맞게 들어 있어요. 직사각형에서 반원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["43"],"explanation":["직사각형의 넓이는 20 × 10 = 200 cm²예요.","반원은 10 × 10 × 3.14 ÷ 2 = 157 cm²예요.","200 - 157 = 43 cm²예요."],"variant_rule":{"alt":[{"stem":"한 변이 20 cm인 정사각형의 한 꼭짓점을 중심으로 반지름이 20 cm인 사분원을 그렸어요. 정사각형에서 사분원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","사분원은 20 × 20 × 3.14 ÷ 4 = 314 cm²예요.","400 - 314 = 86 cm²예요."]},{"stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 14 cm, 세로 7 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["98"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","14 × 7 = 98 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#23','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C8',1,'sa','auto','원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 두 번 곱하는 반지름이 모두 3배예요.","3 × 3 = 9배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 4배가 되면 원의 넓이는 몇 배가 되나요?","answer":["16"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 4배면 두 번 곱하는 반지름이 모두 4배예요.","4 × 4 = 16배가 돼요."]},{"stem":"원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","answer":["25"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 5배면 두 번 곱하는 반지름이 모두 5배예요.","5 × 5 = 25배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#24','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C8',4,'essay','teacher','반지름이 10 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석의 넓이는 작은 방석의 몇 배인지 두 가지 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"반지름이 10 cm인 방석과 반지름이 20 cm인 방석이 있어요. 큰 방석의 넓이는 작은 방석의 몇 배인지 두 가지 방법으로 설명해 보세요.","answer_guide":{"answer":"예: ① 넓이를 직접 구하면 314 cm²와 1256 cm²이고 1256 ÷ 314 = 4배이다. ② 반지름이 2배이고 넓이는 반지름을 두 번 곱하므로 2 × 2 = 4배이다.","scoring_points":["두 넓이를 구해 4배를 보였는가","반지름이 2배임을 밝혔는가","두 번 곱하는 규칙으로 4배를 설명했는가"]},"explanation":["314 cm²와 1256 cm²예요.","1256 ÷ 314 = 4예요.","반지름 2배 → 2 × 2 = 4배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_b#25','math',6,2,'u5','','g6_2_math_u5_review_b','unit_review','M6-2-u5-C4',4,'essay','teacher','길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 반지름을 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u5-C4","difficulty":4,"kind":"essay","stem":"길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 반지름을 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 종이띠의 길이가 원주이다. (지름) = (원주) ÷ (원주율)이므로 78.5 ÷ 3.14 = 25 cm이고, 반지름은 25 ÷ 2 = 12.5 cm이다.","scoring_points":["종이띠의 길이가 원주임을 밝혔는가","지름 25 cm를 구했는가","반지름 12.5 cm를 구했는가"]},"explanation":["종이띠의 길이가 원주예요.","78.5 ÷ 3.14 = 25 cm예요.","반지름은 12.5 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#1','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C1',1,'mc','auto','원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원의 중심을 지나도록 원 위의 두 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심을 지나도록 원 위의 두 점을 이은 선분을 지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원을 그릴 때 누름 못이 꽂혔던 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원을 그릴 때 누름 못이 꽂혔던 점을 원의 중심이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#2','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C1',1,'sa','auto','반지름이 11 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"반지름이 11 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["22"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","11 × 2 = 22 — 지름은 22 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 13 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["26"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","13 × 2 = 26 — 지름은 26 cm예요."]},{"stem":"반지름이 5 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["10"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","5 × 2 = 10 — 지름은 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#3','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C1',2,'sa','auto','지름이 9 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 9 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["27"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 4.5이고 변이 6개이니 둘레는 4.5 × 6이에요.","4.5 × 6 = 27 — 지름의 3배인 27 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 9 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 9 cm이고 변이 4개예요.","9 × 4 = 36 — 지름의 4배인 36 cm예요."]},{"stem":"지름이 5 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["15"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 2.5이고 변이 6개이니 둘레는 2.5 × 6이에요.","2.5 × 6 = 15 — 지름의 3배인 15 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#4','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',1,'mc','auto','원주율을 어림하여 쓸 때 흔히 쓰는 값은 어느 것인가요?',ARRAY['M6-2-u5-X06','M6-2-u5-X20']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"원주율을 어림하여 쓸 때 흔히 쓰는 값은 어느 것인가요?","options":[{"t":"3.14","correct":true},{"t":"4","mis":"M6-2-u5-X06"},{"t":"2","mis":"M6-2-u5-X06"},{"t":"0.314","mis":"M6-2-u5-X20"}],"explanation":["원주율을 소수로 나타내면 3.14159…처럼 끝없이 이어져요.","그래서 어림하여 쓰는데 흔히 3.14를 써요.","원주는 지름의 약 3.14배예요."],"variant_rule":{"alt":[{"stem":"어떤 원의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"21.4","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."]},{"stem":"원주율을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (지름)","correct":true},{"t":"(지름) ÷ (원주)","mis":"M6-2-u5-X04"},{"t":"(원주) × (지름)","mis":"M6-2-u5-X04"},{"t":"(원주) ÷ (반지름)","mis":"M6-2-u5-X04"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비율은 (비교하는 양) ÷ (기준량) — 기준량은 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#5','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',2,'ox','auto','원주율 3.14는 정확한 값이에요.',ARRAY['M6-2-u5-X06']::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":2,"kind":"ox","stem":"원주율 3.14는 정확한 값이에요.","answer":"X","reason_options":[{"t":"원주율은 끝없이 이어지는 소수라 3.14는 어림한 값이기 때문에","correct":true},{"t":"원주를 지름으로 나누면 언제나 3.14로 딱 떨어지기 때문에","mis":"M6-2-u5-X06"}],"mis":"M6-2-u5-X06","explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."],"variant_rule":{"alt":[{"stem":"원주는 지름의 약 3.14배예요.","answer":"O","reason_options":[{"t":"원주율이 약 3.14이기 때문에","correct":true},{"t":"원주는 지름에 3.14를 더한 값이기 때문에","mis":"M6-2-u5-X08"}],"explanation":["(원주율) = (원주) ÷ (지름)이에요.","원주율은 약 3.14예요.","그래서 원주는 지름의 약 3.14배예요."]},{"stem":"지름이 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"지름이 길어지면 원주도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"큰 원일수록 둘레가 길어 원주율도 크기 때문에","mis":"M6-2-u5-X05"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#6','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C2',3,'mc','auto','연필꽂이의 원주를 재었더니 59.75 cm, 지름은 19 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X04']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"연필꽂이의 원주를 재었더니 59.75 cm, 지름은 19 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["59.75 ÷ 19 = 3.14473…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."],"variant_rule":{"alt":[{"stem":"냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."]},{"stem":"냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["22 ÷ 7 = 3.142857…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#7','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 15 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X12']::text[],true,'{"seq":7,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 15 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"47.1 cm","correct":true},{"t":"23.55 cm","mis":"M6-2-u5-X01"},{"t":"94.2 cm","mis":"M6-2-u5-X01"},{"t":"176.625 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","15 × 3.14를 계산해요.","15 × 3.14 = 47.1 — 원주는 47.1 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X01"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"7.14 cm","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","4 × 3.14를 계산해요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."]},{"stem":"지름이 10 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X01"},{"t":"62.8 cm","mis":"M6-2-u5-X01"},{"t":"78.5 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","10 × 3.14를 계산해요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#8','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',2,'mc','auto','반지름이 5 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":8,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"반지름이 5 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X07"},{"t":"78.5 cm","mis":"M6-2-u5-X12"},{"t":"62.8 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 5 cm에 2를 곱해 지름 10 cm를 먼저 만들어요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."]},{"stem":"반지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u5-X07"},{"t":"50.24 cm","mis":"M6-2-u5-X12"},{"t":"6.28 cm","mis":"M6-2-u5-X07"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 — 원주는 25.12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#9','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',2,'mc','auto','지름이 40 cm인 훌라후프를 3바퀴 굴렸어요. 훌라후프가 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X07','M6-2-u5-X02']::text[],true,'{"seq":9,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 40 cm인 훌라후프를 3바퀴 굴렸어요. 훌라후프가 굴러간 거리는 몇 cm인가요?","options":[{"t":"376.8 cm","correct":true},{"t":"125.6 cm","mis":"M6-2-u5-X19"},{"t":"188.4 cm","mis":"M6-2-u5-X07"},{"t":"120 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 40 × 3.14 = 125.6 cm예요.","3바퀴면 125.6 × 3 = 376.8 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 50 cm인 바퀴를 2바퀴 굴렸어요. 바퀴가 굴러간 거리는 몇 cm인가요?","options":[{"t":"314 cm","correct":true},{"t":"157 cm","mis":"M6-2-u5-X19"},{"t":"100 cm","mis":"M6-2-u5-X02"},{"t":"628 cm","mis":"M6-2-u5-X01"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 50 × 3.14 = 157 cm예요.","2바퀴면 157 × 2 = 314 cm예요."]},{"stem":"지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"628 cm","correct":true},{"t":"62.8 cm","mis":"M6-2-u5-X19"},{"t":"314 cm","mis":"M6-2-u5-X07"},{"t":"200 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#10','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C3',3,'mc','auto','바깥쪽 원의 지름이 60 cm인 바퀴를 10바퀴 굴렸어요. 이 바퀴가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":10,"concept":"M6-2-u5-C3","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 지름이 60 cm인 바퀴를 10바퀴 굴렸어요. 이 바퀴가 굴러간 거리는 몇 m인가요?","options":[{"t":"18.84 m","correct":true},{"t":"1884 m","mis":"M6-2-u5-X20"},{"t":"1.884 m","mis":"M6-2-u5-X19"},{"t":"9.42 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 60 × 3.14 = 188.4 cm예요.","10바퀴면 188.4 × 10 = 1884 cm예요.","100 cm = 1 m니 18.84 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 40 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.256 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","5바퀴면 125.6 × 5 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]},{"stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#11','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C4',1,'sa','auto','원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"원 모양 호수의 둘레가 157 m예요. 호수의 중심을 지나는 다리의 길이는 몇 m인가요?","answer":["50"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","157 ÷ 3.14를 계산해요.","157 ÷ 3.14 = 50이에요."],"variant_rule":{"alt":[{"stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."]},{"stem":"길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?","answer":["25"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","78.5 ÷ 3.14를 계산해요.","78.5 ÷ 3.14 = 25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#12','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C4',2,'sa','auto','원주가 50.24 cm인 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"원주가 50.24 cm인 원의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["먼저 지름을 구해요: 50.24 ÷ 3.14 = 16이에요.","반지름은 지름의 반이에요.","16 ÷ 2 = 8 — 반지름은 8이에요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"운동장에 줄을 이용하여 원주가 31.4 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["5"],"explanation":["먼저 지름을 구해요: 31.4 ÷ 3.14 = 10이에요.","반지름은 지름의 반이에요.","10 ÷ 2 = 5 — 반지름은 5예요."]},{"stem":"체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["4"],"explanation":["먼저 지름을 구해요: 25.12 ÷ 3.14 = 8이에요.","반지름은 지름의 반이에요.","8 ÷ 2 = 4 — 반지름은 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#13','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C4',3,'mc','auto','세 원의 크기를 견주려고 해요. ㉠ 원주가 62.8 cm · ㉡ 지름이 18 cm · ㉢ 반지름이 11 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X19','M6-2-u5-X20']::text[],true,'{"seq":13,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 62.8 cm · ㉡ 지름이 18 cm · ㉢ 반지름이 11 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉠, ㉢","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 20 cm · ㉡ 지름 18 cm · ㉢ 지름 22 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉠, ㉡예요."],"variant_rule":{"alt":[{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 40.82 cm · ㉡ 지름이 14 cm · ㉢ 반지름이 6 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉡, ㉠, ㉢","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉢, ㉠, ㉡","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 13 cm · ㉡ 지름 14 cm · ㉢ 지름 12 cm예요.","지름이 긴 원부터 놓으면 ㉡, ㉠, ㉢예요."]},{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 15 cm · ㉡ 지름 16 cm · ㉢ 지름 18 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#14','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C5',1,'mc','auto','한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 32칸, 걸친 칸까지 세면 52칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X10']::text[],true,'{"seq":14,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 32칸, 걸친 칸까지 세면 52칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"32 cm²보다 넓고 52 cm²보다 좁아요","correct":true},{"t":"32 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"52 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"32 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 32 cm²보다 넓고 52 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 276칸, 걸친 칸까지 세면 344칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"276 cm²보다 넓고 344 cm²보다 좁아요","correct":true},{"t":"276 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"344 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"276 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 276 cm²보다 넓고 344 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"60 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"60 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"60 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 60 cm²보다 넓고 88 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#15','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C5',2,'sa','auto','반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 6 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 12 cm예요. 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","12 × 12 ÷ 2 = 72예요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["원 밖 정사각형의 한 변은 지름 6 cm예요.","6 × 6 = 36이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]},{"stem":"반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","10 × 10 ÷ 2 = 50이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#16','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 4 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":16,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 4 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"25.12 cm²","mis":"M6-2-u5-X12"},{"t":"12.56 cm²","mis":"M6-2-u5-X14"},{"t":"200.96 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","4 × 4 × 3.14를 계산해요.","4 × 4 × 3.14 = 50.24 — 넓이는 50.24 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."]},{"stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#17','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',2,'mc','auto','지름이 16 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"지름이 16 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"},{"t":"25.12 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 16 ÷ 2 = 8 cm예요.","8 × 8 × 3.14를 계산해요.","8 × 8 × 3.14 = 200.96 — 넓이는 200.96 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 20 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 20 ÷ 2 = 10 cm예요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."]},{"stem":"지름이 24 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 24 ÷ 2 = 12 cm예요.","12 × 12 × 3.14를 계산해요.","12 × 12 × 3.14 = 452.16 — 넓이는 452.16 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#18','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 28.26 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["(반지름) × (반지름) × 3.14 = 28.26이에요.","28.26 ÷ 3.14 = 9니 (반지름) × (반지름) = 9예요.","같은 수를 두 번 곱해 9가 되는 수는 3 — 반지름은 3 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 50.24 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["(반지름) × (반지름) × 3.14 = 50.24예요.","50.24 ÷ 3.14 = 16이니 (반지름) × (반지름) = 16이에요.","같은 수를 두 번 곱해 16이 되는 수는 4 — 반지름은 4 cm예요."]},{"stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#19','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C6',4,'mc','auto','가로가 12 cm, 세로가 25 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":19,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"가로가 12 cm, 세로가 25 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"490.625 cm²","mis":"M6-2-u5-X19"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"},{"t":"37.68 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 12 cm를 넘을 수 없어요.","반지름은 6 cm예요.","6 × 6 × 3.14 = 113.04 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 18 cm, 세로가 10 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"254.34 cm²","mis":"M6-2-u5-X19"},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 10 cm를 넘을 수 없어요.","반지름은 5 cm예요.","5 × 5 × 3.14 = 78.5 cm²예요."]},{"stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X19"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#20','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":20,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 10 cm인 원에서 반지름이 7 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"160.14 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"467.86 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","작은 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","314 - 153.86 = 160.14 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 6 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"84.78 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"141.3 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","작은 원의 넓이는 3 × 3 × 3.14 = 28.26 cm²예요.","113.04 - 28.26 = 84.78 cm²예요."]},{"stem":"반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 - 3.14 = 47.1 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#21','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C7',3,'mc','auto','도윤은 지름이 30 cm인 원 모양 케이크를 똑같이 6조각으로 나눈 것 가운데 한 조각을 먹었어요. 도윤이 먹은 케이크의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X13']::text[],true,'{"seq":21,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"도윤은 지름이 30 cm인 원 모양 케이크를 똑같이 6조각으로 나눈 것 가운데 한 조각을 먹었어요. 도윤이 먹은 케이크의 넓이는 몇 cm²인가요?","options":[{"t":"117.75 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X17"},{"t":"471 cm²","mis":"M6-2-u5-X13"},{"t":"235.5 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 30 ÷ 2 = 15 cm예요.","케이크 전체는 15 × 15 × 3.14 = 706.5 cm²예요.","6조각 중 한 조각은 706.5 ÷ 6 = 117.75 cm²예요."],"variant_rule":{"alt":[{"stem":"여울은 지름이 16 cm인 원 모양 부침개를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 여울이 먹은 부침개의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X17"},{"t":"100.48 cm²","mis":"M6-2-u5-X17"},{"t":"12.56 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 16 ÷ 2 = 8 cm예요.","부침개 전체는 8 × 8 × 3.14 = 200.96 cm²예요.","4조각 중 한 조각은 200.96 ÷ 4 = 50.24 cm²예요."]},{"stem":"세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X17"},{"t":"226.08 cm²","mis":"M6-2-u5-X13"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 24 ÷ 2 = 12 cm예요.","피자 전체는 12 × 12 × 3.14 = 452.16 cm²예요.","8조각 중 한 조각은 452.16 ÷ 8 = 56.52 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#22','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C7',3,'sa','auto','한 변이 20 cm인 정사각형의 한 꼭짓점을 중심으로 반지름이 20 cm인 사분원을 그렸어요. 정사각형에서 사분원을 뺀 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":22,"concept":"M6-2-u5-C7","difficulty":3,"kind":"sa","stem":"한 변이 20 cm인 정사각형의 한 꼭짓점을 중심으로 반지름이 20 cm인 사분원을 그렸어요. 정사각형에서 사분원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","사분원은 20 × 20 × 3.14 ÷ 4 = 314 cm²예요.","400 - 314 = 86 cm²예요."],"variant_rule":{"alt":[{"stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 14 cm, 세로 7 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["98"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","14 × 7 = 98 cm²예요."]},{"stem":"한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","400 - 314 = 86 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#23','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C8',1,'sa','auto','원의 반지름이 4배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"원의 반지름이 4배가 되면 원의 넓이는 몇 배가 되나요?","answer":["16"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 4배면 두 번 곱하는 반지름이 모두 4배예요.","4 × 4 = 16배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","answer":["25"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 5배면 두 번 곱하는 반지름이 모두 5배예요.","5 × 5 = 25배가 돼요."]},{"stem":"원의 반지름이 2배가 되면 원의 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 2배면 두 번 곱하는 반지름이 모두 2배예요.","2 × 2 = 4배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#24','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C8',4,'essay','teacher','넓이가 9배인 원 모양 방석을 만들려면 반지름을 몇 배로 해야 하는지 구하고, 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"넓이가 9배인 원 모양 방석을 만들려면 반지름을 몇 배로 해야 하는지 구하고, 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 3배로 해야 한다. 넓이는 반지름을 두 번 곱하므로 반지름이 □배면 넓이는 □ × □배이고, □ × □ = 9인 □는 3이다.","scoring_points":["3배라고 답했는가","넓이가 □ × □배라는 규칙을 썼는가","□ × □ = 9에서 3을 찾았는가"]},"explanation":["넓이는 반지름을 두 번 곱해요.","□ × □ = 9예요.","□ = 3 — 반지름을 3배로 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_c#25','math',6,2,'u5','','g6_2_math_u5_review_c','unit_review','M6-2-u5-C4',4,'essay','teacher','세 원 ㉠ 원주 47.1 cm, ㉡ 지름 16 cm, ㉢ 반지름 9 cm의 크기를 견주려고 해요. 어떻게 견주면 좋을지 쓰고 큰 원부터 차례로 놓아 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u5-C4","difficulty":4,"kind":"essay","stem":"세 원 ㉠ 원주 47.1 cm, ㉡ 지름 16 cm, ㉢ 반지름 9 cm의 크기를 견주려고 해요. 어떻게 견주면 좋을지 쓰고 큰 원부터 차례로 놓아 보세요.","answer_guide":{"answer":"예: 셋을 모두 지름으로 바꾸어 견준다. ㉠은 47.1 ÷ 3.14 = 15 cm, ㉡은 16 cm, ㉢은 9 × 2 = 18 cm이므로 큰 원부터 ㉢, ㉡, ㉠이다.","scoring_points":["같은 것(지름)으로 바꾸어 견준다고 썼는가","세 지름 15·16·18 cm를 구했는가","㉢, ㉡, ㉠ 차례를 썼는가"]},"explanation":["모두 지름으로 바꾸어요.","㉠ 15 cm, ㉡ 16 cm, ㉢ 18 cm예요.","큰 원부터 ㉢, ㉡, ㉠이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#1','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C1',1,'mc','auto','원을 그릴 때 누름 못이 꽂혔던 점을 무엇이라고 하나요?',ARRAY['M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":1,"concept":"M6-2-u5-C1","difficulty":1,"kind":"mc","stem":"원을 그릴 때 누름 못이 꽂혔던 점을 무엇이라고 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원을 그릴 때 누름 못이 꽂혔던 점을 원의 중심이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."],"variant_rule":{"alt":[{"stem":"원의 둘레를 무엇이라고 하나요?","options":[{"t":"원주","correct":true},{"t":"반지름","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X02"},{"t":"원의 중심","mis":"M6-2-u5-X02"}],"explanation":["원의 둘레를 원주라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]},{"stem":"원의 중심과 원 위의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"반지름","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"지름","mis":"M6-2-u5-X01"},{"t":"원의 중심","mis":"M6-2-u5-X01"}],"explanation":["원의 중심과 원 위의 한 점을 이은 선분을 반지름이라고 해요.","원의 중심과 원 위의 한 점을 이으면 반지름, 중심을 지나 원 위의 두 점을 이으면 지름이에요.","원주는 원의 둘레의 길이를 말하기도 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#2','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C1',1,'sa','auto','반지름이 13 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u5-C1","difficulty":1,"kind":"sa","stem":"반지름이 13 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["26"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","13 × 2 = 26 — 지름은 26 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["10"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","5 × 2 = 10 — 지름은 10 cm예요."]},{"stem":"반지름이 8 cm인 원이 있어요. 이 원의 지름은 몇 cm인가요?","answer":["16"],"explanation":["지름은 원의 중심을 지나니 반지름 두 개를 이은 길이예요.","(지름) = (반지름) × 2예요.","8 × 2 = 16 — 지름은 16 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#3','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C1',2,'sa','auto','지름이 9 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u5-C1","difficulty":2,"kind":"sa","stem":"지름이 9 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 9 cm이고 변이 4개예요.","9 × 4 = 36 — 지름의 4배인 36 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 5 cm인 원 안에 꼭 맞는 정육각형이 있어요. 이 정육각형의 둘레는 몇 cm인가요?","answer":["15"],"explanation":["원 안에 꼭 맞는 정육각형의 한 변은 반지름과 같아요.","반지름은 2.5이고 변이 6개이니 둘레는 2.5 × 6이에요.","2.5 × 6 = 15 — 지름의 3배인 15 cm예요."]},{"stem":"지름이 5 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 둘레는 몇 cm인가요?","answer":["20"],"explanation":["원 밖에 꼭 맞는 정사각형의 한 변은 지름과 같아요.","한 변이 5 cm이고 변이 4개예요.","5 × 4 = 20 — 지름의 4배인 20 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#4','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C2',1,'mc','auto','어떤 원의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?',ARRAY['M6-2-u5-X04','M6-2-u5-X20']::text[],true,'{"seq":4,"concept":"M6-2-u5-C2","difficulty":1,"kind":"mc","stem":"어떤 원의 원주가 31.4 cm, 지름이 10 cm예요. (원주) ÷ (지름)을 계산하면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"6.28","mis":"M6-2-u5-X04"},{"t":"21.4","mis":"M6-2-u5-X20"},{"t":"31.4","mis":"M6-2-u5-X20"}],"explanation":["(원주) ÷ (지름)을 계산해요.","31.4 ÷ 10 = 3.14예요.","이 값이 원주율 — 어떤 원에서도 3.14쯤 나와요."],"variant_rule":{"alt":[{"stem":"원주율을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(원주) ÷ (지름)","correct":true},{"t":"(지름) ÷ (원주)","mis":"M6-2-u5-X04"},{"t":"(원주) × (지름)","mis":"M6-2-u5-X04"},{"t":"(원주) ÷ (반지름)","mis":"M6-2-u5-X04"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","비율은 (비교하는 양) ÷ (기준량) — 기준량은 지름이에요.","그래서 (원주율) = (원주) ÷ (지름)이에요."]},{"stem":"원의 지름에 대한 원주의 비율을 무엇이라고 하나요?","options":[{"t":"원주율","correct":true},{"t":"원주","mis":"M6-2-u5-X02"},{"t":"반지름","mis":"M6-2-u5-X01"},{"t":"지름","mis":"M6-2-u5-X01"}],"explanation":["원의 둘레가 원주예요.","모든 원에서 지름에 대한 원주의 비율은 일정해요.","그 비율을 원주율이라고 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#5','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C2',2,'ox','auto','원주는 지름의 약 3.14배예요.',ARRAY['M6-2-u5-X08']::text[],true,'{"seq":5,"concept":"M6-2-u5-C2","difficulty":2,"kind":"ox","stem":"원주는 지름의 약 3.14배예요.","answer":"O","reason_options":[{"t":"원주율이 약 3.14이기 때문에","correct":true},{"t":"원주는 지름에 3.14를 더한 값이기 때문에","mis":"M6-2-u5-X08"}],"mis":"M6-2-u5-X08","explanation":["(원주율) = (원주) ÷ (지름)이에요.","원주율은 약 3.14예요.","그래서 원주는 지름의 약 3.14배예요."],"variant_rule":{"alt":[{"stem":"지름이 길어지면 원주율도 커져요.","answer":"X","reason_options":[{"t":"지름이 길어지면 원주도 함께 길어져 비율은 그대로이기 때문에","correct":true},{"t":"큰 원일수록 둘레가 길어 원주율도 크기 때문에","mis":"M6-2-u5-X05"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]},{"stem":"작은 동전과 큰 접시의 원주율은 같아요.","answer":"O","reason_options":[{"t":"모든 원에서 지름에 대한 원주의 비율은 일정하기 때문에","correct":true},{"t":"동전과 접시는 크기가 달라 원주율도 달라야 하기 때문에","mis":"M6-2-u5-X05"}],"explanation":["원주율은 원의 지름에 대한 원주의 비율이에요.","원이 커지면 원주와 지름이 함께 늘어 비율은 변하지 않아요.","원주율은 3.14159…로 끝없이 이어져 3.14로 어림해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#6','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C2',3,'mc','auto','냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?',ARRAY['M6-2-u5-X05','M6-2-u5-X06']::text[],true,'{"seq":6,"concept":"M6-2-u5-C2","difficulty":3,"kind":"mc","stem":"냄비 뚜껑의 (원주) ÷ (지름)은 3.142857…, 물병의 값은 3.13846…였어요. 값이 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"원주와 지름을 정확하게 재기 어렵기 때문에","correct":true},{"t":"원마다 원주율이 다르기 때문에","mis":"M6-2-u5-X05"},{"t":"큰 원일수록 원주율이 크기 때문에","mis":"M6-2-u5-X05"},{"t":"원주율이 3.14로 정해져 있지 않기 때문에","mis":"M6-2-u5-X06"}],"explanation":["원주율은 모든 원에서 일정해요.","줄자·자로 재는 값에는 작은 차이가 생겨요.","그래서 잰 값이 조금씩 달라도 늘 3.14쯤이 나와요."],"variant_rule":{"alt":[{"stem":"냄비 뚜껑의 원주를 재었더니 22 cm, 지름은 7 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["22 ÷ 7 = 3.142857…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]},{"stem":"물병의 원주를 재었더니 40.8 cm, 지름은 13 cm였어요. (원주) ÷ (지름)을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.14","correct":true},{"t":"3.15","mis":"M6-2-u5-X20"},{"t":"3.1","mis":"M6-2-u5-X20"},{"t":"0.32","mis":"M6-2-u5-X04"}],"explanation":["40.8 ÷ 13 = 3.13846…이에요.","소수 셋째 자리를 보고 반올림해요.","그래서 3.14 — 원주율과 같은 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#7','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',1,'mc','auto','지름이 4 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X08']::text[],true,'{"seq":7,"concept":"M6-2-u5-C3","difficulty":1,"kind":"mc","stem":"지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"6.28 cm","mis":"M6-2-u5-X01"},{"t":"25.12 cm","mis":"M6-2-u5-X01"},{"t":"7.14 cm","mis":"M6-2-u5-X08"}],"explanation":["(원주) = (지름) × (원주율)이에요.","4 × 3.14를 계산해요.","4 × 3.14 = 12.56 — 원주는 12.56 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 10 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u5-X01"},{"t":"62.8 cm","mis":"M6-2-u5-X01"},{"t":"78.5 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","10 × 3.14를 계산해요.","10 × 3.14 = 31.4 — 원주는 31.4 cm예요."]},{"stem":"지름이 7 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"21.98 cm","correct":true},{"t":"10.99 cm","mis":"M6-2-u5-X01"},{"t":"43.96 cm","mis":"M6-2-u5-X01"},{"t":"38.465 cm","mis":"M6-2-u5-X12"}],"explanation":["(원주) = (지름) × (원주율)이에요.","7 × 3.14를 계산해요.","7 × 3.14 = 21.98 — 원주는 21.98 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#8','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',2,'mc','auto','반지름이 6 cm인 원의 원주는 몇 cm인가요?',ARRAY['M6-2-u5-X07','M6-2-u5-X12','M6-2-u5-X01']::text[],true,'{"seq":8,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"반지름이 6 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u5-X07"},{"t":"113.04 cm","mis":"M6-2-u5-X12"},{"t":"75.36 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 — 원주는 37.68 cm예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u5-X07"},{"t":"50.24 cm","mis":"M6-2-u5-X12"},{"t":"6.28 cm","mis":"M6-2-u5-X07"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 — 원주는 25.12 cm예요."]},{"stem":"반지름이 9 cm인 원의 원주는 몇 cm인가요?","options":[{"t":"56.52 cm","correct":true},{"t":"28.26 cm","mis":"M6-2-u5-X07"},{"t":"254.34 cm","mis":"M6-2-u5-X12"},{"t":"113.04 cm","mis":"M6-2-u5-X01"}],"explanation":["반지름에 바로 원주율을 곱하면 안 돼요.","반지름 9 cm에 2를 곱해 지름 18 cm를 먼저 만들어요.","18 × 3.14 = 56.52 — 원주는 56.52 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#9','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',2,'mc','auto','지름이 50 cm인 바퀴를 2바퀴 굴렸어요. 바퀴가 굴러간 거리는 몇 cm인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X02','M6-2-u5-X01']::text[],true,'{"seq":9,"concept":"M6-2-u5-C3","difficulty":2,"kind":"mc","stem":"지름이 50 cm인 바퀴를 2바퀴 굴렸어요. 바퀴가 굴러간 거리는 몇 cm인가요?","options":[{"t":"314 cm","correct":true},{"t":"157 cm","mis":"M6-2-u5-X19"},{"t":"100 cm","mis":"M6-2-u5-X02"},{"t":"628 cm","mis":"M6-2-u5-X01"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 50 × 3.14 = 157 cm예요.","2바퀴면 157 × 2 = 314 cm예요."],"variant_rule":{"alt":[{"stem":"지름이 20 cm인 원판을 10바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"628 cm","correct":true},{"t":"62.8 cm","mis":"M6-2-u5-X19"},{"t":"314 cm","mis":"M6-2-u5-X07"},{"t":"200 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 20 × 3.14 = 62.8 cm예요.","10바퀴면 62.8 × 10 = 628 cm예요."]},{"stem":"지름이 30 cm인 원판을 5바퀴 굴렸어요. 원판이 굴러간 거리는 몇 cm인가요?","options":[{"t":"471 cm","correct":true},{"t":"94.2 cm","mis":"M6-2-u5-X19"},{"t":"235.5 cm","mis":"M6-2-u5-X07"},{"t":"150 cm","mis":"M6-2-u5-X02"}],"explanation":["한 바퀴 굴러간 거리는 원주와 같아요.","원주는 30 × 3.14 = 94.2 cm예요.","5바퀴면 94.2 × 5 = 471 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#10','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',3,'mc','auto','바깥쪽 원의 지름이 40 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?',ARRAY['M6-2-u5-X20','M6-2-u5-X19','M6-2-u5-X07']::text[],true,'{"seq":10,"concept":"M6-2-u5-C3","difficulty":3,"kind":"mc","stem":"바깥쪽 원의 지름이 40 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.256 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 40 × 3.14 = 125.6 cm예요.","5바퀴면 125.6 × 5 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."],"variant_rule":{"alt":[{"stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"7.536 m","correct":true},{"t":"753.6 m","mis":"M6-2-u5-X20"},{"t":"1.5072 m","mis":"M6-2-u5-X19"},{"t":"3.768 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 48 × 3.14 = 150.72 cm예요.","5바퀴면 150.72 × 5 = 753.6 cm예요.","100 cm = 1 m니 7.536 m예요."]},{"stem":"바깥쪽 원의 지름이 50 cm인 굴렁쇠를 4바퀴 굴렸어요. 이 굴렁쇠가 굴러간 거리는 몇 m인가요?","options":[{"t":"6.28 m","correct":true},{"t":"628 m","mis":"M6-2-u5-X20"},{"t":"1.57 m","mis":"M6-2-u5-X19"},{"t":"3.14 m","mis":"M6-2-u5-X07"}],"explanation":["한 바퀴 굴러간 거리는 50 × 3.14 = 157 cm예요.","4바퀴면 157 × 4 = 628 cm예요.","100 cm = 1 m니 6.28 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#11','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C4',1,'sa','auto','원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":11,"concept":"M6-2-u5-C4","difficulty":1,"kind":"sa","stem":"원 모양 접시의 원주를 재었더니 31.4 cm였어요. 이 접시의 지름은 몇 cm인가요?","answer":["10"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","31.4 ÷ 3.14를 계산해요.","31.4 ÷ 3.14 = 10이에요."],"variant_rule":{"alt":[{"stem":"길이가 78.5 cm인 종이띠를 겹치지 않게 붙여 원을 만들었어요. 만든 원의 지름은 몇 cm인가요?","answer":["25"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","78.5 ÷ 3.14를 계산해요.","78.5 ÷ 3.14 = 25예요."]},{"stem":"원 모양 탬버린의 원주를 재었더니 62.8 cm였어요. 이 탬버린의 지름은 몇 cm인가요?","answer":["20"],"explanation":["(지름) = (원주) ÷ (원주율)이에요.","62.8 ÷ 3.14를 계산해요.","62.8 ÷ 3.14 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#12','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C4',2,'sa','auto','운동장에 줄을 이용하여 원주가 31.4 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u5-C4","difficulty":2,"kind":"sa","stem":"운동장에 줄을 이용하여 원주가 31.4 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["5"],"explanation":["먼저 지름을 구해요: 31.4 ÷ 3.14 = 10이에요.","반지름은 지름의 반이에요.","10 ÷ 2 = 5 — 반지름은 5예요."],"mis":"M6-2-u5-X09","variant_rule":{"alt":[{"stem":"체육 시간에 줄을 이용하여 원주가 25.12 m인 원을 그리려고 해요. 원의 중심에 줄 한쪽 끝을 고정할 때 필요한 줄의 길이는 몇 m인가요?","answer":["4"],"explanation":["먼저 지름을 구해요: 25.12 ÷ 3.14 = 8이에요.","반지름은 지름의 반이에요.","8 ÷ 2 = 4 — 반지름은 4예요."]},{"stem":"원주가 43.96 cm인 원의 반지름은 몇 cm인가요?","answer":["7"],"explanation":["먼저 지름을 구해요: 43.96 ÷ 3.14 = 14예요.","반지름은 지름의 반이에요.","14 ÷ 2 = 7 — 반지름은 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#13','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C4',3,'mc','auto','세 원의 크기를 견주려고 해요. ㉠ 원주가 40.82 cm · ㉡ 지름이 14 cm · ㉢ 반지름이 6 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?',ARRAY['M6-2-u5-X01','M6-2-u5-X19','M6-2-u5-X20']::text[],true,'{"seq":13,"concept":"M6-2-u5-C4","difficulty":3,"kind":"mc","stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 40.82 cm · ㉡ 지름이 14 cm · ㉢ 반지름이 6 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉡, ㉠, ㉢","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉢, ㉠, ㉡","mis":"M6-2-u5-X19"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 13 cm · ㉡ 지름 14 cm · ㉢ 지름 12 cm예요.","지름이 긴 원부터 놓으면 ㉡, ㉠, ㉢예요."],"variant_rule":{"alt":[{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 47.1 cm · ㉡ 지름이 16 cm · ㉢ 반지름이 9 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 15 cm · ㉡ 지름 16 cm · ㉢ 지름 18 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."]},{"stem":"세 원의 크기를 견주려고 해요. ㉠ 원주가 31.4 cm · ㉡ 지름이 12 cm · ㉢ 반지름이 7 cm — 큰 원부터 차례로 놓은 것은 어느 것인가요?","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-2-u5-X01"},{"t":"㉡, ㉢, ㉠","mis":"M6-2-u5-X20"},{"t":"㉠, ㉢, ㉡","mis":"M6-2-u5-X20"}],"explanation":["세 원의 지름을 구해 같은 것으로 견주어요.","㉠ 지름 10 cm · ㉡ 지름 12 cm · ㉢ 지름 14 cm예요.","지름이 긴 원부터 놓으면 ㉢, ㉡, ㉠예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#14','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C5',1,'mc','auto','한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 276칸, 걸친 칸까지 세면 344칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u5-X10']::text[],true,'{"seq":14,"concept":"M6-2-u5-C5","difficulty":1,"kind":"mc","stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 276칸, 걸친 칸까지 세면 344칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"276 cm²보다 넓고 344 cm²보다 좁아요","correct":true},{"t":"276 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"344 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"276 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 276 cm²보다 넓고 344 cm²보다 좁아요."],"variant_rule":{"alt":[{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 60칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"60 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"60 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"60 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 60 cm²보다 넓고 88 cm²보다 좁아요."]},{"stem":"한 칸이 1 cm²인 모눈 위의 원에서 온전히 들어간 칸은 52칸, 걸친 칸까지 세면 88칸이에요. 원의 넓이가 들어갈 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"52 cm²보다 넓고 88 cm²보다 좁아요","correct":true},{"t":"52 cm²보다 좁아요","mis":"M6-2-u5-X10"},{"t":"88 cm²보다 넓어요","mis":"M6-2-u5-X10"},{"t":"52 cm²와 정확히 같아요","mis":"M6-2-u5-X10"}],"explanation":["온전히 들어간 칸만큼은 반드시 원 안에 있어요.","걸친 칸까지 세면 원을 다 덮어요.","그래서 넓이는 52 cm²보다 넓고 88 cm²보다 좁아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#15','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C5',2,'sa','auto','반지름이 3 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u5-C5","difficulty":2,"kind":"sa","stem":"반지름이 3 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["원 밖 정사각형의 한 변은 지름 6 cm예요.","6 × 6 = 36이에요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"반지름이 5 cm인 원 안에 꼭 맞는 정사각형이 있어요. 이 정사각형은 두 대각선이 모두 10 cm예요. 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["마름모·정사각형의 넓이는 (한 대각선) × (다른 대각선) ÷ 2예요.","10 × 10 ÷ 2 = 50이에요.","반지름을 한 변으로 하는 정사각형 2개와 넓이가 같아요."]},{"stem":"반지름이 4 cm인 원 밖에 꼭 맞는 정사각형이 있어요. 이 정사각형의 넓이는 몇 cm²인가요?","answer":["64"],"explanation":["원 밖 정사각형의 한 변은 지름 8 cm예요.","8 × 8 = 64예요.","반지름을 한 변으로 하는 정사각형 4개와 넓이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#16','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',1,'mc','auto','반지름이 6 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X12','M6-2-u5-X14','M6-2-u5-X13']::text[],true,'{"seq":16,"concept":"M6-2-u5-C6","difficulty":1,"kind":"mc","stem":"반지름이 6 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"113.04 cm²","correct":true},{"t":"37.68 cm²","mis":"M6-2-u5-X12"},{"t":"18.84 cm²","mis":"M6-2-u5-X14"},{"t":"452.16 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","6 × 6 × 3.14를 계산해요.","6 × 6 × 3.14 = 113.04 — 넓이는 113.04 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 3 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"28.26 cm²","correct":true},{"t":"18.84 cm²","mis":"M6-2-u5-X12"},{"t":"9.42 cm²","mis":"M6-2-u5-X14"},{"t":"113.04 cm²","mis":"M6-2-u5-X13"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","3 × 3 × 3.14를 계산해요.","3 × 3 × 3.14 = 28.26 — 넓이는 28.26 cm²예요."]},{"stem":"반지름이 2 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"12.56 cm²","correct":true},{"t":"6.28 cm²","mis":"M6-2-u5-X14"},{"t":"50.24 cm²","mis":"M6-2-u5-X13"},{"t":"4 cm²","mis":"M6-2-u5-X20"}],"explanation":["(원의 넓이) = (반지름) × (반지름) × (원주율)이에요.","2 × 2 × 3.14를 계산해요.","2 × 2 × 3.14 = 12.56 — 넓이는 12.56 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#17','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',2,'mc','auto','지름이 20 cm인 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X13','M6-2-u5-X12','M6-2-u5-X14']::text[],true,'{"seq":17,"concept":"M6-2-u5-C6","difficulty":2,"kind":"mc","stem":"지름이 20 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"314 cm²","correct":true},{"t":"1256 cm²","mis":"M6-2-u5-X13"},{"t":"62.8 cm²","mis":"M6-2-u5-X12"},{"t":"31.4 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 20 ÷ 2 = 10 cm예요.","10 × 10 × 3.14를 계산해요.","10 × 10 × 3.14 = 314 — 넓이는 314 cm²예요."],"variant_rule":{"alt":[{"stem":"지름이 24 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"452.16 cm²","correct":true},{"t":"1808.64 cm²","mis":"M6-2-u5-X13"},{"t":"75.36 cm²","mis":"M6-2-u5-X12"},{"t":"37.68 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 24 ÷ 2 = 12 cm예요.","12 × 12 × 3.14를 계산해요.","12 × 12 × 3.14 = 452.16 — 넓이는 452.16 cm²예요."]},{"stem":"지름이 10 cm인 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"},{"t":"15.7 cm²","mis":"M6-2-u5-X14"}],"explanation":["넓이는 반지름으로 구해요 — 반지름은 10 ÷ 2 = 5 cm예요.","5 × 5 × 3.14를 계산해요.","5 × 5 × 3.14 = 78.5 — 넓이는 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#18','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',3,'sa','auto','넓이가 50.24 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":18,"concept":"M6-2-u5-C6","difficulty":3,"kind":"sa","stem":"넓이가 50.24 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["(반지름) × (반지름) × 3.14 = 50.24예요.","50.24 ÷ 3.14 = 16이니 (반지름) × (반지름) = 16이에요.","같은 수를 두 번 곱해 16이 되는 수는 4 — 반지름은 4 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 314 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["(반지름) × (반지름) × 3.14 = 314예요.","314 ÷ 3.14 = 100이니 (반지름) × (반지름) = 100이에요.","같은 수를 두 번 곱해 100이 되는 수는 10 — 반지름은 10 cm예요."]},{"stem":"넓이가 78.5 cm²인 원이 있어요. 이 원의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["(반지름) × (반지름) × 3.14 = 78.5예요.","78.5 ÷ 3.14 = 25니 (반지름) × (반지름) = 25예요.","같은 수를 두 번 곱해 25가 되는 수는 5 — 반지름은 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#19','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C6',4,'mc','auto','가로가 18 cm, 세로가 10 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X19','M6-2-u5-X13','M6-2-u5-X12']::text[],true,'{"seq":19,"concept":"M6-2-u5-C6","difficulty":4,"kind":"mc","stem":"가로가 18 cm, 세로가 10 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"254.34 cm²","mis":"M6-2-u5-X19"},{"t":"314 cm²","mis":"M6-2-u5-X13"},{"t":"31.4 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 10 cm를 넘을 수 없어요.","반지름은 5 cm예요.","5 × 5 × 3.14 = 78.5 cm²예요."],"variant_rule":{"alt":[{"stem":"가로가 20 cm, 세로가 14 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"153.86 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X19"},{"t":"615.44 cm²","mis":"M6-2-u5-X13"},{"t":"43.96 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 14 cm를 넘을 수 없어요.","반지름은 7 cm예요.","7 × 7 × 3.14 = 153.86 cm²예요."]},{"stem":"가로가 30 cm, 세로가 16 cm인 직사각형 종이를 잘라 만들 수 있는 가장 큰 원의 넓이는 몇 cm²인가요?","options":[{"t":"200.96 cm²","correct":true},{"t":"706.5 cm²","mis":"M6-2-u5-X19"},{"t":"803.84 cm²","mis":"M6-2-u5-X13"},{"t":"50.24 cm²","mis":"M6-2-u5-X12"}],"explanation":["가장 큰 원의 지름은 짧은 변 16 cm를 넘을 수 없어요.","반지름은 8 cm예요.","8 × 8 × 3.14 = 200.96 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#20','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C7',2,'mc','auto','반지름이 6 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X16','M6-2-u5-X20']::text[],true,'{"seq":20,"concept":"M6-2-u5-C7","difficulty":2,"kind":"mc","stem":"반지름이 6 cm인 원에서 반지름이 3 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"84.78 cm²","correct":true},{"t":"113.04 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"141.3 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 6 × 6 × 3.14 = 113.04 cm²예요.","작은 원의 넓이는 3 × 3 × 3.14 = 28.26 cm²예요.","113.04 - 28.26 = 84.78 cm²예요."],"variant_rule":{"alt":[{"stem":"반지름이 4 cm인 원에서 반지름이 1 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"47.1 cm²","correct":true},{"t":"50.24 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"53.38 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","작은 원의 넓이는 1 × 1 × 3.14 = 3.14 cm²예요.","50.24 - 3.14 = 47.1 cm²예요."]},{"stem":"반지름이 7 cm인 원에서 반지름이 4 cm인 원을 뺀 고리 모양이에요. 고리 모양의 넓이는 몇 cm²인가요?","options":[{"t":"103.62 cm²","correct":true},{"t":"153.86 cm²","mis":"M6-2-u5-X16"},{"t":"28.26 cm²","mis":"M6-2-u5-X16"},{"t":"204.1 cm²","mis":"M6-2-u5-X20"}],"explanation":["큰 원의 넓이는 7 × 7 × 3.14 = 153.86 cm²예요.","작은 원의 넓이는 4 × 4 × 3.14 = 50.24 cm²예요.","153.86 - 50.24 = 103.62 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#21','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C7',3,'mc','auto','여울은 지름이 16 cm인 원 모양 부침개를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 여울이 먹은 부침개의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u5-X17','M6-2-u5-X12']::text[],true,'{"seq":21,"concept":"M6-2-u5-C7","difficulty":3,"kind":"mc","stem":"여울은 지름이 16 cm인 원 모양 부침개를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 여울이 먹은 부침개의 넓이는 몇 cm²인가요?","options":[{"t":"50.24 cm²","correct":true},{"t":"200.96 cm²","mis":"M6-2-u5-X17"},{"t":"100.48 cm²","mis":"M6-2-u5-X17"},{"t":"12.56 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 16 ÷ 2 = 8 cm예요.","부침개 전체는 8 × 8 × 3.14 = 200.96 cm²예요.","4조각 중 한 조각은 200.96 ÷ 4 = 50.24 cm²예요."],"variant_rule":{"alt":[{"stem":"세호는 지름이 24 cm인 원 모양 피자를 똑같이 8조각으로 나눈 것 가운데 한 조각을 먹었어요. 세호가 먹은 피자의 넓이는 몇 cm²인가요?","options":[{"t":"56.52 cm²","correct":true},{"t":"452.16 cm²","mis":"M6-2-u5-X17"},{"t":"226.08 cm²","mis":"M6-2-u5-X13"},{"t":"113.04 cm²","mis":"M6-2-u5-X17"}],"explanation":["반지름은 24 ÷ 2 = 12 cm예요.","피자 전체는 12 × 12 × 3.14 = 452.16 cm²예요.","8조각 중 한 조각은 452.16 ÷ 8 = 56.52 cm²예요."]},{"stem":"하린은 지름이 20 cm인 원 모양 팬케이크를 똑같이 4조각으로 나눈 것 가운데 한 조각을 먹었어요. 하린이 먹은 팬케이크의 넓이는 몇 cm²인가요?","options":[{"t":"78.5 cm²","correct":true},{"t":"314 cm²","mis":"M6-2-u5-X17"},{"t":"157 cm²","mis":"M6-2-u5-X17"},{"t":"15.7 cm²","mis":"M6-2-u5-X12"}],"explanation":["반지름은 20 ÷ 2 = 10 cm예요.","팬케이크 전체는 10 × 10 × 3.14 = 314 cm²예요.","4조각 중 한 조각은 314 ÷ 4 = 78.5 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#22','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C7',3,'sa','auto','아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 14 cm, 세로 7 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":22,"concept":"M6-2-u5-C7","difficulty":3,"kind":"sa","stem":"아랫부분이 반원만큼 패이고 윗부분이 반원만큼 볼록한 모양이 있어요. 아랫부분의 반원을 윗부분으로 옮겼더니 가로 14 cm, 세로 7 cm인 직사각형이 되었어요. 처음 모양의 넓이는 몇 cm²인가요?","answer":["98"],"explanation":["조각을 더하지도 덜지도 않고 자리만 옮겼어요.","그래서 넓이는 직사각형과 같아요.","14 × 7 = 98 cm²예요."],"variant_rule":{"alt":[{"stem":"한 변이 20 cm인 정사각형 안에 지름이 20 cm인 원이 꼭 맞게 들어 있어요. 정사각형에서 원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["86"],"explanation":["정사각형의 넓이는 20 × 20 = 400 cm²예요.","원의 넓이는 10 × 10 × 3.14 = 314 cm²예요.","400 - 314 = 86 cm²예요."]},{"stem":"가로 20 cm, 세로 10 cm인 직사각형 안에 반지름이 10 cm인 반원이 꼭 맞게 들어 있어요. 직사각형에서 반원을 뺀 부분의 넓이는 몇 cm²인가요?","answer":["43"],"explanation":["직사각형의 넓이는 20 × 10 = 200 cm²예요.","반원은 10 × 10 × 3.14 ÷ 2 = 157 cm²예요.","200 - 157 = 43 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#23','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C8',1,'sa','auto','원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u5-C8","difficulty":1,"kind":"sa","stem":"원의 반지름이 5배가 되면 원의 넓이는 몇 배가 되나요?","answer":["25"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 5배면 두 번 곱하는 반지름이 모두 5배예요.","5 × 5 = 25배가 돼요."],"variant_rule":{"alt":[{"stem":"원의 반지름이 2배가 되면 원의 넓이는 몇 배가 되나요?","answer":["4"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 2배면 두 번 곱하는 반지름이 모두 2배예요.","2 × 2 = 4배가 돼요."]},{"stem":"원의 반지름이 3배가 되면 원의 넓이는 몇 배가 되나요?","answer":["9"],"explanation":["넓이는 (반지름) × (반지름) × (원주율)이에요.","반지름이 3배면 두 번 곱하는 반지름이 모두 3배예요.","3 × 3 = 9배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#24','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C8',4,'essay','teacher','반지름이 3배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u5-C8","difficulty":4,"kind":"essay","stem":"반지름이 3배가 되면 원주와 원의 넓이는 각각 몇 배가 되는지 쓰고, 두 배수가 다른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원주는 3배, 넓이는 9배가 된다. 원주는 길이를 한 번 곱해 구하지만 넓이는 반지름을 두 번 곱하므로 3 × 3 = 9배가 된다.","scoring_points":["원주 3배를 썼는가","넓이 9배를 썼는가","한 번·두 번 곱하는 차이로 설명했는가"]},"explanation":["원주는 3배예요.","넓이는 3 × 3 = 9배예요.","넓이는 반지름을 두 번 곱해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u5_review_d#25','math',6,2,'u5','','g6_2_math_u5_review_d','unit_review','M6-2-u5-C3',4,'essay','teacher','바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 굴렁쇠가 굴러간 거리는 몇 m인지 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u5-C3","difficulty":4,"kind":"essay","stem":"바깥쪽 원의 지름이 48 cm인 굴렁쇠를 5바퀴 굴렸어요. 굴렁쇠가 굴러간 거리는 몇 m인지 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 한 바퀴 굴러간 거리는 원주이므로 48 × 3.14 = 150.72 cm이다. 5바퀴면 150.72 × 5 = 753.6 cm이고, 100 cm = 1 m이므로 7.536 m이다.","scoring_points":["한 바퀴 거리가 원주임을 밝혔는가","753.6 cm를 구했는가","m로 바꾸어 7.536 m를 구했는가"]},"explanation":["원주는 150.72 cm예요.","5바퀴는 753.6 cm예요.","7.536 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
